window.__D("text/likkutei-sichot/c012",{"p":[[1301430172,"השליחות, דשלוחו של אדם כמותו, שיש לבארו בכמה אופנים:\nא) \"כמותו\" ממש<sup data-n=\"951\">11</sup> — בנוגע לעושה המעשה, שגוף השליח הוא כגוף המשלח (ובדרך ממילא מתייחסת עשיית השליח למשלח).\nב) \"כמותו\" — (רק) בשייכות לכח ה­עשי' דהשליח או להמעשה, דעשיית ה­שליח היא כמו עשיית המשלח.\nג) \"כמותו\" — רק בנוגע לתוצאות ה­מעשה. בלשון אחר: להחפצא בו נעשה העשי' — שגם עשייתו של השליח אינה דהמשלח, אלא שעשיית השליח בהחפצא ה\"ז (פועלת אותו הדבר שפועלת) עשיית המשלח.\nועפ\"ז יש לומר, דדעת רב אשי היא כאופן הג' הנ\"ל, שגם מעשה השליחות אינו מתייחס להמשלח אלא להשליח, ו­מכיון שאין השליח עומד במקום המשלח (אפילו לא שמעשהו יחשב כמעשה ה­משלח), לכן, אם הוא רק בן אדם השייך לעשי' זו יכול להיות שליח, של זה ה­מבקשו ומקשרו עם פעולה זו, וע\"ד ש­מקשרו בחבל ואינו מתנגד לזה.\nולכן ס\"ל שבכל התורה כולה יש שליחות לנכרי, דאם השליחות היא ב­ענין כזה שגם הנכרי שייך לעשייתו<sup data-n=\"952\">12</sup>, הרי הוא יכול להיות שליח לישראל.\nאמנם מסקנת הגמ' היא, ד\"הא דר\"א ברותא היא\", ששיטה זו מופרכת, והכרח שהשליח יהי' דומה להמשלח (\"מה אתם כו' אף שלוחכם כו'\"). היינו, שגם את\"ל שענין שליחות הוא כאופן הג' הנ\"ל, שה­עשי' היא מעשה השליח — מ\"מ, ענין ה­שליחות לא יתכן אלא במי שהוא \"כמותו דהמשלח\"<sup data-n=\"953\">13</sup>, וזהו ע\"פ כל האופנים ש­מבארים ענין השליחות.\nהסברת הענין:\nבשליחות יש שני ענינים: (א) קיום השליחות בפועל. (ב) חלות שם שליח.\nכל שלשת האופנים הנ\"ל בגדר ה­שליחות הם רק בנוגע לקיום השליחות בפועל: כאשר דנים איך מועיל מעשה איש זה (השליח) עבור איש אחר (ה­משלח) — אז יתכן לומר הטעם בזה בג' אופנים, אם משום שחדשה תורה בשלי­חות שמעשה השליח מועיל כמעשה ה­משלח, או מטעם שעשייתו זו נחשבת כעשיית המשלח, או יתירה מזו, שגוף השליח נחשב כגוף המשלח ובמילא מעשהו כמעשה המשלח.\nאבל קודם לכן צ\"ל חלות של שלי­חות על השליח, היינו המינוי הפועל חלות שם שליח<sup data-n=\"954\">14</sup>. וכדי שיחול עליו שם שליח, צ\"ל קשר בין השליח והמשלח, כי אא\"פ להיות שלוחו של המשלח (באיזה אופן שהוא) מבלי שיהי' \"כמותו דה­משלח\", ש\"צריך להיות השליח מתייחס בערך מה\"<sup data-n=\"955\">15</sup> להמשלח.\nולכן אין שליחות לנכרי בכל התורה",[["951","11","ראה שו\"ת הריב\"ש סי' רכח. וראה הערה 13."],["952","12","שהרי צ\"ל ב\"תורת\" אותו דבר כדי להיות שליח בדבר (קידושין שם. גיטין כג, א וברש\"י שם. ועוד)."],["953","13","ל' אדה\"ז בלקו\"ת ויקרא (א, ג) — היינו שהפירוש ב\"שלוחו של אדם כמותו\" הוא לא רק בנוגע לדין השליחות, אלא גם בנוגע למהות ה­שליח, שצ\"ל \"כמותו דהמשלח\", כדלקמן. וראה לקמן סעיף ד."],["954","14","להעיר מצפע\"נ (להל' אישות פ\"ג הט\"ו. השמטות להל' מת\"ע — ג, א) אם השליח יש עליו שם שליח תיכף או לאחר שהתחיל לעשות הדבר. ע\"ש."],["955","15","ל' אדה\"ז בלקו\"ת שם."]]],[1301430173,"כולה, כי אינו יכול להיות \"כמותו דה­משלח\"<sup data-n=\"956\">16</sup> (הישראל).\nג. ע\"פ ההסבר הנ\"ל בדברי רב אשי, יש לבאר עוד מאמר של ר\"א בענין השליחות, שמצינו ג\"כ שנפרך להלכה — בדין שליח עושה שליח, שיכול לעשות כמה שלוחין<sup data-n=\"957\">17</sup> (\"אפילו מאה\"<sup data-n=\"958\">18</sup>), דס\"ל לרב אשי<sup data-n=\"957\">17</sup> ש\"אם מת (שליח) ראשון בטלו כולן, אמר מר בר רב אשי הא דאבא דקטנותא היא (בקטנותו אמר אבי שמועה זו שיש להשיב עלי'<sup data-n=\"960\">19</sup>) אילו מת בעל מידי מששא אית בהו כולהו מכח מאן קאתו מכח דבעל קאתו איתי' לבעל איתנהו לכולהו ליתי' לבעל ליתנהו ל­כולהו\".\nוהנה באחרונים<sup data-n=\"961\">20</sup> כתבו שפלוגתת ר\"א ומר בר\"א (אם קאתו מכח שליח ראשון או מכח הבעל) היא, דמר בר\"א ס\"ל דהשליח הוא כהמשלח עצמו או עכ\"פ שמעשהו מתייחס להמשלח, ונמצא שהשליח הראשון (וכמוהו כל השלוחים אחריו) קאתי מכח הבעל המשלח שהרי הוא עומד במקומו; משא\"כ ר\"א ס\"ל שה­שליח אינו כהמשלח עצמו, וגם מעשהו אינו מתייחס למשלח ורק מועיל עבור המשלח, וא\"כ השליח השני לא נעשה שליח מכח המשלח אלא מכח שליח הראשון.\nאבל צ\"ע בזה, שהרי מלשון מר בר\"א \"הא דאבא דקטנותא היא\" מובן, שסברת ר\"א מופרכת להלכה (וכן נפסק ל­הלכה<sup data-n=\"962\">21</sup> כמר בר\"א). והרי הביאו האחרו­נים<sup data-n=\"963\">22</sup> כמה ראיות (גם) כצד זה בשליחות שהמעשה לא נחשב אלא כעשיית ה­שליח.\nולכן נראה לומר, דגם כאן שיטת ר\"א היא לא רק מטעם שמעשה השליח לא נחשב כעשיית המשלח (ורק שעשייתו מועלת עבור המשלח), אלא משום דס\"ל יתירה מזו, שמכיון שכל ענין השליחות הוא רק בשייכות לתוצאות המעשה בה­חפצא (כנ\"ל), א\"צ להיות שום ערך בין השליח והמשלח. כלומר: לאחרי שה­משלח עשאו שליח שוב לא אתי השליח מכח המשלח אלא \"כח\" השליחות נמצא אצלו, וכאילו הוא הבעלים על דבר זה. ומטעם זה ס\"ל ש\"אם מת (שליח) ראשון בטלו כולן\", כי השלוחים לא אתו מכח המשלח אלא מכח השליח הראשון<sup data-n=\"964\">23</sup>.\nוזהו מה שאמר מר בר\"א דסברא זו מופרכת לגמרי — הא דאבא דקטנותא היא — כי \"כולהו מכח מאן קאתו מכח דבעל קאתו\", כלומר: גדר שליחות הוא מה ש\"אתי מכח\" המשלח (דעצם תואר שליח פירושו — שהוא כחו של המשלח), שלוחו של אדם כמותו, ולכן אא\"פ לייחס את ענין השליחות למי שהוא (שליח ראשון וכו') מבלי שבא ונמשך מ­",[["956","16","בשו\"ת משאת בנימין סצ\"ו (הובא בש\"ך חו\"מ סרמ\"ג סק\"ה) ועוד, שלכן גוי נעשה שליח לגוי מכיון שהם דומים. — הדיעות בזה ראה שד\"ח כללים מערכת א ס\"מ. אנציקלופדי' תלמודית ערך גוי (ע' שלו). וש\"נ."],["957","17","גיטין כט, ב."],["958","18","ל' הרמב\"ם הל' גירושין פ\"ז ה\"ד. שם הכ\"ב. וראה רש\"י גיטין שם: וכן לעולם."],["957","17","גיטין כט, ב."],["960","19","רש\"י."],["961","20","לקח טוב שם (אות ד)."],["962","21","רמב\"ם הל' גירושין פ\"ז ה\"ד. טושו\"ע אה\"ע סקמ\"א סמ\"א."],["963","22","ראה לקח טוב כלל הנ\"ל. ועוד."],["964","23","ומה שכל השלוחים שלאחריו תלויים בשליח ראשון (שאם מת שליח ראשון בטלו כולן) — ולא אמרינן דכשם ששליח ראשון לא אתי אלא מכח הבעל, כך שלוחים האחרונים לא אתו אלא מכח שליח שלפני כאו\"א — י\"ל, כי ענין השליחות נתחדש ע\"י שליח הראשון ודי בזה. וראה לקח טוב שם."]]],[1301430174,"הבעל — המשלח. ואף את\"ל שמעשה השליחות (ואפילו הפעולה דמינוי השלי­חות) נחשב כאילו עשאו השליח (כאופן הג' הנ\"ל) — מ\"מ אין הוא הבעלים כלל על הענין ד\"כולהו. . (רק) מכח דבעל קאתו\"<sup data-n=\"965\">24</sup>, וכנ\"ל בארוכה.\nד. ע\"פ הנ\"ל יומתק זה שהלימוד למעט נכרים מדין שליחות — \"מה אתם בני ברית כו'\" — נאמר גבי תרומה, ולא גבי גירושין וכיו\"ב [שגם בהם נאמר דין שליחות<sup data-n=\"966\">25</sup>]:\nיש חילוק עיקרי בין ענין השליחות בהפרשת תרומה והשליחות בשאר עני­נים — גירושין וכו':\nבהפרשת תרומה העיקר הוא הנפעל, זה שהתרומה נפרשת מהתבואה, ולכן הסברא נותנת שענין השליחות בתרומה אצ\"ל באופן ש(יהי' נחשב כאילו) ה­משלח (בעל התבואה) עשה פעולת ה­הפרשה, אלא דמכיון שהוא הבעלים של התבואה ע\"כ צ\"ל ההפרשה מדעתו — ואע\"פ שהיא פעולת השליח<sup data-n=\"967\">26</sup>.\nמשא\"כ גבי גירושין הרי פשוט שה­מגרש צ\"ל הבעל דוקא, כי גירושין הוא (לא רק הפעולה של כתיבת ונתינת הגט, אלא בעיקר) שהבעל מגרש את אשתו, ומובן ששליחות בגט פירושה שע\"י עשיית השליח נחשב שהבעל גירש את אשתו.\nולפ\"ז, אי כתב רחמנא דינא ד\"מה אתם בני ברית כו'\" גבי גירושין וכיו\"ב הי' קס\"ד לומר שהוא רק בדברים הדור­שים פעולת הבעלים ובמילא צריך ה­שליח להיות דומה להמשלח (הבעלים) שאז ראוי הוא לעמוד במקום הבעלים;\nולכן נאמר דין זה דוקא גבי תרומה, ללמדנו, שכל ענין של שליחות (באיזה ענין שהוא) — גם בתרומה שבה אנו דנים רק על העשי' והפעולה שתועיל עבור הישראל — לא יתכן חלות שם שליח אם אין השליח דומה למשלח (\"מה אתם כו' אף שלוחכם כו'\"), כי עיקר ענין ה­שליחות הוא זה שהשליח הוא \"כמותו דהמשלח\".\nה. ויש להביא ראי' לענין זה מדברי רבינו הזקן, שבנוגע לענין השליחות כותב<sup data-n=\"968\">27</sup> \"דשלוחו של אדם כמותו, ולכן אין שליחות לחרש שוטה וקטן שאינן כמותו דהמשלח\".\nולכאורה צ\"ע, שהרי מפורש בגמ'<sup data-n=\"969\">28</sup>",[["965","24","ועפ\"ז מובנת אריכות ל' מר בר\"א \"אילו מת בעל מידי מששא כו' כולהו מכח מאן כו' איתי' לבעל כו'\" [ועוד — לכאורה הו\"ל להדגיש ולהסביר איך לא בטלו כולן במיתת שליח הראשון שב­אמצעותו נעשו הם שלוחים] — אלא שמר בר\"א בא להדגיש, שכל \"כח\" השליחות אינו אלא דהמשלח (\"מכח דבעל קאתו\") ואין להשליח שייכות ל\"כח\" השליחות.\n[וכבר הקשו באחרונים מכאן על מ\"ש בקצוה\"ח (סרפ\"ח סק\"ב) שלדעת הרמב\"ם (הל' גירושין פ\"ב הט\"ו) גם אם מת המשלח לא בטלה השליחות. ואכ\"מ]."],["966","25","ראה קידושין מ, א (ואילך). וראה לעיל הערה 6.\nבפשטות י\"ל שאא\"פ לכתוב דין זה בגירושין מפני שעכו\"ם אינן בתורת גירושין וקידושין (ראה הנסמן בהערה 12). אבל ראה תוס' גיטין (שם ע\"ב ד\"ה מה אתם) דגם לר\"ש דס\"ל שעכו\"ם שתרם אין תרומתו תרומה ילפינן מתרומה לכל התורה כולה דאין שליחות לנכרי (ע\"ש) — וא\"כ ה\"ה דאפשר לכתוב דין זה בגירושין."],["967","26","ולהעיר מדעת הרמב\"ן (גיטין סו, ב — הובא בר\"ן שם (והקשה עליו). וראה ר\"ן נדרים לו, ב ד\"ה הכא נמי) ד\"גבי תרומה אפילו גלוי מילתא נמי מהני\" (וא\"צ שליחות גמורה). ע\"ש. ואכ\"מ."],["968","27","לקו\"ת ויקרא א, ג."],["969","28","גיטין כג, א. וראה רש\"י שם (וכ\"ה ברש\"י קידושין מב, א ד\"ה והא. ועוד) ד\"גבי שליחות איש בעינן\"."]]],[1301430175,"שהטעם שאינן בני שליחות הוא משום \"דלאו בני דיעה נינהו\"<sup data-n=\"970\">29</sup>?\nואף שי\"ל שזהו פירוש דברי הגמ', ד­מכיון שאינן בני דיעה נמצא שאינן \"כמותו דהמשלח\"<sup data-n=\"971\">30</sup> — מ\"מ צריך ביאור מהו ההכרח לפירוש זה?\nוע\"פ הנ\"ל י\"ל:\nידוע הכלל<sup data-n=\"972\">31</sup> דקטן אין לו כוונה, אבל יש לו מעשה. ועפ\"ז, את\"ל שענין השליחות אינו זה שהשליח עומד במקום המשלח, אלא רק שעשייתו מועלת עבור המשלח, א\"כ בדברים שאינם צריכים כוונה אלא עשי' בלבד, אין טעם לכאו­רה שלא יהי' דין שליחות לקטן<sup data-n=\"973\">32</sup>?\nוזהו שדייק רבינו הזקן לומר דמה שחש\"ו אינן בני שליחות הוא מפני שאינן \"כמותו דהמשלח\" — שלכן הם מופקעים בעצם מגדר השליחות. כלומר: אף שב­נוגע למעשה השליחות הי' מקום לומר שישנם בשליחות, שעשייתם תועיל עבור המשלח, מ\"מ, אין הם בתורת שליחות, כי אא\"פ שיחול עליהם שם שליח, מאחר שאינם \"כמותו דהמשלח\".\nו. דין שליחות בפשטות, בין אדם ל­חבירו, נמשך ומשתלשל מענין השליחות בין אדם למקום, בין ישראל לאביהם ש­בשמים:\nכאו\"א מבנ\"י ה\"ה שלוחו של הקב\"ה, שלוחו של אדם — העליון — כמותו<sup data-n=\"974\">33</sup>, ל­השלים כוונת הבריאה על ידי העבודה בקיום התומ\"צ.\nוכמו שיש ג' אופנים בדין שליחות הנ\"ל, כן הוא גם בעבודת האדם, שישנם ג' דרגות באופן מסירת וביטול השליח (האדם) אל המשלח (הקב\"ה):\nיש דרגא בעבודת השם, שהאדם ה­עובד — בהרגשתו ה\"ה מציאות בפני עצמו בכל עניניו, אלא שהוא כופה עצמו לקיים רצונו ית' — בעשיותיו הוא ממלא שליחותו של הקב\"ה;\nויש מי שפועל בעצמו ביטול פנימי, עד שעשיותיו מתייחסות להמשלח, כלו­מר, מעשיו ועניניו (בענין השליחות) ה\"ה מסורים ונתונים להשם עד שפעולותיו אלו אינן מציאות בפ\"ע ואינן אלא כח המשלח;\nולמעלה מזה הוא מי שהוא בטל ל­גמרי להקב\"ה, עד שכל מציאותו (ובדרך ממילא כל עשיותיו) אינה אלא מציאות המשלח.\nאמנם כל דרגות אלו הן רק בשייכות לקיום השליחות, אבל זה שכ\"א מישראל יש ביכלתו לקיים שליחות זו (באיזה אופן שהוא), הוא מפני שחל עליו שם \"שליח\"; וחלות שם זה יכולה להיות רק על בני ישראל (ולא באוה\"ע להבדיל) כי רק בבנ\"י יתכן לומר שהם \"כמותו דה­משלח ממש\"<sup data-n=\"975\">34</sup>; והיינו לפי שנשמות ישראל הם \"חלק ה' עמו\"<sup data-n=\"976\">35</sup>, חלק אלקה",[["970","29","להעיר מחי' רעק\"א לגיטין כג, א (וכן לכתובות יא, א) ד\"היכא דא\"צ דעתו שיעשה שליח גם לקטן יש שליחות (שיכול לעשות שליח) וזהו דאמרינן כיון דלאו בני דיעה נינהו\"."],["971","30","ראה תוס' רי\"ד ומאירי (למשנה) גיטין שם. תוד\"ה שאני גיטין סד, ב. ראב\"ד הל' גירושין פ\"ו ה\"ט. ולהעיר מנתיבות המשפט סקפ\"ב סק\"א."],["972","31","חולין יב, ב ואילך."],["973","32","להעיר ממעילה כא, א. נתה\"מ שבהערה 30. ואכ\"מ."],["974","33","ראה לקו\"ת שם."],["975","34","ל' אדה\"ז בלקו\"ת שם (בנוגע לשלוחו של אדם התחתון. אבל מהמשך הענין שם מובן דכ\"ה גם בשליחות דנש\"י מ\"קדש העליון\")."],["976","35","האזינו לב, ט. וראה אגה\"ת פ\"ד (צג, סע\"ב)."]]],[1301430176,"ממעל ממש<sup data-n=\"977\">36</sup>, ולכן רק להם יש יחס \"בערך מה\" לגבי הקב\"ה, המשלח, ועד שהם \"כמותו דהמשלח ממש\".\n[וזה מרומז גם במרז\"ל \"מה אתם בני ברית כו'\"<sup data-n=\"978\">37</sup> — שכל בנ\"י הם \"בני ברית\" עם הקב\"ה, שזהו עצם מציאותו של איש ישראל (השווה בכאו\"א בישראל) שהוא נכלל ב\"בני ברית\", דהיינו הקשר וה­ברית בין ישראל ואביהם שבשמים].\nומכל זה למדנו הוראה בפועל בעבו­דת השם:\nגם מי שעבודתו עדיין בדרגא ה­פחותה ביותר, שהוא מציאות בפ\"ע ורק שעשייתו היא עבור השם, מ\"מ, מכיון שעצם מציאותו היא \"כמותו דהמשלח ממש\", יש ביכלתו — ולכן צריך הוא — להכניס גם בעבודתו זו חיות מעצם נפשו.\nז. והנה אע\"פ שדברי רב אשי (דיש שליחות לנכרי, וכמשנת\"ל טעם הדבר, דס\"ל שאין השליח צ\"ל \"כמותו דה­משלח\") נדחו להלכה עד שאמרו \"ברותא היא\" — מ\"מ, מזה גופא שגם דבריו הוכנסו בתורת אמת, עכצ\"ל שיש גם להם מקום<sup data-n=\"979\">38</sup>.\nוי\"ל הביאור בזה — בעבודת האדם:\nבעבודת האדם לקונו ישנו עילוי כש­השליח הוא מציאות בפ\"ע (נפרד מה­משלח)<sup data-n=\"980\">39</sup> — כי אז יש בעבודתו בגלוי ה­מעלה ד\"קב שלו\", ואמרז\"ל<sup data-n=\"981\">40</sup> שע\"פ טבע בריאתו \"אדם רוצה בקב שלו מתשעה קבים של חבירו\", וכמו שרואים במוחש, דכאשר הרגשת האדם ביחס לדבר מ­סויים היא שזהו ענין הנוגע לו ה\"ז מעורר אצלו יגיעה גדולה יותר, וכן יש לו בזה יותר תענוג<sup data-n=\"982\">41</sup> וכו'.\nוכן בעבודה רוחנית, דכאשר עבודתו היא באופן שאינו מרגיש את מציאותו וחושב רק אודות המשלח [או אפילו בדרגא הפחותה בשליחות, שנחשב ל­עשיית השליח אלא שעשייתו היא בשביל המשלח], ה\"ז יכול לגרום לחלי­שות בענין היגיעה.\nולדוגמא: כאשר התייגע בכל כחו, ומ\"מ הענין לא נשלם עדיין, שאז אפשר שיעלה במחשבתו, דמכיון שהוא עשה את כל אשר ביכלתו, והענין ה\"ה של ה\"משלח\" (הקב\"ה), הרי הוא את שלו עשה, והשאר — ישלים המשלח.\nולכן יש מעלה בהרגשה שישנה מצי­אות השליח, אשר דבר השליחות נמסר לו וזהו ענין שלו, ובמילא הדבר נוגע לו במיוחד.\n[וכידוע המשל בזה — מהחילוק שבין מסירותו של פקיד או שכיר העושה ענין באמונה, למסירותו של בעל הבית באותו ענין: הפקיד, מכיון שעושה מלאכתו ב­אמונה עובד ככל יכולתו בכחות ה­גלוים, ואח\"כ הולך לעסקיו במנוחה, מ­כיון שבאמת עשה כל המוטל עליו; משא\"כ הבעה\"ב — שאינו יכול לישון במנוחה, אף אם עשה ככל יכולתו,",[["977","36","תניא רפ\"ב."],["978","37","להעיר מגיטין כג, ב: מאי טעמא לאו. . מה אתם ישראל. . לא מה אתם בני ברית."],["979","38","וראה לקוטי לוי\"צ אגרות (ע' רסו): וכן ההלכה שעלי' אמרו אח\"כ שבדותא (ברותא) היא. . כולם ממש אמר ה' ובאותו הלשון ממש. . וה' עצמו אומר ההלכה והוא עצמו אמר שבדותא היא."],["980","39","להעיר מהסברא דמשלוח מנות צ\"ל דוקא ע\"י שליח (ראה שד\"ח אסיפת דינים מערכת פורים סוס\"ו)."],["981","40","ב\"מ לח, א."],["982","41","ראה פרש\"י שם: חביבה עליו ע\"י שעמל כו'."]]],[1301430177,"ובמילא מתגלים אצלו כחות נעלמים וכו'].\nח. אלא שמ\"מ מסקנת הגמ' היא \"הא דר\"א ברותא היא\", כי אע\"פ שיש מעלה בהרגשת מציאות השליח, אין זה סותר ח\"ו לענין \"שלוחו של אדם כמותו\", שה­שליח צ\"ל בטל אל המשלח.\nהסברת הענין:\nזה גופא שצ\"ל מציאות של שליח (נפרד מהמשלח), ה\"ז גופא רק מפני שזהו רצון ותענוג המשלח — כי דוקא עי\"ז \"נחת<sup data-n=\"983\">42</sup> רוח לפני שאמרתי ונעשה רצוני\".\nומזה מובן, שבעומק הענין, מציאותו של השליח (אינה מציאות בפ\"ע, אלא היא) מתאחדת עם מציאותו של המשלח להיות מציאות אחת.\n[ואדרבה — זה גופא הוא החידוש ב­ענין השליחות, שהשליח צ\"ל איש בר דעת בפני עצמו (ולא קטן<sup data-n=\"984\">43</sup>), שנמסר לו כחו ותוקפו של המשלח, ומ\"מ כל כחו (בענין השליחות) קאתי מכח המשלח].\nונמצא, שאין כאן דרגא ואופן בשלי­חות שהשליח נשאר (באמת) מציאות בפני עצמו, אלא דבר זה (שהשליח צ\"ל מציאות בפני עצמו) הוא פרט נוסף ב­ענין השליחות (דשלוחו של אדם כמו­תו), שכדי שיושלם רצון המשלח כדבעי צ\"ל מעשה השליחות נעשה על ידי מציאות השליח (עד שמרגיש את עצמו כבעל הדבר).\nוזהו גם הרמז בלשון חז\"ל (הנ\"ל) \"אדם רוצה בקב שלו מתשעה קבים של חבירו\":\n\"אדם\" ו\"חבירו\" קאי על ישראל ו­הקב\"ה (\"ריעך. . זה הקב\"ה\"<sup data-n=\"985\">44</sup>), שעל ידי שניהם יחד ישנם עשרה קבים, ה­מורה על שלימות (דעשר הוא מספר השלם<sup data-n=\"986\">45</sup>).\nוכדי להגיע לשלימות זו צ\"ל החיבור דה\"קב שלו\" של האדם וה\"תשעה קבים של חבירו\" — כלומר, מחד גיסא צ\"ל יגיעת האדם, שבזה מרגיש שזהו שלו (\"קב שלו\"), וביחד עם זה צריך להכיר שכל עבודתו (כולל זה שיש \"קב שלו\") היא בשביל \"חבירו\", וע\"י צירוף שניהם יחדיו<sup data-n=\"987\">46</sup> — ישנם כל העשרה קבים.\n<span data-k=\"q\">(משיחות כ\"ף מנ\"א תשמ\"ה, כ\"א מנ\"א תשד\"מ)</span>",[["983","42","ספרי (ורש\"י) פינחס כח, ח. ובכ\"מ."],["984","43","להעיר מהא דקטן עושה על דעת גדול ה­עומד על גביו (גיטין כג, רע\"א. ועוד. וראה אנציקלופדי' תלמודית ערך חש\"ו ס\"ה. וש\"נ)."],["985","44","שמו\"ר ר\"פ כז. רש\"י ד\"ה דעלך שבת לא, א."],["986","45","ראה ראב\"ע שמות ג, טו. פרדס ש\"ב."],["987","46","ע\"ד תורת הה\"מ (אור תורה מה, ד ואילך) שישראל והקב\"ה הם כמו \"שתי חצאי צורות\", ד\"כשיתדבקו יחד נעשה צורה שלימה\".\nולהעיר ממשנ\"ת בביאוה\"ז לאדהאמ\"צ (בשלח מג, ג) דיש הנברא ויש האמיתי חד הם. ע\"ש."]]],[1301430178,"<h3>שיחה ג</h3>\nא. עה\"פ בסיום פרשתנו<sup data-n=\"988\">1</sup> \"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\" איתא בספרי: \"מנין אתה אומר שאם הפרשתם אותו שלא מן המובחר<sup data-n=\"989\">2</sup> שאתם בנשיאות עון ת\"ל ולא תשאו עליו חטא\".\nובגמרא<sup data-n=\"990\">3</sup> אמרו: \"א\"ר אילעאי מנין לתורם מן הרעה על היפה שתרומתו תרומה דכתיב ולא תשאו עליו חטא בהרימכם את חלבו ממנו [הא אם לא תרימו מן המובחר תשאו חטא. רש\"י], ואם אין קדוש נשיאות חטא למה, מיכן לתורם מן הרעה על היפה שתרומתו תרומה\".\nולכאורה נראה שיש כאן פלוגתא בין הגמ' והספרי, שבגמ' נאמר רק האיסור לתרום מן הרעה על היפה, ומשמע מזה שאין איסור לתרום מן הרעה על הרעה (וכן מן הבינונית על הבינונית)<sup data-n=\"991\">4</sup>; משא\"כ מלשון הספרי מבואר שהתרומה עצמה צריכה תמיד להיות \"מן המובחר\". וכן משמע גם מלשון הספרי לעיל עה\"פ<sup data-n=\"992\">*4</sup> \"בהרימכם את חלבו ממנו ונחשב ללוים גו'\" — \"הרי זו אזהרה. . שלא יהו תורמים אותו אלא מן המובחר<sup data-n=\"989\">2</sup>\".\n[ואע\"פ שאם אין לו אלא בינונית או רעה הרי חיוב התרומה חל רק על ה­פירות שיש לו, ואין לחייבו להשיג יפות כדי לתרום מן המובחר — מ\"מ נפק\"מ באם יש לאדם תבואה יפה ותבואה רעה ורוצה לתרום מכל סוג בפני עצמו, מן היפה על היפה ומן הרעה על הרעה, שלשיטת הש\"ס אין בכך איסור, משא\"כ להספרי שצ\"ל מן המובחר דוקא<sup data-n=\"991\">4</sup>].\nובזה יש לבאר עוד שינוי בלשון ה­ספרי מלשון הש\"ס, שבספרי הלשון \"שלא מן המובחר\"<sup data-n=\"995\">5</sup>, \"לא יהו תורמים אותו אלא מן המובחר\", דלא כלשון הש\"ס \"על היפה\": בש\"ס ההדגשה היא על החילוקים בטיב התבואה והפירות, אם הן \"רעות\" או \"יפות\", ולכן נקט \"יפה\" בניגוד ל\"רעה\" [ע\"ד שמצינו לענין שיעור תרומה<sup data-n=\"996\">6</sup>, \"עין יפה\", \"בינונית\" או \"רעה\"]; משא\"כ כוונת הספרי שלעולם חייבים לתרום \"מן המובחר\", והיינו שגם כשתורם מן היפה על היפה, הרי מבין היפות גופא צריך לתרום את המובחר ביותר<sup data-n=\"997\">7</sup>, ולכן נקט \"מובחר\" [ע\"ד הלשון",[["988","1","יח, לב."],["989","2","כ\"ה ביל\"ש, רמב\"ם (סהמ\"צ מ\"ע קכט. וראה הערה 5), רמב\"ן שהובא לקמן (ס\"ג) ועוד (ראה ספרי הוצאת האראוויטץ. ועוד). ובדפוס ראשון ועוד \"מן המחובר\". וראה מפרשי הספרי."],["990","3","יבמות פט, ב. וש\"נ."],["991","4","לכאורה י\"ל, דאם אינו תורם מן היפה ב­יותר, ממילא הוי מן הרע על היפה (כי כל שיש יפים ממנו ה\"ז בגדר רע לגבי היפים). וראה ל' רש\"י ד\"ה בהרימכם (קידושין מו, סע\"ב) \"הא אם תרימו את הרעה שבו\".\nאבל מהדוגמאות שהובאו במשנה (תרומות פ\"ב מ\"ה ואילך), תוספתא (שם פ\"ד), מנחות (נה, א) ועוד — שהם מסוג א' על סוג השני (ולא שבסוג זה גופא צריכים לתרום מן המובחר שבו) משמע, שהכוונה ב\"רע על היפה\" היא רק — שאין לתרום מסוג רע על סוג יפה. וראה לקמן סעיף ג."],["992","*4","יח, ל."],["989","2","כ\"ה ביל\"ש, רמב\"ם (סהמ\"צ מ\"ע קכט. וראה הערה 5), רמב\"ן שהובא לקמן (ס\"ג) ועוד (ראה ספרי הוצאת האראוויטץ. ועוד). ובדפוס ראשון ועוד \"מן המחובר\". וראה מפרשי הספרי."],["991","4","לכאורה י\"ל, דאם אינו תורם מן היפה ב­יותר, ממילא הוי מן הרע על היפה (כי כל שיש יפים ממנו ה\"ז בגדר רע לגבי היפים). וראה ל' רש\"י ד\"ה בהרימכם (קידושין מו, סע\"ב) \"הא אם תרימו את הרעה שבו\".\nאבל מהדוגמאות שהובאו במשנה (תרומות פ\"ב מ\"ה ואילך), תוספתא (שם פ\"ד), מנחות (נה, א) ועוד — שהם מסוג א' על סוג השני (ולא שבסוג זה גופא צריכים לתרום מן המובחר שבו) משמע, שהכוונה ב\"רע על היפה\" היא רק — שאין לתרום מסוג רע על סוג יפה. וראה לקמן סעיף ג."],["995","5","בסהמ\"צ להרמב\"ם שם לפנינו (מספרי) \"מן היפה\". אבל בסהמ\"צ הוצאת העליר וקאפח — \"מן המובחר\"."],["996","6","תרומות פ\"ד מ\"ג. ובכ\"מ."],["997","7","ראה גם של\"ה חלק תושב\"כ סוף פרשתנו."]]],[1301430179,"אצל קרבנות שצ\"ל<sup data-n=\"998\">8</sup> \"תמימין ומובחרין\", \"מן המובחר\"].\n[ויש לומר, שהספרי יליף דין זה מלשון הכתוב \"חלבו ממנו\", דלכאורה תיבת \"ממנו\" מיותרת. ובספרי לעיל עה\"פ<sup data-n=\"999\">9</sup> \"והרמותם ממנו\" — \"ממין על מינו ולא ממין על שאינו מינו\", שמפרש \"ממנו\" — \"ממינו\"<sup data-n=\"1000\">10</sup>. ועפ\"ז י\"ל, שלספרי הפירוש ב\"חלבו ממנו\" היינו שגם אם הוא \"ממינו\", צ\"ל מן המובחר שבו, דהיינו מובחר מן היפות גופא].\nב. אלא שלכאורה יש לעיין אם יש לפרש דהש\"ס פליג על הספרי בזה, ש­הרי שנינו בפירוש<sup data-n=\"1001\">11</sup> \"כל מקום שיש כהן תורם מן היפה\" (ורק כשאין כהן \"תורם מן המתקיים\", ולדעת ר' יהודה<sup data-n=\"1001\">11</sup> \"לעולם הוא תורם (רק) מן היפה\"), ועכצ\"ל שגם לשיטת הש\"ס החיוב ד\"בהרימכם את חלבו ממנו\" אינו רק איסור לתרום מן הרעה על היפה, אלא שחייבים לתרום \"מן היפה\".\nוכן שנינו<sup data-n=\"1003\">12</sup> \"וכל שאינו כלאים ב­חברו תורם מן היפה על הרע\", הרי שהחיוב לתרום \"מן היפה\" פירושו גם \"מן היפה על הרע\", ואין תורמין מן הרע על הרע.\nאיברא שבמשנה שם ממשיך \"(תורם מן היפה על הרע) אבל לא מן הרע על היפה\", וע\"פ הנ\"ל הו\"ל להתנא לומר רק \"אבל לא מן הרע\" שאז ה\"ז כולל גם לא מן הרע על הרע, ומשמע לכאורה, שה­איסור הוא רק \"מן הרע על היפה\". אבל י\"ל דהא שנקט התנא \"אבל לא מן הרע על היפה\" הוא מחמת המשך דבריו, \"ואם תרם מן הרע על היפה תרומתו תרומה\", ולכן נקט \"מן הרע על היפה\" להשמיענו חידוש, שגם באופן כזה, שלא רק שלא תרם מן היפה, אלא עוד זאת, שתרם מן הרע על היפה, מ\"מ בדיעבד תרומתו תרומה. אבל לכתחילה אסורים לתרום (לא רק מן הרע על היפה, אלא) אפילו מן הרע על הרע.\nוזהו גם הטעם שבש\"ס שם נקט ר' אילעאי \"תורם מן הרעה על היפה\" (ש­הוא ב\"נשיאות חטא\"), דלא כלשון ה­ספרי \"שהפרשתם אותו שלא מן המו­בחר\" — שאין צ\"ל שזוהי פלוגתא, אלא טעם השינוי, כי כוונת ר' אילעאי ל­השמיענו (לא עצם הדין שהוא בנשיאות חטא, אלא) הדין ש\"תרומתו תרומה\", ובזה חידוש יותר בתורם מן הרע על היפה; משא\"כ הספרי שבא להשמיענו עצם הדין שהוא \"בנשיאות עון\", סתם וכתב \"שלא מן המובחר\", שזהו החידוש, דאפילו אם רק לא הפריש מן המובחר, יש עליו נשיאות עון<sup data-n=\"1004\">13</sup>.\nג. אבל דוחק לפרש כן שיטת הש\"ס, כי בכ\"מ שמצינו במשנה וגמ' האיסור שלא יתרום מן הרע, נאמר \"לא מן הרע על היפה\"<sup data-n=\"1005\">14</sup> [או לא ממין פלוני (שהוא רע) על מין פלוני (שהוא טוב)<sup data-n=\"1006\">15</sup>] — אף שבמקומות אלה לא נזכר כלל הדין שבדיעבד תרומתו תרומה. ומשמע, שה­איסור הוא רק מן הרע על היפה.",[["998","8","רמב\"ם ריש הל' איסורי מזבח. שם רפ\"ז."],["999","9","יח, כו. — ולהעיר שבש\"ס (בכורות נג, סע\"ב. תמורה ה, א) יליף דין זה מ\"כל חלב יצהר וכל חלב תירוש ודגן\" (פרשתנו יח, יב)."],["1000","10","כ\"פ בתולדות אדם לספרי שם. מלבי\"ם שם."],["1001","11","תרומות פ\"ב מ\"ד."],["1001","11","תרומות פ\"ב מ\"ד."],["1003","12","שם מ\"ו."],["1004","13","וראה לקמן ס\"ז."],["1005","14","בתמורה (ה, א) \"חלבו אין גירועין לא\" — אבל גם שם מתחיל \"והרי תורם מן הרעה על היפה דרחמנא אמר מכל חלבו כו'\"."],["1006","15","ראה הנסמן לעיל הערה 4."]]],[1301430180,"ולכאורה יש לדייק כן מלשון ה­רמב\"ן בהשגותיו על ספר המצות לה­רמב\"ם, שמוסיף במנין מצות עשה<sup data-n=\"1007\">16</sup> \"שנצטוינו בהפרישנו תרומה שנפריש אותה מן היפה או מן השוה לא מן הרע על היפה\" (וכן מוסיף במנין הל\"ת<sup data-n=\"1008\">17</sup> \"שנמנעו הלוים שירימו מן המעשר הניתן להם תרומת מעשר מן הרע שבו אבל ירימו ביפה או בשוה והוא אמרו יתעלה ולא תשאו עליו חטא בהרימכם את חלבו ממנו\").\nוהנה לכאורה יש לפרש כוונת ה­רמב\"ן במ\"ש \"או מן השוה\" (\"או בשוה\"), שהחיוב לתרום מן היפה שולל רק הפרשה מן הרע, אבל מותר להפריש מן הבינוני<sup data-n=\"1009\">18</sup> [וע\"ד דין \"מובחרים\" בקרבן, שנוסף לכך שגם אם אינו מובחר אינו נפסל בכך<sup data-n=\"1010\">19</sup>, הנה גם גדר ד\"מובחר\" ש­חייבים להביא לכתחילה, הוא רק ש\"לא יביא שה כחוש וכעור\"<sup data-n=\"1011\">20</sup>, אבל אין חייבים (אולי אפילו לכתחילה) להביא \"מן היפה המשובח ביותר\"<sup data-n=\"1012\">21</sup>].\nוכן מפורש בש\"ס<sup data-n=\"1013\">22</sup>, בסוגיא ד\"כלך אצל יפות\", ד\"סתמי' דבעל הבית כי תרום מבינונית הוא תרום\"<sup data-n=\"1014\">23</sup>, ומדוייק גם כן בלשון הגמ' במ\"א<sup data-n=\"1015\">24</sup> \"והרי תורם מן הרעה על היפה דרחמנא אמר מכל חלבו, חלבו אין גירועין לא\", שרק \"גירועין\" אסור.\nאבל צע\"ק לשון הרמב\"ן \"או מן ה­שוה\", דלכאורה ע\"פ הנ\"ל הו\"ל לנקוט כלשון הש\"ס \"או מן הבינוני\"?\nומסתבר יותר לפרש לשון הרמב\"ן \"או מן השוה\" שכוונתו שאם התרומה והשיריים הם \"בשווה\", כלומר מאותו הסוג (ללא הבדל, אם הם יפים, בינונים או רעים), מותרים לתרום זה על זה. כי האיסור הוא רק לתרום \"מן הרע על היפה\" (וכן מ\"ש הרמב\"ן \"מן הרע שבו\", היינו שהשיריים אינם רע, ובמילא הוי תורם מן הרע על היפה) — אבל אם התרומה והשיריים \"בשוה\", אפילו שני­הם מן הרע, אין בכך איסור<sup data-n=\"1016\">25</sup>.\n[ויש להוסיף, שגם את\"ל שכוונת ה­רמב\"ן ב\"או מן השוה\" היא שמותרים לתרום מן הבינוני — ה\"ז לכאורה דלא כשיטת הספרי הנ\"ל<sup data-n=\"1017\">26</sup>, שכ' בפירוש \"שאם הפרשתם אותו שלא מן המובחר שאתם בנשיאות עון\", \"אזהרה. . שלא יהו תורמים אותו אלא מן המובחר\", ודוחק גדול לומר שכוונתו לשלול רק \"רע\" (ואדרבה, פשטות משמעות הספרי היא, דגם כשתורם מן היפה צריך לתרום מן המובחר שביפות גופא, כנ\"ל ס\"א)].",[["1007","16","מצוה ט."],["1008","17","מצוה ז."],["1009","18","ע\"ד לשון הרמב\"ם סוף הל' איסורי מזבח \"יפה. . והשוה והפחות\"."],["1010","19","דרק אם יש בו מום פסול."],["1011","20","רמב\"ם שם רפ\"ז."],["1012","21","ל' הרמב\"ם שם בסוף הפרק — למי ש\"רוצה לזכות עצמו\". וראה לקמן בפנים ס\"ה."],["1013","22","ב\"מ כב, א."],["1014","23","ובתוס' שם (ד\"ה ואם לאו) ש\"מיפות אין רגילות לתרום\". — וראה בארוכה השקו\"ט בספרי דבי רב על הספרי פרשתנו כאן (ועוד), שלכאו' לפי לשון הספרי (וכן ל' הרמב\"ם הל' תרומות רפ\"ה, הובא לקמן ס\"ד) צ\"ל רק מן המובחר. ומפרש שדברי הגמ' \"סתמי' דבעה\"ב. . מבינונית הוא תרום\" נאמרו רק להקס\"ד ולא למסקנא. ע\"ש."],["1015","24","תמורה שם."],["1016","25","וראה ערוך השולחן העתיד הל' תרומות (סי' סו) שמגרוגרות על גרוגרות יכול להפריש."],["1017","26","ואף שהרמב\"ן שם הביא דברי הספרי — י\"ל שכוונתו רק לראי' לכללות דבריו שהוא ציווי בפ\"ע (ולכן נמנה במנין המצות, דלא כהרמב\"ם שלא מנאו במנין המצות)."]]],[1301430181,"וע\"פ הנ\"ל י\"ל שמקורו של הרמב\"ן הוא בלשונות הש\"ס הנ\"ל, שהאיסור הוא רק לתרום מן הרע על היפה.\nד. ולכן מסתבר לומר, שלשיטת ה­ש\"ס (שבכל מקום מדייק שהאיסור הוא רק לתרום \"מן הרע על היפה\", ולאידך מפורש (כנ\"ל) שיש לתרום \"מן היפה על הרע\", שמזה משמע — ולא מן הרע על הרע) — יש חילוק בין החיוב והאיסור (מ\"ע ול\"ת<sup data-n=\"1018\">27</sup>):\nהחיוב (מ\"ע) לכתחילה ולהידור<sup data-n=\"1019\">28</sup> הוא לתרום מן היפה, וזה כולל שיש לתרום \"מן היפה על הרע\" (וכן ביפות גופא, המובחר מן היפות); אבל האיסור (ל\"ת) כשאינו תורם מן היפה הוא רק כשתורם מן הרע על היפה, שרק אז הוא ב­\"נשיאות חטא\"<sup data-n=\"1020\">29</sup> (משא\"כ אם רק החסיר ההידור לתרום מן היפה ומן המובחר, אין בו נשיאות חטא).\n[ויש לומר, שהחילוק תלוי בלשונות הכתובים: גבי האיסור (ל\"ת) נאמר \"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\", שפשטות הכתוב<sup data-n=\"1021\">30</sup> היא, שהנשאר (\"ממנו\") אינו \"חלבו\", והיינו שצ\"ל הפ­רשה מן היפה על הרעה, ולא להיפך, מן הרעה על היפה; משא\"כ גבי החיוב (העשה) לתרום מן היפה נאמר<sup data-n=\"1022\">31</sup> (גם) \"מכל חלבו\" (סתם), \"כל חלב יצהר גו'\", שהתרומה (בכלל) צ\"ל תמיד מן ה\"חלב\" והמובחר].\nמשא\"כ לפי הספרי, שהאיסור הוא לא רק לתרום מן הרע על היפה, אלא גם כשאינו מפריש \"מן המובחר\" הרי הוא \"בנשיאות עון\".\nוזוהי גם שיטת הרמב\"ם ששינה מלשון המשנה<sup data-n=\"1001\">11</sup> \"כל מקום שיש כהן תורם מן היפה\", וכתב<sup data-n=\"1024\">32</sup> \"אין תורמין",[["1018","27","לדעת הרמב\"ן בהשמטות לסהמ\"צ שמנה החיוב לתרום מן היפה במנין העשה ובמנין הל\"ת (כנ\"ל ס\"ג), משא\"כ לדעת הרמב\"ם (סהמ\"צ מ\"ע קכט) שלא מנאו כמ\"ע בפ\"ע, וגם \"ולא תשאו עליו חטא\" אינו לאו אלא \"שלילת החיוב\" (וראה השקו\"ט במפרשי סהמ\"צ שם. הרי\"פ פערלא לסהמ\"צ הרס\"ג עשה קנד. ועוד). — וראה הערה 32."],["1019","28","להעיר מהקס\"ד דאביי (תמורה שם) \"אי לאו דאמר רחמנא ולא תשאו עליו חטא ה\"א הכי אמר רחמנא עביד מצוה מן המובחר ואי לא עביד חוטא לא מקרי, קמ\"ל\". ועפ\"ז י\"ל, שלפי המסקנא לא מקרי חוטא אלא בתורם מן הרע על היפה, משא\"כ זה שצריך לתרום מן היפה על הרעה (וכן מן המובחר ביפה גופא) הוי רק למצוה מן המובחר (כיון דלא נזכר בזה נשיאות חטא, ואין בו אלא חידושו)<sup data-n=\"e22\">*</sup>. וראה לקמן הערה 32 בשוה\"ג."],["1020","29","להעיר מספרי זוטא (פרשתנו יח, כט) \"ממנו — שלא יפריש תרומה ממין על שאינו מינו, שלא יטול מן הרע על היפה\", שמשמע, שגדר האיסור שלא ליטול מן הרע על היפה הוא ע\"ד האיסור ליטול ממין על שאינו מינו. והיינו שאין האיסור מפני שמפריש מן הרע, אלא מפני שאין ההפרשה מן הרע יכולה להתיר את היפה, ע\"ד מין על שאינו מינו."],["1021","30","משא\"כ לדרשת הספרי \"ממנו — ממינו\" (כנ\"ל בפנים סוס\"א)."],["1022","31","פרשתנו יח, כט (שפסוק זה הובא בש\"ס — תמורה ה, א). שם, יב (הובא לענין זה בתוס' (ד\"ה אם) קידושין מז, רע\"א)."],["1001","11","תרומות פ\"ב מ\"ד."],["1024","32","הל' תרומות רפ\"ה. וראה גם הל' מעשר פ\"א הי\"ג.\nועפ\"ז י\"ל שהרמב\"ם והרמב\"ן לשיטתייהו אזלי: להרמב\"ם ש\"לא תשאו עליו חטא\" אינו לאו בפ\"ע אלא \"שלילת החיוב\" (כנ\"ל הערה 27), אין חילוק בין החיוב להרים מן היפה ו\"לא תשאו עליו חטא\", ש­שניהם איירי באותו ענין (וראה ל' הרמב\"ם שם); משא\"כ להרמב\"ן, ש\"ולא תשאו עליו חטא\" הוא לאו בפ\"ע, ס\"ל שהעשה והלאו איירי בגוונים שונים<sup data-n=\"e23\">*</sup>, כבפנים."],["e22","*","ועפ\"ז י\"ל, שגם לרבא (ראה תוד\"ה אם שם ובקידושין מו, ב), יש חילוק (למסקנא) בין העשה והל\"ת, כבפנים. ואכ\"מ."],["e23","*","אף שגם בהמ\"ע כ' \"שנפריש אותה. . או מן השוה\" — י\"ל (בדוחק עכ\"פ) שזהו מפני שבהמשך דבריו מוסיף גם השלילה, \"לא מן הרעה על היפה\", שאיסור זה אינו כשתורם \"מן השוה\" [דכיון שגבי הל\"ת (\"ולא תשאו עליו חטא\") מודגש שהאיסור הוא רק בתורם מן הרעה על היפה, מסתבר, שכ\"ה גם לגבי העשה, שאין איסור עשה (לאו הבא מכלל עשה) אלא בתורם מן הרעה על היפה; והחיוב לתרום מן המובחר ביותר הוא רק לכתחילה ולהידור, כנ\"ל בפנים]."]]],[1301430182,"אלא מן היפה שנאמר בהרימכם<sup data-n=\"1025\">33</sup> את חלבו ממנו\" — שיש לפרש כוונתו, שה­חיוב לתרום מן היפה אינו רק הידור מצוה, אלא שיש איסור לתרום שלא מן המובחר (\"אין תורמין אלא מן היפה\"), וכלשון הספרי הנ\"ל \"שלא יהו תורמים אותו אלא מן המובחר\"<sup data-n=\"1026\">34</sup>.\nה. ויש לומר, ששני אופנים אלה (אם הפרשה שלא מן המובחר הוא בנשיאות חטא) — תלויים בגדר החיוב לתרום מן היפה.\nדהנה בסוף הל' איסורי מזבח כתב הרמב\"ם \"שהרוצה לזכות עצמו יכוף יצרו הרע וירחיב ידו ויביא קרבנו מן היפה המשובח ביותר כו' והוא הדין בכל דבר שהוא לשם הא­ל הטוב שיהי' מן הנאה והטוב, אם בנה בית תפלה יהי' נאה מבית ישיבתו כו' הקדיש דבר יקדיש מן היפה שבנכסיו וכן הוא אומר<sup data-n=\"1027\">35</sup> כל חלב לה' וגו'\".\nויש לחקור אם החיוב דתרומה מן היפה (\"בהרימכם את חלבו ממנו\") אינו אלא פרט מהחיוב הכללי ד\"כל חלב לה'\", או שזהו דין מיוחד גבי תרומה.\nוי\"ל דבזה פליגי הש\"ס והספרי:\nלשיטת הש\"ס חיוב זה אינו אלא פרט מהדין הכללי ד\"כל חלב לה'\", ולכן אין לומר דכשאינו מקיים זה הרי הוא בכלל \"נשיאות חטא\", שהרי דין כללי זה אינו אלא הידור למי ש\"רוצה לזכות עצמו\" (כמ\"ש הרמב\"ם שם). ולכן ס\"ל להש\"ס שרק כשתורמים מן הרע על היפה הוי \"נשיאות חטא\", שאז הוא בזיון התרומה, ששירי' הם יפים והתרומה (המתירה את השיריים) היא מן הרע.\nמשא\"כ לשיטת הספרי, שהדין ד\"בה­רימכם את חלבו ממנו\" הוא דין מיוחד בתרומה, מובן שזהו חיוב גמור להפריש מן המובחר, ובמילא, כשאין מפרישים מן המובחר \"אתם בנשיאות עון\".\nו. ואולי יש לומר עוד, ובהקדם פלוגתת ת\"ק ור' יהודה (הנ\"ל ריש סעיף ב) אם כשאין כהן תורמין מן המתקיים או לעולם תורמין מן היפה גם כשאין כהן.\nשיש לבאר דפליגי אם החיוב לתרום מן היפה הוא תנאי בההפרשה או תנאי בהנתינה לכהן<sup data-n=\"1028\">36</sup>:\nר' יהודה הסובר שלעולם תורמים מן היפה (גם כשאינו מתקיים) טעמו — כי חיוב זה הוי דין בהפרשת התרומה, כי",[["1025","33","וג\"ז הוא כהספרי, ולא כבש\"ס שהביא (כנ\"ל הערה 31) הכתוב ד\"מכל חלבו\" (אלא שבסהמ\"צ (מ\"ע קכט) גם הרמב\"ם הביא \"מכל חלבו\")."],["1026","34","ולהעיר מלשון הרמב\"ם בסהמ\"צ שם, \"כשיוציאוהו מן הרע יחטאו\" [ולא כ' כלשון המשנה \"מן הרע על היפה\"], וממשיך בהעתק לשון הספרי."],["1027","35","ויקרא ג, טז."],["1028","36","להעיר מצפע\"נ על הרמב\"ם ריש הל' כלאים (ב, סע\"ג) ובהשמטות לשם (נדפסו לאחרי הל' מתנ\"ע — א, א)."]]],[1301430183,"תוכן ענין הפרשת תרומה הוא — ה­הפרשה לה'<sup data-n=\"1029\">37</sup>, כלשון הכתוב<sup data-n=\"1030\">38</sup> \"כל חלב יצהר גו' אשר יתנו לה' לך נתתים\", \"כן תרימו גם אתם תרומת ה'\" (אלא שאח\"כ נותנים אותה לכהנים), ולכן חל על עצם ההפרשה חיוב שתהי' מחלבו (ע\"ד \"כל חלב לה'\"), ומטעם זה ס\"ל לר' יהודה ד­אע\"פ שאינו מתקיים לא חיישינן לפסי­דא דכהן, כי העיקר הוא שההפרשה לה' תהי' מן היפה<sup data-n=\"1031\">39</sup>.\nמשא\"כ הת\"ק ס\"ל שזהו בעיקר בשביל הכהן, שהנתינה אליו תהי' מן ה­יפה<sup data-n=\"1032\">40</sup>, כדי שהספקת צרכיו על ידי בנ\"י תהי' באופן היותר טוב, מן היפה וה­מובחר. ולאופן זה אם היפה אינו מתקיים דין קדימה להמתקיים.\nועפ\"ז יש לומר, שהשאלה הנ\"ל (אם החיוב להפריש תרומה מן המובחר הוא חלק מהחיוב הכללי ד\"כל חלב לה'\" או לא) תלוי בגדר ד\"כל חלב לה'\".\nדהנה נת' במ\"א<sup data-n=\"1033\">41</sup> בביאור שיטת ה­רמב\"ם שלא הביא הא ד\"התנאה לפניו במצות\"<sup data-n=\"1034\">42</sup> (שנלמד מ\"זה א­לי ואנוהו\"<sup data-n=\"1035\">43</sup>) אלא רק הדין ד\"כל דבר שהוא לשם הא­ל הטוב יהי' מן הנאה והטוב, אם בנה בית תפלה יהי' נאה מבית ישיבתו כו' הקדיש דבר יקדיש מן היפה שב­נכסיו וכן הוא אומר כל חלב לה' וגו'\" — שהכוונה בזה לדבר שהוא דומה לקרבן ע\"ג מזבח (קרבן לה'), שמוסר את הדבר לה', כמו \"בנה בית תפלה\", \"הקדיש דבר\" [וגם הדוגמאות שברמב\"ם שם ד­\"האכיל רעב כו' כסה ערום\" הוא מפני שאיירי בצדקה שהיא לכפרה<sup data-n=\"1036\">44</sup>], שבזה צ\"ל \"מן היפה שבנכסיו\", כי זה נוגע להחפצא, שע\"י שהדבר הוא \"מן היפה\" הרי ההקרבה לה' היא בשלימות וב­הידור יותר.\nולפי זה מבוארת שיטת הרמב\"ם בנדו\"ד (הפרשת תרומה מן היפה): כיון שנקטינן להלכה כת\"ק שכשאין כהן תורמין מן המתקיים, והיינו מפני שזהו דין בנתינה לכהן, נמצא, שאין דין זה שייך לחיוב הכללי ד\"כל חלב לה'\" (שזהו רק ב\"כל דבר שהוא לשם הא­ל\"), ולכן ס\"ל להרמב\"ם שזהו דין חדש ו­מיוחד גבי הפרשת תרומה שצריכים לתת לכהן מן היפה, וכיון שזהו דין מיוחד בתרומה ס\"ל ג\"כ שאינו רק הידור לכתחילה, אלא דאם אין מקיימים דין זה יש בו נשיאות עון (כשיטת הספרי), ולכן כתב \"אין תורמין אלא מן היפה\", כנ\"ל.\nמשא\"כ לשיטת הש\"ס, שיש חיוב דהידור מצוה בכל המצות, \"התנאה ל­פניו במצות\" (וי\"ל שלשיטת הש\"ס אין חילוק בין דין הידור מצוה בכלל, והחיוב ד\"כל חלב לה'\"), ולכן ס\"ל שה­חיוב לתרום מן היפה הוא רק פרט בחיוב הכללי דהידור מצוה ו\"כל חלב לה'\"<sup data-n=\"1037\">45</sup>, ולכן אא\"פ לומר שבגלל זה",[["1029","37","ראה ספרי פרשתנו (יח, כא) כל מצות כהונה קנאו השם ונתנו לכהונה. וראה מגילת אסתר ומרגניתא טבא לסהמ\"צ שורש יב. וראה לקו\"ש ח\"ח ע' 34 ובהערות שם. חי\"ח ע' 223. ועוד."],["1030","38","פרשתנו יח, יב. שם, כח (ושם, כו)."],["1031","39","ולהעיר מהשקו\"ט במפרשי הספרי (סוף פרשתנו) ועוד, אם חייבים לתרום מן היפה בתרומה טמאה ההולכת לאיבוד. וראה צפע\"נ הנ\"ל."],["1032","40","וכן משמע מדיוק ל' רש\"י (ב\"מ כב, א ד\"ה כלך) \"הי' לך לילך אצל יפות לתת מהן לכהן\"."],["1033","41","לקו\"ש חכ\"ז ע' 10 ואילך ובהערות שם."],["1034","42","שבת קלג, ב."],["1035","43","בשלח טו, ב."],["1036","44","ראה לקו\"ש שם ע' 14 ובהערות שם. וש\"נ."],["1037","45","ראה של\"ה (שבהערה 7) \"המצוה מהמובחר ליתן חלק הכהנים מן המובחר ביותר, וכן אלו ה­נותנים מעות לקופה של צדקה או לעני יתנו מטבע המובחרת כו'\".\nולהעיר ג\"כ שהדין ד\"כל חלב לה'\" שברמב\"ם (סוף הל' איסורי מזבח) — הועתק (בשינוי לשון קצת) בשו\"ע הל' צדקה (יו\"ד סו\"ס רמח), אף שלכאורה הי' מקום להביאו לפנ\"ז בהל' בית הכנסת (או\"ח סק\"נ ואילך), כהדוגמא \"בנה בית תפלה\". וי\"ל של­דעת הב\"י הדין ד\"כל חלב לה'\" אינו רק בדברים שהם דומים לקרבן ע\"ג מזבח, אלא בכל מצוה<sup data-n=\"e24\">*</sup>, והוא דין אחד עם כללות החיוב דהידור מצוה (שהובא בשו\"ע או\"ח סתרנ\"ו לענין אתרוג \"עד שליש\", משא\"כ ברמב\"ם שהשמיט דין זה). ולכן הביאו בהל' צדקה דוקא, שאין מוסרים לשמים כ\"א לעני."],["e24","*","ואולי י\"ל שזהו טעם השינוי, שברמב\"ם כתב \"כל דבר שהוא לשם הא­ל\", ובשו\"ע \"לשם שמים\", ד\"לשם הא­ל\" משמעו דבר שמוסרים לה', כקרבן ע\"ג מזבח, משא\"כ \"לשם שמים\" משמעו כל ענין של עבודת השם."]]],[1301430184,"שאינו מן המהדרים תהי' בזה \"נשיאות חטא\".\nז. והנה יש עוד שינוי בין לשון הספרי ולשון הש\"ס, דבש\"ס הלשון \"ואם אין קדוש נשיאות חטא למה\" (והוא כלשון הכתוב עצמו \"ולא תשאו עליו חטא\"), אבל בספרי משנה ואומר \"שאתם בנשיאות עון\", וידוע ד\"עון\" חמור יותר מן החטא<sup data-n=\"1038\">46</sup>.\nוהנה אע\"פ שנת\"ל שדין זה (שרק משום שחסר \"מן המובחר\" יש בזה \"נשיאות עון\") הוא רק בתרומה — מ\"מ, יש ללמוד מזה גם לגבי שאר מצוות התורה החומר כשחסר בהידור מצוה — דאע\"פ שאין לחייבו ולכופו על הידור, מ\"מ, כשאינו מהדר במצות, אין זה רק שחסרה בו המעלה דהידור מצוה, אלא שיש בזה (מעין) נשיאות עון<sup data-n=\"1039\">47</sup> (שנחשב לחסרון בהמצוה עצמה).\nומרובה מדה טובה כו' — דכאשר מקיימים מצות בהידור, הרי נוסף על השכר עבור ההידור מצוה, יש הוספה בשכרה של המצוה עצמה.\n<span data-k=\"q\">(משיחות ש\"פ קרח תשכ\"ד, כ\"ף מנ\"א תשמ\"ה)</span>",[["1038","46","ראה יומא לו, ב. ובכ\"מ."],["1039","47","וראה שו\"ע אדה\"ז או\"ח (סתפ\"א ס\"א) \"והאוכל והשותה (אחר כוס ד) אין עליו כלום, אלא שנמצא מוציא עצמו מכלל המהדרין ועובר על דברי חכמים שאמרו (ברכות מט, סע\"ב) לעולם אל יוציא אדם עצמו מן הכלל\"."]]],[1301430185,"<h3>שיחה א</h3>\nא. \"זאת חוקת התורה גו' ויקחו אליך פרה אדומה גו'\"<sup data-n=\"1040\">1</sup>, וארז\"ל<sup data-n=\"1041\">2</sup> בטעם הדיוק \"ויקחו אליך\" (למשה דוקא) \"שכל ה­פרות בטלות ושלך קיימת\", וזה נוגע (לא רק לפרת משה, אלא) לכל הפרות ה­אדומות שבכל הדורות, כי בכולם נת­קדשו הכהנים שעשו את הפרה מאפר פרתו של משה<sup data-n=\"1042\">3</sup>, ולכן נקראו כל הפרות ע\"ש משה דוקא<sup data-n=\"1043\">4</sup>.\nוהשייכות המיוחדת של פרה אדומה למשה רבינו מודגשת גם בנוגע לטעם מצוה זו, דאע\"פ שאפילו שלמה המלך [ש\"על כל אלה (כל חוקי התורה) עמד­תי\"<sup data-n=\"1044\">5</sup>] אמר על מצוה זו \"והיא רחוקה ממני\"<sup data-n=\"1045\">6</sup> — מ\"מ, למשה רבינו נתגלה טעם פרה, כמחז\"ל<sup data-n=\"1046\">7</sup> על תיבות אלו \"ויקחו אליך\" — \"לך אני מגלה טעם פרה\".\nוצריך להבין — מה נשתנתה מצוה זו מכל מצות התורה, שבה מודגשת שייכו­תה למשה רבינו, הן באופן קיומה, ש­קיום מצוה זו (גם לדורות) הוא ע\"י אפר פרתו של משה, והן באופן לימודה, \"לך אני מגלה טעם פרה\"<sup data-n=\"1047\">8</sup>?\nב. ויש לבאר זה בהקדים מה שאמרו רז\"ל<sup data-n=\"1048\">9</sup> (בטעם שפרה אדומה היא נקבה, דלא ככל קרבנות ציבור שהם זכרים) — \"אמר הקב\"ה תבא פרה ותכפר על מעשה העגל\" (ובפרש\"י על התורה<sup data-n=\"1049\">10</sup> מ­יסודו של ר' משה הדרשן, גם פרטי הרמזים במצות פרה אדומה על כפרת חטא העגל).\nוביארו המפרשים<sup data-n=\"1050\">11</sup> השייכות בין כפרת חטא העגל להטהרה מטומאת מת (ענינה של פרה אדומה כפשוטה) — ע\"פ דברי חז\"ל<sup data-n=\"1051\">12</sup> שלולא חטא העגל לא הי' כל ענין המיתה אצל בנ\"י, כי היתה \"חי­רות ממלאך המות\" (כמו לפני חטא עץ הדעת, שהרי בעת מ\"ת פסקה זוהמתן<sup data-n=\"1052\">13</sup>, אלא שע\"י חטא העגל חזרה זוהמתן<sup data-n=\"1053\">14</sup>), ונמצא שחטא העגל הי' סיבה (לענין ה­",[["1040","1","ריש פרשתנו (יט, ב)."],["1041","2","תנחומא פרשתנו ח. במדב\"ר פי\"ט, ו. וראה רש\"י יומא ד, רע\"א. וראה הנסמן בהערה הבאה."],["1042","3","ראה פרה פ\"ג מ\"ה \"ומאחת\" (ועד\"ז הוא ל' הרמב\"ם הל' פרה אדומה פ\"ב ה\"ו) ובמשנה אחרונה שם (ע\"פ תוי\"ט שם מ\"ג). ולהעיר ג\"כ מפי' מהרז\"ו לבמדב\"ר שם. ביאורי מהרא\"י (לבעל תרוה\"ד) ושפ\"ח (לפרש\"י פרשתנו שם). של\"ה חלק תושב\"כ פרשתנו (שנט, ב). וראה לקמן הערה 36."],["1043","4","של\"ה, ביאורי מהרא\"י ושפ\"ח שבהערה הקודמת."],["1044","5","תנחומא שם ו (קרוב לסופו). במדב\"ר שם, ג (בסופו)."],["1045","6","קהלת ז, כג. תנחומא ובמדב\"ר שם."],["1046","7","תנחומא שם, ח. במדב\"ר שם, ו. וראה ידי משה שם."],["1047","8","בכלי יקר ריש פרשתנו מבאר השייכות למשה מצד הענין דכפרת חטא העגל, ע\"ש (וראה לקמן סעיף ב). אבל עדיין צריך ביאור השייכות למשה מצד הענין דטהרה מטומאת מת (כפשוטה)."],["1048","9","תנחומא שם ח (בסופו). במדב\"ר שם, ח (בסופו). וראה גם תוד\"ה מי — מו\"ק (כח, רע\"א)."],["1049","10","בסוף פרשת פרה אדומה (יט, כב)."],["1050","11","כלי יקר, אלשיך, ש\"ך עה\"ת, עץ הדעת טוב (להרח\"ו) ועוד פרשתנו."],["1051","12","שמו\"ר רפל\"ב. זח\"א לז, סע\"ב. קלא, סע\"ב. ועוד."],["1052","13","שבת קמו, רע\"א."],["1053","14","זח\"א נב, ב. קכו, ב. זח\"ב קצג, סע\"ב. ועוד."]]],[1301430186,"מיתה, ובמילא — גם) לטומאת מת; וזהו הקשר בין שני הענינים דכפרת חטא ה­עגל וטהרה מטומאת מת — דהא בהא תליא, שע\"י כפרת חטא העגל, מתבטל בדרך ממילא הענין דטומאת מת (ע\"י שבטלה הסיבה לטומאת מת — מיתה בכלל).\nובזה יש לבאר (ע\"ד הדרוש) דיוק ל' הרמב\"ם<sup data-n=\"1054\">15</sup> \"ותשע פרות אדומות נעשו משנצטוו במצוה זו עד שחרב הבית ב­שניי', ראשונה עשה משה כו' והעשירית יעשה המלך המשיח\" — דלכאורה אינו מובן: מה טעם הוצרך הרמב\"ם לכתוב מספר<sup data-n=\"1055\">16</sup> הפרות שנעשו במשך כל ה­דורות?\nכן צע\"ק: הרמב\"ם לא הסתפק ב­הבאת מספר הפרות שהובא במשנה<sup data-n=\"1056\">17</sup>, אלא מוסיף<sup data-n=\"1057\">18</sup> \"והעשירית יעשה המלך ה­משיח\" — הרמב\"ם הביא בספרו גם הלכ­תא למשיחא, שאז \"חוזרין כל המשפטים. . כשהיו מקודם, מקריבין קרבנות כו'\"<sup data-n=\"1058\">19</sup>, אבל למה הבדיל הרמב\"ם פרה העשירית מכל הענינים והקרבנות של \"הנשיא\" — שבנבואת יחזקאל<sup data-n=\"1059\">20</sup>, וכותב שהמלך המשיח יעשה הפרה העשירית?\nוע\"פ הנ\"ל יש לומר — שבזה מרמז הרמב\"ם, ששלימות הטהרה על ידי פרה אדומה בכלל תהי' רק בפרה העשירית שתיעשה על ידי המלך המשיח. כי אין כפרה גמורה לחטא העגל (כמש\"נ<sup data-n=\"1060\">21</sup> \"וב­יום פקדי ופקדתי גו'\") עד לעת\"ל, ורק אז, כשתוגמר הכפרה על מעשה העגל, אז תבוא שלימות הטהרה מטומאת מת, כי יבוטל אז כל ענין המיתה (כמ\"ש<sup data-n=\"1061\">22</sup> בלע המות לנצח), שהיא הסיבה לטומאת מת כנ\"ל<sup data-n=\"1062\">23</sup>.\nוזהו הרמז בהרמז ש\"העשירית יעשה המלך המשיח\" — כי עשר הוא מספר ה­שלם (כנודע<sup data-n=\"1063\">24</sup>), ושלימות ה(טהרה ד)פרה אדומה תהי' רק לעת\"ל, בפרה שיעשה המלך המשיח.\nג. עפ\"ז יש לבאר גם השייכות דפרה אדומה \"אליך\" למשה רבינו:\nיסוד הטהרה של פרה אדומה אינו רק ביטול הטומאה בפועל, אלא ביטול סיבת הטומאה מעיקרא — ענין המיתה. ולכן צריכים בזה לכחו של משה<sup data-n=\"1064\">25</sup> — כי מעניניו המיוחדים של משה הוא ענין הנצחיות, כמבואר בחז\"ל<sup data-n=\"1065\">26</sup> שמעשי ידי",[["1054","15","הל' פרה אדומה ספ\"ג. — ביאור הלכה זו ע\"ד ההלכה ראה לקו\"ש חכ\"ח ע' 131 ואילך."],["1055","16","בפשטות י\"ל — להודיע שצריך להביא מתשע פרות ולא משבע כדברי ר\"מ."],["1056","17","פרה פ\"ג מ\"ה."],["1057","18","וצ\"ע וחיפוש מקורו דהרמב\"ם. ולהעיר מכו\"כ ענינים שהעשירי הוא בימוה\"מ (או ע\"י משיח) — שירה העשירית, מנין העשירי דבנ\"י, כיבוש ארץ עשר אומות, עשר נימין דכינור המקדש וכו'. וראה מדרש מעשה תורה אות יו\"ד."],["1058","19","ל' הרמב\"ם הל' מלכים רפי\"א. וצע\"ק אם ואיך יקריבו קרבנות קודם עשית פרה העשירית וטהרת ג' וז'."],["1059","20","מה, יז ואילך. — וראה רמב\"ם הל' מעה\"ק ספ\"ב."],["1060","21","תשא לב, לד ובפרש\"י שם. סנהדרין קב, סע\"א. ועוד."],["1061","22","ישעי' כה, ח. משנה סוף מו\"ק. זח\"א קטו, סע\"א. — וראה סה\"מ תרכ\"ח ע' מ ואילך. סה\"מ מלוקט ח\"ב ע' רעז ואילך."],["1062","23","ראה אוה\"ת לנ\"ך (ס\"ע תקכג ואילך) ד\"מעשה פרה רומז על הגאולה דלע\"ל ולכן מטהרת טומאת מת שאזי ומחה ה'. . ובלע המות לנצח\". ע\"ש. וראה אוה\"ת פרשתנו ס\"ע תתט."],["1063","24","ראה ראב\"ע לשמות ג, טו. פרדס שער ב'."],["1064","25","וראה עץ הדעת טוב פרשתנו, שענין התורה שניתנה ע\"י משה בא \"לכפר עון אדה\"ר לבטל ה­מיתה\". ע\"ש."],["1065","26","ראה סוטה ט, סע\"א. תנא דבא\"ר פי\"ח. צפע\"נ עה\"ת ר\"פ תרומה. ועוד."]]],[1301430187,"משה הם נצחיים (וכמו שמצינו בנדו\"ד, פרה אדומה גופא, שאפר פרה שלו הוא מתחלת הענין, וגם — קיים לעד), ועד\"ז בנוגע למשה עצמו, אף שנאמר וימת שם משה<sup data-n=\"1066\">27</sup> אמרו עליו<sup data-n=\"1067\">28</sup> \"לא מת משה. . מה להלן עומד ומשמש אף כאן כו'\". ולכן הטהרה של כל פרה ופרה תלוי' באפרו של פרת משה — כי כח הטהרה של פרה אדומה קשור עם ענין הנצחיות של משה רבינו<sup data-n=\"1068\">29</sup>.\nולהעיר, שאע\"פ שענין הטהרה מ­טומאת מת בשלימותו לא יושג עד לעת\"ל כשיבולע המות לנצח (ועד אז הפרה מטהרת מן הטומאה, אבל אין בכחה לבטל סיבת הטומאה) — זהו רק בנוגע ליחיד, אבל בנוגע לציבור — ע\"י תורה, שקיבל משה מסיני ומסרה כו', נעשית מציאות ציבור, אשר \"אין הציבור מתים\"<sup data-n=\"1069\">30</sup>, שבציבור דבנ\"י לא שייך ענין המיתה.\nד. והנה \"התורה היא נצחית\"<sup data-n=\"1070\">31</sup> בכל זמן ובכל מקום. שמזה מובן, דאע\"פ ש­עכשיו אין לנו אפר פרה, מ\"מ, תוכן הענין דטהרת פרה אדומה, שכולל אפר פרתו של משה, ישנו בעבודה הרוחנית של כאו\"א מישראל.\nהסברת הענין:\nהמשכת הנצחיות של משה היתה ע\"י שהי' בתכלית הביטול להקב\"ה (\"עבד נאמן\"<sup data-n=\"1071\">32</sup>), ענין המסירת נפש, שמוכן למסור כל מציאותו עבורו ית'. וי\"ל ש­לכן מעשי ידי משה נצחיים המה — כי מסירת נפש היא למעלה משינויים, שהרי כל ענין המסירת נפש הוא — התוקף לעשות רצונו ית' באופן ששום דבר שב­עולם לא יוכל לשנותו.\nולכן הטהרה מטומאת מת היא בכח אפר פרתו של משה: טומאת מת מורה על הפירוד מקדושה, כי כאשר \"דבקים בה' אלקיכם (הרי אתם) חיים כולכם היום\"<sup data-n=\"1072\">33</sup> (אין שייך מיתה, ובמילא לא טומאת מת); וכדי לבטל מכל וכל את ה­\"מיתה\" והפירוד מקדושה, שיהי' תכלית הדביקות בה' אלקיכם — ה\"ז ע\"י שה­אדם מעורר בעצמו את מסירת נפשו לה'<sup data-n=\"1073\">34</sup>.\nוכמו שהנצחיות באפר פרתו של משה באה בשני ענינים — (א) שהוא עצמו קיים לעד<sup data-n=\"1074\">35</sup>, (ב) כל הפרות היו צריכות",[["1066","27","ברכה לד, ה."],["1067","28","סוטה יג, סע\"ב. זח\"א לז, סע\"ב ואילך. וראה לקו\"ש חכ\"ו (ע' 6 ואילך) החידוש בזה לגבי המדובר במרז\"ל (ברכות יח, סע\"א ואילך) שצדיקים (בכלל) גם במיתתם קרויים חיים."],["1068","29","וי\"ל שזהו גם הטעם שהרמב\"ם הזכיר רק משה ועזרא ולא העתיק מהמשנה (פרה שם) שמות עושי ז' הפרות לאחרי עזרא — כי כח הטהרה שב­פרה אדומה יסודו מפרתו של משה, כבפנים (ועזרא שקול כמשה ומסר תורה לכל ישראל ונקרא הסופר וכו' — ראה סנהדרין כא, סע\"ב. ועוד)."],["1069","30","הוריות ו, א. תמורה (טו, ב. טז, סע\"א). רמב\"ם הל' פסולי המוקדשין פ\"ד סה\"א (וצע\"ק שינוי ל' הרמב\"ם \"ואין כל ישראל מתים\", ובפרט ע\"פ דעתו דשבט אינו כלה (עיין צפע\"נ להל' קדוה\"ח ספ\"ה בפי' דברי הרמב\"ם בסהמ\"צ מ\"ע קנג — ע\"פ ב\"ב קטו, ריש ע\"ב וברשב\"ם שם))."],["1070","31","ל' התניא — רפי\"ז. שם קו\"א סד\"ה להבין פרטי ההלכות. וראה סה\"מ מלוקט ח\"ב ע' שיב הערה 17 בשוה\"ג."],["1071","32","נוסח תפלת העמידה דשחרית דשבת. וראה בהעלותך יב, ז."],["1072","33","ואתחנן ד, ד."],["1073","34","ראה גם לקו\"ש ח\"ד ע' 1058 ואילך. ולהעיר מתניא פי\"ט (כד, ב) בענין \"החכמה תחי'\". וראה בארוכה לקו\"ש חי\"ח ע' 233 ואילך."],["1074","35","ולהעיר, שגם ההשתמשות באפרו של פרת משה נתארכה ריבוי שנים, שהרי עד ימי עזרא לא הוצרכו לפרה שני' — קרוב לאלף שנה השתמשו בפרתו של משה (ואילו במשך השנים דבית שני — ת\"כ שנה — עשו שמונה פרות!)."]]],[1301430188,"לאפר פרתו של משה<sup data-n=\"1075\">36</sup> — עד\"ז הוא ב­עבודה רוחנית, שבהתעוררות כח המסי­רת נפש יש שני ענינים: (א) ההתעוררות של עצם כח המסירת נפש, (ב) מה שכח המסירת נפש נותן כח ועוז בכל עניני עבודת ה' שיהיו כדבעי, וכמבואר ב­תניא<sup data-n=\"1076\">37</sup>, \"שקיום התורה ומצותי' תלוי בזה שיזכור תמיד ענין מסירת נפשו לה'. . שיהי' קבוע בלבו תמיד ממש יומם ו­לילה לא ימיש מזכרונו כי בזה יוכל לעמוד נגד יצרו לנצחו תמיד בכל עת ובכל שעה\".\nובעבודת האדם מדי יום ביומו — הוא החילוק בין עבודת התפלה ושאר עניני עבודת ה' במשך כל היום כולו:\nבשעת התפלה צריך האדם לעורר את אהבתו לה' המסותרת בלבו, שענינה של אהבה זו (כמבואר בארוכה בספר ה­תניא<sup data-n=\"1077\">38</sup>) — הרצון והחפץ לידבק בה' אחד עד כדי מסירת נפש [ואהבה זו נטועה בלב כאו\"א מישראל, להיות נפשו \"חלק אלקה ממעל ממש\"<sup data-n=\"1078\">39</sup>, ש\"ה' אחד\" מאיר בהחלק באופן גלוי; אלא שהיא מסותרת בלבו, ועבודת האדם, לעורר אהבה זו ולהביאה לידי גילוי];\nואח\"כ, במשך כל היום, שאז אין ה­אדם עסוק בעבודת המסירת נפש (כשל­עצמה), אלא \"בקיום התורה ומצותי'\", מ\"מ גם אז צ\"ל זכרון \"ענין מסירת נפשו לה'\", שעי\"ז \"יוכל לעמוד נגד יצרו ל­נצחו תמיד בכל עת ובכל שעה\" — דבי­קות תמידית ונצחית בה', ואז — \"חיים כולכם היום\".\n<span data-k=\"q\">(משיחת ש\"פ חוקת תשכ\"ג)</span>",[["1075","36","ובפרט ע\"פ מ\"ש במפרשים שבכל הפרות היו צריכין לערב מאפר פרתו של משה (ראה ש\"ך עה\"ת ושפ\"ח פרשתנו (יט, ב). עץ הדעת טוב שם. ועוד). — ובפני דוד (להחיד\"א) פרשתנו, ש\"כעת לא נתברר לי זה שמערבין בכל פרה מאפר פרה שעשה משה\"."],["1076","37","ספכ\"ה."],["1077","38","פי\"ח­יט."],["1078","39","תניא רפ\"ב."]]],[1301430189,"<h3>שיחה ב</h3>\nא. בפירושו על הפסוק<sup data-n=\"1079\">1</sup> \"וישלח ישראל מלאכים אל סיחון מלך האמורי\", מעתיק רש\"י \"וישלח ישראל מלאכים\", ומפרש: ובמקום אחר תולה השליחות ב­משה שנאמר<sup data-n=\"1080\">2</sup> ואשלח מלאכים ממדבר קדמות וכן וישלח משה מלאכים מקדש אל ארץ אדום<sup data-n=\"1081\">3</sup> וביפתח הוא אומר<sup data-n=\"1082\">4</sup> ו­ישלח ישראל מלאכים אל מלך אדום וגו' הכתובים הללו צריכים זה לזה זה נועל וזה פותח שמשה הוא ישראל וישר­אל הם<sup data-n=\"1083\">5</sup> משה לומר לך שנשיא הדור הוא ככל הדור כי הנשיא הוא הכל.\nוהנה אף שלפי המשמעות השטחית כוונת רש\"י בפירוש זה היא לתווך ה­סתירות בין הכתובים (אם השליחות ל­סיחון או לאדום היתה ע\"י משה או ע\"י ישראל), הרי כבר נת' כמ\"פ בארוכה ש­אין זו דרכו של רש\"י לתרץ ולתווך סתירות ואי­הבנות שבכתובים אלא ל­אחרי, במקום שבו מתעוררת הסתירה וכיו\"ב. ולפי זה, עכצ\"ל שכוונת רש\"י כאן היא לבאר קושי המתעורר בפסוק דנן, אלא שלצורך זה עליו לבאר את כל הכתובים שמביא ומיישב בדרך אגב.\nויש לומר, שהקושי בכתוב כאן הוא — השינוי בין כתוב זה שבשליחות ל­סיחון (שנאמר בו \"וישלח ישראל מלאכים\") לכתוב שלפנ\"ז (המובא ברש\"י כאן) גבי השליחות למלך אדום \"וישלח משה מלאכים\"<sup data-n=\"1084\">6</sup> — וכדי לבאר שינוי זה מבאר רש\"י \"ובמקום אחר כו'\", שעי\"ז<sup data-n=\"1085\">7</sup> מתיישב (גם) שינוי זה.\nב. אמנם לכאורה יש להבין פרטי לשון רש\"י \"הכתובים הללו צריכים זה לזה זה נועל וזה פותח שמשה הוא ישר­אל וישראל הם משה לומר לך שנשיא הדור הוא ככל הדור כי הנשיא הוא הכל\":\nא) מהו תוכן ההקדמה \"הכתובים הללו צריכים זה לזה זה נועל וזה פותח\"<sup data-n=\"1086\">8</sup>?\n[ואף שלשון רש\"י מקורו במדרש<sup data-n=\"1087\">9</sup>, הרי: א) כבר נת' כמ\"פ שענינו של רש\"י לפרש פשש\"מ ולא להעתיק ולהודיע ל' המדרש, ובמקום שמעתיק דברי רז\"ל במדרש וכיו\"ב, הוא משום שלשון זה נוגע להבנת פשוטם של כתובים. וזהו גם כשכותב בפירוש \"רבותינו דרשו\" ו­כיו\"ב, ופשיטא שכן הוא כאשר מפרש הכתוב בלי לכתוב שמקור הפירוש הוא בדברי חז\"ל. ב) ועיקר: במדרש מתחיל הדרשה כאן \"כל דברי תורה צריכין זה לזה שמה שזה נועל זה פותח\", היינו",[["1079","1","פרשתנו כא, כא."],["1080","2","דברים ב, כו."],["1081","3","פרשתנו כ, יד."],["1082","4","שופטים יא, יז."],["1083","5","בדפוס שני וכמה כת\"י רש\"י (שתח\"י): הוא משה."],["1084","6","ראה גם משכיל לדוד כאן."],["1085","7","והיינו דהתחלת פרש\"י \"ובמקום אחר כו'\", הוא התחלת התירוץ."],["1086","8","להעיר שכל זה (מהתיבות \"הכתובים הללו\" עד \"הם משה\") ליתא בדפוס ראשון ובב' כת\"י רש\"י (שתח\"י)."],["1087","9","תנחומא פרשתנו כג. במדב\"ר פי\"ט, כח. ועד\"ז הוא בתנחומא (באבער) שם נב. ילקו\"ש פרשתנו עה\"פ (רמז תשסד קרוב לסופו)."]]],[1301430190,"שתוכן מאמר המדרש הוא ביאור כללי<sup data-n=\"1088\">10</sup> בדרך \"כל דברי תורה\"<sup data-n=\"1089\">11</sup>, אבל בפרש\"י שכוונתו רק לבאר פרטי פסוקים אלה, למאי נפק\"מ ההקדמה ש\"הכתובים הללו צריכים זה לזה זה נועל וזה פותח\"?].\nב) מהו כפל הלשון (והענין) \"שמשה הוא ישראל וישראל הם משה<sup data-n=\"1090\">12</sup> (לומר לך שנשיא הדור הוא ככל הדור)\"?\nג) כשם שבפרטי הענין כותב את שני הצדדים, \"שמשה הוא ישראל וישראל הם משה\", כך הו\"ל לכאורה לפרט ב­סיכום פירושו, לא רק \"שנשיא הדור הוא ככל הדור\" אלא גם \"וכל הדור הוא כמו הנשיא\" וכיו\"ב?\nד) מהו תוכן הטעם \"כי הנשיא הוא הכל\"<sup data-n=\"1091\">13</sup>, ומהי ההוספה בזה על מה שאמר לפנ\"ז \"שנשיא הדור הוא ככל הדור\"<sup data-n=\"1092\">14</sup>? ויתירה מזו — לכאו' ה\"ז סתירה מיני' ובי': בתחלה משמע שנשיא הדור הוא רק כמו כל הדור<sup data-n=\"1093\">15</sup> (ולא ממש \"כל ה­דור\"), ובהמשך כותב \"כי הנשיא הוא הכל\", שאינו רק \"ככל הדור\" בכ\"ף ה­דמיון, כ\"א \"הכל\" ממש?\nג. ויש להקדים ביאור דיוק לשון רש\"י \"ובמקום אחר תולה השליחות ב­משה שנאמר ואשלח כו'\", דלכאורה הו\"ל לקצר ולומר \"ובמקום אחר נאמר ואשלח\" וכיו\"ב.\nויש לומר, שבלשון זה מודגש הקושי בכתוב כאן ע\"פ פשש\"מ, שאותו בא רש\"י ליישב בפירושו.\nוהביאור בזה:\nזה שבכתוב דידן (בשליחות לסיחון) כתיב \"וישלח ישראל מלאכים\", ובכתוב הקודם (בשליחות למלך אדום) נאמר \"וישלח משה מלאכים\" — אין לפרש ה­כוונה בזה שהמשלח למלך אדום הי' משה והמשלח לסיחון הי' עם ישראל. כי\nפשוט ששילוח המלאכים אל מלך אדום הי' בשליחות עם ישראל, כהמשך כל הפרשה שם<sup data-n=\"1094\">16</sup> \"כה אמר אחיך ישראל גו'<sup data-n=\"1095\">17</sup> וירדו אבותינו מצרימה גו' ונצעק אל ה' וישמע קולנו גו'\", דכל תוכן ה­דיבורים הוא בנוגע עם ישראל<sup data-n=\"1096\">18</sup>, ומה שנאמר \"וישלח משה\" מובן בפשטות, כי כל מעשיהם של עם ישראל היו ונעשו על ידי משה, והוא הוא ששלח את המלאכים בפועל<sup data-n=\"1097\">19</sup>;\nולאידך — גם כשנאמר \"וישלח ישר­אל\" פשוט שהשילוח בפועל הי' על ידי",[["1088","10","להעיר גם ממרז\"ל (ירוש' ר\"ה פ\"ג ה\"ה. תוס' כריתות יד, סע\"א) \"ד\"ת עניים במקומן ו­עשירים במ\"א\"."],["1089","11","ולכן מסיים (בתנחומא ושמו\"ר שם) וכותב עוה\"פ \"הכתובים אלו צריכים זל\"ז\"."],["1090","12","ראה בהנסמן בהערה 8, שליתא שם תיבות אלו (ורק ממשיך — אחרי הביאו הפסוקים: אלא לומר לך שנשיא כו')."],["1091","13","וליתא בדפוס שני דרש\"י. וכן ליתא במדרשים הנ\"ל."],["1092","14","בא' מכת\"י רש\"י (שתח\"י) — אחרי הבאת הכתובים — \"ללמדך שנשיא הדור הוא הכל\" ותו לא."],["1093","15","כ\"ה בדפוסים שלפנינו וכ\"ה בדפוס שני (אלא שליתא שם ההמשך, כנ\"ל הערה 13). אבל בדפוס ראשון וכמה כת\"י רש\"י (שתח\"י) \"הוא כל הדור\" (כמו בתנחומא ושמו\"ר שם. ובתנחומא (באבער) ויל\"ש שם — כברש\"י שלפנינו)."],["1094","16","כ, יד­טז."],["1095","17","וראה פרש\"י שם: מה ראה להזכיר כאן אחוה כו'."],["1096","18","וראה שם גם בההמשך (כ, יט) \"ויאמרו אליו בנ\"י\"."],["1097","19","וראה עץ הדעת טוב (להרח\"ו) שם (כ, יד) להיפך, כי ישראל הם השולחים אמנם לפי עצת משה כו'."]]],[1301430191,"משה, ומה שנאמר \"וישלח ישראל\" הוא לפי שהשליחות היתה בשביל ומכל עם ישראל, ונעשית בפועל על ידי משה — ככל הדברים הנוגעים לכלל ישראל ש­היו ע\"י משה<sup data-n=\"1098\">20</sup>.\nועפ\"ז — השליחות לסיחון והשליחות למלך אדום אין ביניהם הבדל, אלא רק שינוי בלשון הכתובים.\nוזהו מה שמדייק רש\"י — \"ובמקום אחר תולה השליחות כו'\", שכוונתו, שה­שאלה בשינוי לשון הכתובים כאן אינה בנוגע למה שאירע בפועל (אם משה שלח המלאכים או ישראל), כ\"א רק במי תולה הכתוב השליחות, כלומר, מה טעם לשינוי לשון הכתוב — דגבי אדום תלה הכתוב השליחות במשה, וכאן תלה ה­כתוב השליחות בישראל,\nובפרט שלכאורה איפכא מסתברא, דאם בהשליחות למלך אדום, שבה מוד­גש בהכתובים שהשולח הוא כלל ישר­אל (\"כה אמר אחיך ישראל\"), נאמר שם \"וישלח משה\", עאכו\"כ שהי' צריך לומר כן בשליחות לסיחון (שאין בה הדגשה זו).\nד. והנה לכאורה הי' מקום לבאר ש­תליית השליחות במשה או בישראל אינה רק ענין צדדי (— בלשון הכתוב), אלא זה מבאר מי הי' יוזם השליחות (דמכיון שהשליחות באה ביוזמתו, הרי שהשלי­חות תלוי' בו)<sup data-n=\"1099\">21</sup>.\nוזהו טעם החילוק שבאדום תולה ה­כתוב השליחות במשה, וכאן — בישראל, כי שאני השליחות למלך אדום מהשלי­חות למלך סיחון<sup data-n=\"1100\">22</sup>:\nגבי אדום היתה השליחות ע\"פ ציווי ה'<sup data-n=\"1101\">23</sup>, ולכן תולה הכתוב השליחות במשה, שהוא עבד ושליח השם ששומע הוראת הקב\"ה ומקיימן בפועל (ועד שאין ה­כתוב צריך לכתוב שהשם ציוהו על כך, כי מובן מאליו שכן הוא, וכדמצינו<sup data-n=\"1102\">24</sup> בכמה מקומות שלא נאמר בתורה ציווי",[["1098","20","משא\"כ ע\"פ המדרש (ראה מדרש לק\"ט כאן), שלמלך אדום שלח משה, משא\"כ למלך סיחון שלחו ישראל (\"ברשות משה\", אבל לא משה עצמו). ע\"ש הטעם. ובאו\"א — ראה ש\"ך עה\"ת כאן."],["1099","21","וזה שבשילוח המרגלים מפורש בכתוב \"וישלח אותם משה\" (שלח יג, ג. טז. יז. יד, לו), אף שסיבתו הי' מצד זה \"שבאו ישראל ואמרו (דברים א, כב) נשלחה אנשים לפנינו\" (רש\"י ר\"פ שלח) — י\"ל כי מכיון שהקב\"ה אמר לו \"שלח לך — לדעתך, אני איני מצוה לך אם תרצה שלח\", הי' זה תלוי ברצונו של משה, ולכן נק' על שמו (ראה דברים א, כג \"וייטב בעיני הדבר ואקח גו'\"). ועוד ועיקר: שליחות ראשי י\"ב שבטים \"ראשי בני ישראל המה\" (שלח יג, ג) — אין מתאים לייחסה לבנ\"י, כ\"א למשה, נשיא הראשים. וראה המשך הכתוב דברים (שם) \"ואקח מכם שנים עשר אנשים גו'\"."],["1100","22","במושב זקנים עה\"ת כאן, דמה שלא שלח משה כאן (בסיחון) כמו בראשונה בהשליחות למלך אדום הוא \"כי ידע שיש לו למות\" (וצ\"ע במ\"ש שלא שלח משה, והרי מפורש ששלח בפ' דברים. ואולי כוונתו שלכן לא נאמר כן מפורש בתורה כאן). ובכל אופן מ\"ש בטעם שלא שלח \"כי ידע שיש לו למות\" הוא היפך פרש\"י מטות לא, ג \"אע\"פ ששמע שמיתתו תלוי' בדבר עשה בשמחה וכו'\" (ובנ\"י לא רצו ללכת — ראה פרש\"י שם, ה). ועד\"ז הוא במושב זקנים מטות שם, ב (אלא — שספר זה הוא ליקוט מכמה מפרשים). וראה מדרש הגדול ופנים יפות כאן."],["1101","23","בעץ הדעת טוב שם: השי\"ת לא ציוהו בכך כי אין רצונו ית' להכניסו לארץ אבל משה בעצמו ביקש לשלחם לסיבה הנ\"ל (שיוכל ליכנס לארץ).\nאבל ע\"ד הפשט אין הכרח לפרש, דמה שנאמר בתורה בהליכת בנ\"י אל א\"י — כוונת משה בזה היתה לפעול ביטול שבועת ה' (פרשתנו כ, יב) \"לא תביאו\". ובפשטות הי' זה כחלק מהנהגת משה את בנ\"י במדבר בדרך (שהם יכנסו לארץ). וראה פנים יפות שם, יד."],["1102","24","ראה לקו\"ש חי\"ג ע' 72. וש\"נ."]]],[1301430192,"השם אל משה)<sup data-n=\"1103\">25</sup>; משא\"כ גבי סיחון, הרי מפורש ברש\"י כאן<sup data-n=\"1104\">26</sup> שהקב\"ה לא צוה לפתוח לו בשלום<sup data-n=\"1105\">27</sup>, וא\"כ יש מקום לו­מר, שמטעם זה נאמר \"וישלח ישראל\", ללמדנו, שבנ\"י הם הם שתבעו שליחות זו, ומשה הסכים על ידם<sup data-n=\"1106\">28</sup>, ולכן נאמר \"וישלח ישראל\".\nוכדי לשלול פירוש זה מתחיל רש\"י פירושו — \"ובמקום אחר תולה השליחות במשה שנאמר ואשלח מלאכים ממדבר קדמות\", היינו שמפורש ש(גם) שליחות זו — דמשה, ואין לייחס ולתלות אותה (רק) בישראל<sup data-n=\"1107\">29</sup>; ואח\"כ ממשיך רש\"י \"וכן וישלח משה מלאכים מקדש אל מלך אדום וביפתח הוא אומר וישלח ישראל מלאכים אל מלך אדום וגו'\" — כלומר, גם בשליחות למלך אדום אין כוונת הכתוב לתלות השליחות רק במשה (ולא בבנ\"י), שהרי מפורש \"וישלח ישראל\".\nוזהו שממשיך רש\"י \"הכתובים הללו צריכים זה לזה זה נועל וזה פותח ש­משה הוא ישראל וישראל הם משה\":\nאם בשליחות לאדום הי' כתוב רק \"וישלח משה\", הי' \"זה נועל\", כלומר, זה הי' נועל (בפני הפירוש) ושולל שהשלי­חות לאדום היתה (גם) של בנ\"י, כ\"א משה עשה זאת בתור שליח השם ואין לתלות השליחות בישראל (אף שתוכן השליחות הוא בשבילם)<sup data-n=\"1108\">30</sup>; וכן לאידך — אם בשליחות לסיחון הי' כתוב רק \"ו­ישלח ישראל\" הי' \"זה נועל\" הפי' ד­שליחות משה בזה, כי השליחות לסיחון יש לתלות רק בישראל ולא במשה.\nולכן בא הכתוב השני ו\"פותח\" ומגלה — \"שמשה הוא ישראל וישראל הם משה\", דמ\"ש \"וישלח משה\" הרי זה כ­אילו נאמר \"וישלח ישראל\" (כי \"משה הוא ישראל\"), ומש\"נ \"וישלח ישראל\" הוא כאילו נאמר \"וישלח משה\" (כי \"ישראל הם משה\").\nה. אלא שצריך ביאור — איך אפשר לומר \"שמשה הוא ישראל וישראל הם משה\"? ומבאר רש\"י \"לומר לך שנשיא הדור הוא ככל הדור כי הנשיא הוא הכל\" —\nדי\"ל שב' הענינים בפרש\"י, \"נשיא הדור הוא ככל הדור כי הנשיא הוא ה­כל\", הם כנגד שני הענינים שלפנ\"ז<sup data-n=\"1109\">31</sup> — \"משה הוא ישראל וישראל הם משה\":",[["1103","25","וראה פנים יפות שם דישראל לא רצו לשלוח אלא משה שלח בשבילם ולא חש שמיתתו תלוי' בזה \"כמו שפרש\"י (שבהערה 22) גבי מלחמת מדין\". ועד\"ז הוא באלשיך שם. וראה גם צרור המור וש\"ך עה\"ת שם."],["1104","26","כא, כב."],["1105","27","ולהעיר מילקוט כאן (רמז תשסד קרוב לסופו) שהקב\"ה א\"ל \"אני אמרתי החל רש והתגר בו מלחמה ואתה משלח שלוחי שלום\" (אלא שב­ילקוט הוא להפירוש דמשה שלח, כהפסוק בדברים ובפרש\"י שם)."],["1106","28","ראה מדרש לקח טוב כאן."],["1107","29","ובזה גם סותר פי' החזקוני כאן, דשתי אגרות כתבו אחת של משה לשלום וא' של ישראל למלחמה. ומה שלא ס\"ל לרש\"י כן, ובפרט ששם נאמר בכתוב \"מדבר קדמות\"<sup data-n=\"e25\">*</sup> — כי בפשטות, ב­משנה תורה חוזר על דברים שאירעו לפנ\"ז ולא ענינים חדשים לגמרי (אם לא שיש הכרח גמור לומר כך). ועצ\"ע."],["1108","30","ומה שנאמר שם (ב, יט) \"ויאמרו אליו בני ישראל במסלה נעלה\" — בפשטות אינה שליחות חדשה, כ\"א המשך השקו\"ט של המלאכים שלוחי בנ\"י ומלך אדום. וראה לקו\"ש ח\"ח ע' 144 ואילך ובהערות שם."],["1109","31","וצ\"ע בלשון רש\"י \"כי הנשיא כו'\". ולהעיר שברוב כת\"י רש\"י (שתח\"י) ליתא לתיבה זו."],["e25","*","ומפרש בפשוטו ש\"מ (בדברים שם) שאינו שם מקום (ראה מלבי\"ם כאן), אלא \"למדתי. . שקדמה. . שקדמת כו'\"."]]],[1301430193,"זה ש\"משה הוא ישראל\" הוא לפי \"שנשיא הדור הוא ככל הדור\", כלומר — אין פירוש הדברים, דכאשר המדובר ב­התעסקותו של משה בענין השייך לצרכי כלל ישראל אין הוא איש פרטי בזה, אלא הוא עושה זאת עבור הכלל, וב­מילא אפשר לכתוב \"משה\" (העושה ב­פועל) או \"ישראל\" (שבשבילם נעשה) — אלא שעצם מציאותו של משה, להיותו \"נשיא הדור\", הוא \"ככל הדור\". היינו דנשיא הדור הוא (איש) צבורי בעצם מהותו, ובמילא מה שהוא עושה ה\"ז עשיית ישראל.\nוכן לאידך — זה \"שישראל הם משה\" הוא לפי \"שהנשיא הוא הכל\": כאן לא כתב רש\"י \"כל הדור\", כי אין כוונתו כאן שמהותו של נשיא הדור היא — כל אנשי הדור, אלא שהכל<sup data-n=\"1110\">32</sup> — כל צרכי הכלל — הם (צרכיו ובאים על ידי) ה­נשיא<sup data-n=\"1111\">33</sup>, דכל מה שיש אצל בנ\"י בא מ(כח) הנשיא [כמו שמצינו בנוגע לבנ\"י במדבר, שכל צרכיהם הגשמיים (אכילה (מן ובשר)<sup data-n=\"1112\">34</sup> ושתי'<sup data-n=\"1113\">35</sup>) קיבלו על ידי משה, וכן כל התורה נמסרה להם (וכמה ציווים וכיו\"ב) על ידי משה]. ומכיון שכל עניני וצרכי בנ\"י באים ממשה (הנשיא), נמצא ש\"ישראל הם משה\"<sup data-n=\"1114\">36</sup>.\nוזהו ש\"הכתובים הללו\" — שתולים השליחות פעם במשה ופעם בישראל — באים \"לומר לך\", ששליחות שלכאורה יש לייחס ולתלות רק במשה (בתור שליח השם), הנה היא שייכת לכל ישר­אל, וכן לאידך, ששליחות שלכאורה היא של ישראל, תולה אותה הכתוב ב­משה — לפי \"שנשיא הדור הוא ככל הדור. . הנשיא הוא הכל\".\nו. מה\"ענינים מופלאים\" שבפירוש רש\"י:\nבמדרש<sup data-n=\"1115\">37</sup> (מקורו של פרש\"י) הלשון הוא \"שראש הדור הוא כל הדור\", ורש\"י משנה וכותב \"נשיא הדור הוא ככל ה­דור\"<sup data-n=\"1116\">38</sup>.\nויש לומר, שזהו בהתאם לחידושו של רש\"י (הנ\"ל): \"ראש הדור\" פירושו (ע\"ד",[["1110","32","להעיר מהלשון \"שלום שקול כנגד הכל\" (פרש\"י בחקותי כו, ו)."],["1111","33","להעיר מהגי' בדפ' ראשון \"שעל פי הנשיא הוא הכל\"."],["1112","34","כפשטות הכתובים בפ' בשלח — טז, ב ואילך. וראה פרש\"י שם, לה. וראה לקו\"ש חי\"ח ע' 260. וראה שם בנוגע ענני הכבוד."],["1113","35","ראה שם טו, כד­ה. פרשתנו כ, ז ואילך. וראה פרש\"י פרשתנו כא, כ. וראה לקו\"ש שם."],["1114","36","ועפכ\"ז יש לבאר ההוספה והחידוש כאן לגבי פרש\"י (ר\"פ יתרו) \"שקול משה כנגד כל ישראל\"<sup data-n=\"e26\">*</sup>, כי (נוסף לזה שכאן למדים משינוי הכתובים שאין זה ענין השייך רק למשה ולישראל בדורו כ\"א לכל נשיא הדור, הרי) זה שמשה שקול כנגד כל ישראל הוא ענין בגדלותו וחשיבותו של משה, וכאן — המדובר הוא בשייכותו לדורו. ולהעיר מגו\"א לפרש\"י שם."],["1115","37","שבהערה 9. וראה לעיל הערה 15 (ובהערה הבאה)."],["1116","38","ואולי י\"ל, שדברי רש\"י \"נשיא הדור הוא ככל הדור כי הנשיא הוא הכל\" — הוא פירוש ו­פירוט לשון קצר דהמדרש \"ראש הדור הוא כל הדור\". וראה להלן בפנים."],["e26","*","במכילתא יתרו שם ממשיך \"וישראל כמשה שקול רב כתלמיד ותלמיד כרב\". אבל לכאורה אינו פשוטו של מקרא. ולהעיר ממכילתא בשלח (ר\"פ השירה) \"משה שקול כנגד ישראל וישראל שקולין כמשה בשעה שאמרו שירה\". ושם \"מגיד שאמר משה שירה כנגד כל ישראל\". ושם טו, יג \"משה שנשקל כנגד הכל. . שהי' משה שקול כנגד הכל\". וראה גם ספרי מטות לא, ו. וגם שם הביא רש\"י רק צד א' — שהי' פינחס שקול כנגד כולם. ואכ\"מ."]]],[1301430194,"ראש כפשוטו) שהוא מנהיג את כל הדור; משא\"כ \"הנשיא\" הוא לשון נשי­אות והרמה, היינו שהוא שם התואר ל­אדם מרומם ומנושא.\nולכן: בלשון המדרש \"שראש הדור הוא כל הדור\" אפשר לפרש הכוונה, ד­מכיון שהוא הראש המנהיג את כל הדור, ועל ידי הנהגה אחת ואחידה של הראש — נעשים כל אנשי הדור למציאות אחת, מציאות הראש, לכן \"ראש הדור הוא כל הדור\",\n[ולהעיר משו\"ת הרשב\"א<sup data-n=\"1117\">39</sup> בענין מלך \"המלך כצבור שהצבור וכל ישראל תלויין בו\"<sup data-n=\"1118\">40</sup>, שהטעם שהמלך הוא כ­צבור, הוא לפי שהצבור וכל ישראל תלויים בו<sup data-n=\"1119\">41</sup>],\nולפ\"ז נמצא, דמה ש\"ראש הדור הוא כל הדור\" ה\"ז (רק) בענינים הצבוריים שלו, והיינו בענינים שעושה עבור כל ישראל וכיו\"ב, שעי\"ז מתאחדים כל ישראל כמציאות אחת.\nאבל בלשונו של רש\"י \"שנשיא הדור הוא ככל הדור כי הנשיא הוא הכל\", י\"ל שבזה מודגש ש\"נשיא\" הדור, גם כמו שהוא מרומם ומנושא (בפני עצמו), הרי הוא ככל הדור.\nוהחידוש שבדבר הוא בשני הקצוות:\nמחד גיסא, מכיון שעניניו ה\"ה חלק ממציאותו בתור נשיא, הרי מובן, שפעו­לותיו ומעשיו, שלכאורה הי' מקום לומר שהם \"בשוה\", עכ\"פ \"בערך\" למעשי שאר בנ\"י, גם בהם הוא שונה ומנושא<sup data-n=\"1120\">42</sup>, לגבי כל העם.\nולאידך, מכיון ש\"נשיא הדור הוא ככל הדור\", הרי גם עניניו הכי נעלים של הנשיא, שלכאורה הם בבחי' \"משכמו ומעלה גבוה מכל העם\"<sup data-n=\"1121\">43</sup> ואינם בערך לאנשי הדור, הרי מכיון שגם הם חלק ממציאות הנשיא (הנשיא הוא הכל) — הרי הם פועלים ונמשכים באנשי הדור<sup data-n=\"1122\">44</sup>.\nז. פ' חוקת חלה בכמה שנים בין ג' תמוז (היום אשר \"חופשה ניתנה לו\", התחלת הגאולה) וי\"ב­י\"ג תמוז — יום גאולת כ\"ק מו\"ח אדמו\"ר, נשיא הדור, ממאסרו אשר נאסר על הרבצת התורה וחיזוק הדת.\nויש למצוא רמז לעבודתו ואופן נשי­אותו בפרש\"י הנ\"ל — כי אצלו הי' נראה בגלוי, ובפרט בעבודתו הנ\"ל, ש\"נשיא הדור הוא ככל הדור. . הנשיא הוא הכל\":\n\"העבודה הגדולה\" אשר עבד כ\"ק",[["1117","39","ח\"א סי' קמח."],["1118","40","ראה בארוכה לקו\"ש חי\"ט ע' 165 ואילך. ושם נת' החילוק בין לשון זה ללשון הרמב\"ם (הל' מלכים פ\"ג ה\"ו) בנוגע למלך \"שלבו הוא לב כל קהל ישראל\"."],["1119","41","להעיר מתניא אגה\"ק סכ\"ט (קמח, ב) מ\"מ\"ש האריז\"ל\" בביאור הטעם ש\"מצות התלויות במלך. . מוציא כל ישראל כי הוא כללות כולם\", ומשנה מל' המשנת חסידים (מסכת חיוב הנשמות פ\"ב מ\"א) \"שמפני חשיבותו כל המצות הראויים לו עולים לכל ישראל כו'\". וראה לקו\"ש חי\"ח ע' 192 סוף הערה 55."],["1120","42","להעיר מצפע\"נ ר\"פ קרח, שמפרש מחלוקת קרח וטעותו, היפך האמת אשר גם בדבר שהלויים דומים לכהנים, היינו גבי מצות שמירה, מ\"מ כהן למעלה והם למטה. עיי\"ש בארוכה."],["1121","43","ל' הכתוב (בנוגע לשאול) ש\"א ט, ב (וראה גם שם י, כג). וראה אוה\"ת בראשית (כרך ד) ע' 1528. שה\"ש (כרך ב) ע' תיד­טו. ועוד."],["1122","44","ראה תניא פמ\"ד \"ואף כי מי הוא זה ואיזהו אשר ערב לבו לגשת להשיג אפי' חלק אחד מני אלף. . מ\"מ הרי אפס קצהו ושמץ מנהו מרב טובו ואורו מאיר לכללות ישראל כו'\". וראה בכל הנ\"ל בארוכה לקו\"ש ח\"ד ע' 1051 ובהערות שם."]]],[1301430195,"מו\"ח אדמו\"ר \"בהרבצת תורה וחיזוק הדת\"<sup data-n=\"1123\">45</sup> במדינה ההיא (שבדרך הטבע — היא שגרמה להמאסר) — וכן בכל מקום מגורו לאחר צאתו ממדינה ההיא<sup data-n=\"1124\">46</sup> — לא היתה מוגבלת בתחום מסויים של יהדות, כ\"א עסק בכל השטחים<sup data-n=\"1125\">47</sup> — הן בכל ה­שייך לחיזוק הדת: שילוח רבנים ושוח­טים למקומות שהיו זקוקים להם, בנין מקוואות, יסוד ישיבות וחדרים בשביל תשב\"ר, עד להרבצת התורה לכל ישר­אל, וגם הפצת רזי דרזין דאורייתא; והן הצלת נפשות כפשוטה, בפדיון שבויים, עזר וסיוע גשמיים לעניים וכל הזקוקים לזה (כידוע פרשת הימים ההם, ומה ש­ידוע הוא — מעט מזעיר, מטעמים מו­בנים).\nובכל עבודות אלו, שחלוקות מן ה­קצה אל הקצה, היתה התעסקותו בזה במסירה מוחלטת, עד למסירת נפש בפועל.\nוכך ראו במוחש אצלו הענין ד\"נשיא הדור הוא ככל הדור\" — ובמילא — \"הנשיא הוא הכל\", שכל עניני צרכי בנ\"י הרוחניים והגשמיים באים ונמשכים ממנו.\n<span data-k=\"q\">(משיחת ש\"פ חוקת תשמ\"א)</span>",[["1123","45","ל' כ\"ק מו\"ח אדמו\"ר במכתבו לחגיגת י\"ב תמוז הראשונה — בשנת תרפ\"ח (נדפס בסה\"מ תש\"ח ע' 263. אג\"ק שלו ח\"ב ע' פ. ועוד)."],["1124","46","ראה לקו\"ש חי\"ח ע' 302 ואילך."],["1125","47","ראה גם מכתב ג' תמוז השי\"ת (לקו\"ש חי\"א ע' 209 ואילך. ועוד)."]]],[1301430196,"<h3>שיחה א</h3>\nא. נוסח ברכת הגומל (להלכה<sup data-n=\"1126\">1</sup>) הוא \"ברוך כו' הגומל לחייבים טובות ש­גמלני טוב<sup data-n=\"1127\">2</sup>\", ונוסח ברכת הנס (שנעשה ליחיד) הוא \"ברוך כו' שעשה לי נס במקום הזה\"<sup data-n=\"1128\">3</sup>. ומדייק כ\"ק מו\"ח אדמו\"ר (במאמרו<sup data-n=\"1129\">4</sup> שאמר בש\"ק (ט\"ז תמוז תרפ\"ז) שלאחרי גאולתו ממאסרו במדינה ההיא), וז\"ל:\nוצריך להבין למה נשתנה נוסח ברכה זו מברכת הנסים, דבברכת הנס אומר ברוך שעשה לי נס, ואינו מזכיר בברכתו חובה לעצמו, והיינו שימצא חוב בעצמו אשר בעבורו עמד ר\"ל בסכנה והוא ב­עצמו מודה שהי' חייב בדבר הסכנה ח\"ו אלא שהקב\"ה עשה לו נס, משא\"כ ב­ברכה זו אומר הגומל לחייבים טובות שמזכיר חוב לעצמו, והוא בעצמו מודה שהוא החייב בזה אלא שזהו מחסדי הוי' ודרכי הוי' שהוא ית' גומל גם לחייבים טובות. עכ\"ל.\nוהנה בהמשך המאמר לא נתפרשה, לכאורה, התשובה לשאלה זו (\"למה נשתנה נוסח ברכה זו מברכת הנסים\"), ורק לאחרי שמבאר ענין \"ארבעה צרי­כין להודות\"<sup data-n=\"1130\">5</sup> בעבודת האדם, שהם ד' סוגים במניעות ועיכובים על עבודת השם<sup data-n=\"1131\">*5</sup> (שעל ידם נוצר מצב של סכנה רוחנית לאיש ישראל), והקב\"ה עומד לימין כל אדם ונותן לו כח להתגבר על המניעות ועיכובים — מסיים את המאמר בביאור קצר בתוכן אמירת \"הגומל ל­חייבים\", וז\"ל:\nוזהו נוסח ברכה זו הגומל לחייבים טובות, דהלא כל ישראל מחוייבים בלי­מוד התורה ובקיום המצות. . ואם מצד איזה סיבה לא קיים זה הלא הוא האשם בזה. . כל המניעות ועכובים שבזמן ה­גלות הם רק נסיונות. . ולכן בברכה זו מזכיר חוב לעצמו.\nב. ונראה לבאר התשובה לשאלה הנ\"ל, ובהקדמה:\nבבית יוסף<sup data-n=\"1132\">6</sup> מפרש נוסח הברכה \"ה­גומל לחייבים\" — \"כלומר אפילו לאותם שהם חייבים דהיינו שהם רשעים. . עכ\"ז גומל להם טובות, וגם אני כאחד מהם שאף על פי שאיני הגון גמלני בכל טוב\".",[["1126","1","רמב\"ם הל' ברכות פ\"י ה\"ח. טור (וב\"י) ושו\"ע או\"ח ר\"ס ריט. סידור אדה\"ז."],["1127","2","כן הוא בסידור אדה\"ז (וכ\"ה בכת\"י הרמב\"ם החתום בעצם כי\"ק (רמב\"ם ספר אהבה — ירושלים, תשד\"מ) ועוד כת\"י — ראה רמב\"ם הוצאת קאפח). אבל ברמב\"ם לפנינו, טושו\"ע שם \"שגמלני כל טוב\". וראה רד\"ה ברוך הגומל שבהערה 4."],["1128","3","ברכות נד, א. רמב\"ם שם ה\"ט. שו\"ע שם סרי\"ח ס\"ד. סדר ברכת הנהנין לאדה\"ז רפי\"ג."],["1129","4","ד\"ה ברוך הגומל (נדפס בסה\"מ קונטרסים ח\"א קפד, ב ואילך. סה\"מ תרפ\"ז ע' ריא ואילך)."],["1130","5","ברכות נד, ב. — ולהעיר, שנלמדים בגמ' שם מהכתובים דמזמור קז שבתהלים — המזמור המתאים לשנותיו של כ\"ק מו\"ח אדמו\"ר במשך השנה (י\"ב תמוז תשמ\"ו­תשמ\"ז (שנת הדפסת שיחה זו)), ע\"פ תקנת הבעש\"ט (קובץ מכתבים לתהלים (בסוף תהלים אהל יוסף יצחק) ע' 214. ועוד) \"לאמר הקאפיטל תהלים המתאים למספר שנותיו\" (וראה לקו\"ש ח\"ה ס\"ע 103 ואילך (וש\"נ) בנוגע להמשך הזמן לאחרי ההסתלקות)."],["1131","*5","להעיר גם מחדא\"ג מהרש\"א ברכות שם."],["1132","6","לטואו\"ח ר\"ס ריט."]]],[1301430197,"ומשמעות פירושו, שהתואר \"חייבים\" כאן הוא כעין \"בלתי ראויים\" לקבלת חסדי השם, והיינו שהמברך מודה ו­משבח להקב\"ה על עשיית חסד זה עמו אף שאינו ראוי לכך (\"אע\"פ שאיני הגון\")<sup data-n=\"1133\">7</sup>.\nאמנם במאמר כ\"ק מו\"ח אדמו\"ר הנ\"ל מפורש<sup data-n=\"1134\">8</sup>, דהזכרת \"חובה לעצמו\" ענינה \"שימצא חוב בעצמו אשר בעבורו עמד ר\"ל בסכנה והוא בעצמו מודה שהי' חייב בדבר הסכנה ח\"ו\".\nויש לומר, ששינוי זה לגבי מ\"ש הבית יוסף נוגע להבנת תירוץ השאלה \"למה נשתנה נוסח ברכה זו (ברכת הגומל) מ­ברכת הנסים\":\nאת\"ל שאמירת \"הגומל לחייבים\" כוונתה רק להודות לה' על הטובה ש­נעשה עמו אע\"פ שאינו ראוי לכך — תמוה, אמאי לא תיקנו לשון זה גם בברכת הנסים?\nולכאורה, כלפי לייא: ברכת הגומל אין חיובה דוקא על הצלה שבאה על ידי נס, ואדרבה, הארבעה שצריכים ל­הודות הם במצבים שע\"פ טבע יכולים לצאת מהם בשלום (שלכן אין הם חייבים גם בברכת הנס אא\"כ ניצלו על ידי נס מיוחד כו'<sup data-n=\"1135\">9</sup>), משא\"כ ברכת הנס חיובה הוא על נס היוצא ממנהגו של עולם<sup data-n=\"1136\">10</sup>.\nוא\"כ, אם בהצלה טבעית יש להודות להשם על שגמל עמו טובה זו \"אע\"פ שאיני הגון\" — כש\"כ וק\"ו כשמודים ל­הקב\"ה על שידוד מערכות הטבע, שהי' צריך להוסיף בההודאה ההדגשה ש­נעשה לו הנס \"אע\"פ שאיני הגון\".\nג. לכאורה יש מקום לחלק בין ברכת הגומל לברכת הנס:\nברכת הגומל היא מברכות הודאה, שמודה ומשבח לה' על הטובה שהגיעה לו, ולכן יש מקום להוסיף \"הגומל ל­חייבים טובות\", מכיון שזה מפליא יותר את החסד שנעשה עמו (שלמרות שאינו הגון מ\"מ נעשה עמו חסד זה);\nמשא\"כ ברכת הנס היא מברכות הראי' — שמברך על ראיית המקום ש­נעשה שם הנס, היינו שהברכה היא על עצם עשיית הנס במקום זה (המראה על גדלותו ית' שביכלתו לשדד מערכות הטבע), ובמילא אין מקום להוסיף הפרט ד\"הגומל לחייבים\" השייך להאדם ש­אירע עמו נס זה, ולא לעצם עשיית הנס.\nאבל [לבד זאת, שכאשר הנס נעשה לשאינו ראוי י\"ל שזהו נס גדול יותר, הרי] חילוק זה אינו מוכרח, כי מלשון",[["1133","7","ועי\"ז מגדיל בשבחו ית', דנוסף על עצם ה­ענין שהקב\"ה גמל עמו טוב, הרי עשה זאת למרות שהוא אינו ראוי לטובה זו."],["1134","8","וכן פי' בתשובת מהר\"ם מינץ סי\"ד (שהובא במג\"א ר\"ס ריט). וכן מוכח בפי' התפלות והברכות לר\"י ב\"ר יקר (רבו דהרמב\"ן) ח\"ב (ירושלים, תשכ\"ט. תשל\"ט). וראה גם שו\"ת מהר\"ם שיק או\"ח ספ\"ח. שו\"ת אבני נזר או\"ח סל\"ט. ערוך השולחן או\"ח סרי\"ט ס\"ד."],["1135","9","ראה מג\"א שם סרי\"ט סק\"ט. סדר ברכת הנהנין לאדה\"ז רפי\"ג."],["1136","10","ראה שו\"ע או\"ח סו\"ס ריח ובמג\"א שם. ט\"ז שם סרי\"ט סק\"ו. ערוך השולחן שם ס\"א­ד. ועוד. וראה גם ס' פי' התפלות והברכות (שבהערה 8): ומן הדין יחיד שנעשה לו נס הי' לו לברך הגומל. . אלא שנפטר ממנה ע\"י ברכה זו שעשה לי נסים שהיא גדולה ממנה שהרי הי' חולה כו' אינו נעשה לו נס שהרי רוב חולים מתרפאים כו'. ע\"ש. וצע\"ק בפרש\"י צו (ז, יב): דבר הודאה על נס שנעשה לו כגון יורדי הים כו' וחולה שנתרפא כו'. וראה סדור הנסמן בהערה 22."]]],[1301430198,"ברכת הנס (ליחיד<sup data-n=\"1137\">11</sup>) \"ברוך שעשה לי נס במקום הזה\" מוכח שההודאה והשבח<sup data-n=\"1138\">12</sup> הם (לא רק על עצם הנס, אלא) ע\"ז ש­הוא \"בעל הנס\" [שלכן חייבים רק \"כל<sup data-n=\"1139\">13</sup> יוצאי יריכו של אותו אדם. . הם ובני­הם עד סוף כל הדורות לברך. . שכולם שותפים באותו נס\"].\nוי\"ל, שכדי ליישב שאלה זו מוסיף כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1140\">14</sup> שהפירוש ב\"הגומל לחייבים\" הוא, ש\"מודה שהי' חייב בדבר הסכנה ח\"ו\" — דזה שייך רק בברכת הגומל, שהיא הודאה על הצלה, כלומר, כאשר לפנ\"ז הי' מצב של סכנה ואח\"כ ניצול ממנה, ולכן שייך לומר \"הגומל לחייבים\"<sup data-n=\"1141\">15</sup>, ש\"מודה שהי' חייב בדבר ה­סכנה ח\"ו\" (היינו שבאשמתו נעשה המצב שדרש הצלה מלמעלה);\nמשא\"כ ברכת הנס אינה דוקא על נס שהוא הצלה ממצב של סכנה. וע\"ד \"הרואה. . מעברות הירדן\"<sup data-n=\"1142\">16</sup> (המקום ש­עברו בו ישראל בימי יהושע<sup data-n=\"1143\">17</sup>), שנס זה (בקיעת הירדן) לא הי' בגדר הצלה מ­מקום סכנה אלא רק להקל עליהם העברת הירדן<sup data-n=\"1144\">18</sup>. שמזה מובן, שגם כש­מברכים על נס של הצלה, אין ההודאה על ביטול מצב סכנה, אלא על עצם החסד, שהקב\"ה עשה לו נס.\nולכן אינו מתאים בברכת הנס ענין \"הגומל לחייבים\", מכיון שאין הכרח שבעל הנס הי' במצב בלתי רצוי (סכנה וכיו\"ב) \"שהי' חייב בדבר הסכנה ח\"ו\"<sup data-n=\"1145\">19</sup> (וגם אם הי' במצב כזה — אין הכוונה בברכה זו להודות על ביטול מצב זה, כנ\"ל).\n[ועד\"ז הוא החילוק בין ברכת הגומל וברכת הנס בתוכנם הפנימי:\nברכת הגומל — שענינה הוא ההודאה על הצלה ממצב בלתי רצוי (סכנה כו') — שייכת לעבודת הנשמה בגוף, שהיא ירידה גדולה (כמבואר בארוכה בהמשך",[["1137","11","והרי כל השאלה (בהמאמר) מלכתחילה היא מברכת נס דיחיד, שהרי על נס דרבים (שנעשה לכל ישראל או לרובם — שו\"ע או\"ח סרי\"ח ס\"ב) אין לומר \"(הגומל) לחייבים\" — שהרי אדרבא זכות הרבים מסייעתם. ובכלל צ\"ל זהירות יתירה להזכיר חובה על כלל ישראל (ראה ישעי' ו, ה ואילך ובמפרשים. יבמות מט, ב), משא\"כ יחיד המזכיר חובה לעצמו.\n[ודוחק גדול לומר, שלא תיקנו לשון \"חייבים\" בברכת נס דכל יחיד מפני \"לא פלוג\"]."],["1138","12","ראה ברכות נד, א: על כולן צריך שיתן הודאה ושבח."],["1139","13","ל' אדה\"ז — סדר ברכת הנהנין פי\"ג ס\"א. וראה טושו\"ע או\"ח סרי\"ח ס\"ד ובנ\"כ."],["1140","14","היינו שהשאלה נכתבה בסגנון כזה, שמ­אריכות הביאור בהמאמר (בעבודת האדם) יובן ה­תירוץ על שאלה זו. וראה לקמן בפנים בסוף הסעיף."],["1141","15","וי\"ל שזהו גם הדיוק \"הגומל. . שגמלני\" — ע\"פ מרז\"ל (ברכות נו, סע\"ב) \"הרואה גמל בחלום מיתה נקנסה לו מן השמים והצילוהו ממנה\" (וראה רש\"י וחדא\"ג מהרש\"א שם, שהסימן הוא מצד ה\"נוטריקון של גמל\", השייך גם לתיבת \"גומל\")."],["1142","16","ברכות נד, א. טושו\"ע או\"ח ר\"ס ריח."],["1143","17","רש\"י ברכות שם."],["1144","18","בביאור הלכה (ר\"ס ריח) \"דהברכה לא נתקנה על פלאי הבורא כו' דנתקן רק אהצלת אדם מן המיתה בדרך נס\". ע\"ש באורך. אבל לכאורה צע\"ק מ\"מעברות הירדן\", כבפנים.\nובכל אופן: גם לפירושו י\"ל, דאף שהברכה נתקנה רק כשהיתה הצלה מן המיתה — מ\"מ, תוכן ההודאה והשבח אינו על ביטול הסכנה אלא על עשיית הנס (משא\"כ ברכת הגומל שתוכנה ההודאה שניצל מן הסכנה), כבפנים."],["1145","19","וע\"ד בפרשתנו (פ' בלק) — הנסים שנעשו לפינחס (ספרי, תנחומא, תיב\"ע ורש\"י סוף פרשתנו, סנהדרין פב, ב), שלא שייך לומר שהוא \"הי' חייב בדבר הסכנה\", ורק שגרם והביאה ע\"ע."]]],[1301430199,"מאמר כ\"ק מו\"ח אדמו\"ר), שירידה זו נותנת מקום שהאדם יכניס א\"ע למצב של סכנה ר\"ל (בד' האופנים ד\"ארבעה צריכים להודות\"); אלא שגם לאדם זה שהכניס עצמו למצב זה נותן הקב\"ה כח להנצל מהסכנה, על ידי ש\"גומל ל­חייבים טובות שגמלני טוב\" — (\"אין<sup data-n=\"1146\">20</sup> טוב אלא תורה שהוא טוב האמיתי\"<sup data-n=\"1147\">21</sup>);\nולכן אומרים בברכה זו \"הגומל ל­חייבים\", מכיון שהיא קשורה עם מצב של \"חייב\", סכנה רוחנית, והאדם מודה להשם שהצילו אף \"שהי' חייב בדבר הסכנה\", כנ\"ל.\nמשא\"כ ברכת הנס ענינה ההודאה והשבח להקב\"ה על ההתגלות האלקית שבמעשה נסים (שלמעלה — מל' ארים נסי<sup data-n=\"1148\">22</sup> — מטבע העולם), ולכן לא שייך בזה אמירת \"הגומל לחייבים\", שהרי אין כאן מצב של \"חייב\", כ\"א אדרבה, הת­גלות השם].\nד. אמנם לכאורה צ\"ע בגוף הפירוש הנ\"ל:\nברכת הגומל היא בנוסח שווה לכל ישראל, גם לצדיקים גמורים, ולכאורה תמוה ביותר לומר, שגם צדיק גמור \"הי' חייב בדבר הסכנה ח\"ו\"<sup data-n=\"1149\">23</sup>?\nבשלמא לפי' הב\"י שהכוונה ב­\"חייבים\" היא לענין קבלת הטוב (שה­אדם מודה שאינו הגון וראוי לטובה זו) יש לומר שזה שייך גם בצדיקים, ש­מחמת גודל ענוותנותם חושבים שאינם ראויים לחסדי ה'<sup data-n=\"1150\">24</sup>. וע\"ד שמצינו ביעקב ש\"התנצל<sup data-n=\"1151\">25</sup> על יראתו מפני עשו ולא די לו בהבטחתו כו' מפני היות קטן יעקב במאד מאד בעיניו כו' ואינו ראוי וכדאי כלל להנצל כו' שנדמה בעיניו שחטא\".\nאבל איך אפ\"ל שגם צדיק גמור צריך לחשוב (ובאמת) שחטא עד כדי כך<sup data-n=\"1152\">26</sup> שיהי' \"חייב בדבר הסכנה ח\"ו\"<sup data-n=\"1153\">27</sup>?\nוביותר אינו מובן: פירוש זה נאמר",[["1146","20","אבות פ\"ו, ג."],["1147","21","לשון כ\"ק מו\"ח אדמו\"ר סד\"ה הגומל שם."],["1148","22","ישעי' מט, כב (רש\"י יתרו כ, יז. חקת כא, ח. וראה סדור עם דא\"ח מד, סע\"ב (בעניננו — הודאה על נס). אוה\"ת בשלח ע' תרסה. ועוד)."],["1149","23","ולהעיר מעיון יעקב לע\"י ברכות (נד, ב ד\"ה על) \"גנאי הוא לת\"ח כמותו לומר כן (הגומל ל­חייבים)\". ט\"ז או\"ח סרי\"ט סק\"ג. ובס' מאמר מרדכי (ליוורנו, תקמ\"ד) או\"ח שם סק\"ו ד\"חייבים\" היינו \"חייבים דעלמא\".\nולהעיר שבשו\"ת לחמי תודה ס\"ה (שהובא ב­שערי תשובה ורעק\"א לשו\"ע או\"ח שם בריש הסימן) פי' \"חייבים\" (לא לשון \"חיוב של עונש\", אלא) \"לשון חוב. . שהאדם יש לו טובות הרבה אצל בוראו כו'\"."],["1150","24","וכדיוק ל' הב\"י, שמתחיל ד\"חייבים. . הם רשעים\", וממשיך \"וגם אני כאחד מהם שאע\"פ שאיני הגון כו'\" (ולא \"רשע\")."],["1151","25","ל' אדה\"ז בתניא אגה\"ק ס\"ב. וראה לקמן סעיף ה."],["1152","26","ראה טעמי המצות להרח\"ו פ' קדושים בטעם שהאריז\"ל נהג \"לומר פרטי הוידוים\". ולהעיר מלקו\"ש ח\"ט ע' 206 ואילך."],["1153","27","בפרש\"י וישלח (לב, יא) \"נתמעטו זכיותי כו' שמא משהבטחתני נתלכלכתי בחטא ויגרום לי להמסר ביד עשו\". וברא\"ם שם מפרש ד\"ממעוט זכיותיו לחודי' אין לו לירא כל זמן שלא חטא דאין יסורין בלא חטא ולא מיתה בלא עון\". וראה פרש\"י תהלים קז, יא.\nאבל ראה חדא\"ג מהרש\"א ברכות (ד, א) ש­מסקנת הגמ' (שבת נה, ב) היא דיש מיתה בלא חטא כו'. וכוונת רש\"י ב\"נתלכלכתי בחטא\" היא (לא שלכן יענש להמסר ביד עשו, אלא) שזה יגרום שתתבטל ההבטחה<sup data-n=\"e27\">*</sup>. וכן מוכח מל' אדה\"ז באגה\"ק שם. וראה לקו\"ש ח\"ה ע' 398 הערה 67 (ח\"כ ע' 168 הערה 19)."],["e27","*","ועפ\"ז יומתק ל' רש\"י \"ויגרום לי להמסר ביד עשו\"."]]],[1301430200,"ע\"י כ\"ק מו\"ח אדמו\"ר בקשר לגאולתו ממאסרו, אשר הסיבה הטבעית למאסרו (\"דבר הסכנה\") היתה \"העבודה הגדולה\" אשר עבד \"בהרבצת תורה וחיזוק ה­דת\"<sup data-n=\"1154\">28</sup>, שעבד בזה עד כדי מסירת נפש בפועל, שזהו מצב של זכות בתכלית השלימות והעילוי — ואיך יתכן לומר שהוא \"הי' חייב בדבר הסכנה ח\"ו\"?!\nה. ויובן זה ע\"פ המבואר באגרת רבינו הזקן<sup data-n=\"1155\">29</sup> (שכתבה \"אחר ביאתו מ­פטרבורג\"<sup data-n=\"1156\">30</sup>) בפירוש הכתוב<sup data-n=\"1157\">31</sup> \"קטונתי מכל החסדים\", וז\"ל:\nבכל חסד וחסד שהקב\"ה עושה לאדם צריך להיות שפל רוח במאד כי חסד. . היא בחי' קרבת אלקים ממש. . וכל הקרוב אל ה' ביתר שאת. . צריך להיות יותר שפל רוח. . כל שהוא קמי' יותר הוא יותר כלא ואין ואפס. . וזו היא ג\"כ מדתו של יעקב. . היות קטן יעקב במאד מאד בעיניו מחמת ריבוי החסדים. . ואינו ראוי וכדאי כלל להנצל כו' וכמארז\"ל<sup data-n=\"1158\">32</sup> שמא יגרום החטא שנדמה בעיניו שחטא.\nמהמשך הלשון מובן, דגם זה שיעקב \"נדמה בעיניו שחטא\" הוא תוצאה מ\"ריבוי החסדים\". היינו, שה\"קרבת אלקים\" (שע\"י ריבוי החסדים) פעלה אצל יעקב לא רק הרגש של קטנות ו­שפלות (שיהי' קטן במאד מאד בעיניו) אלא שיהי' \"נדמה בעיניו שחטא\".\nויש לומר הסברת הענין:\nזה שחשש יעקב \"שמא יגרום החטא שנדמה בעיניו שחטא\" לא היתה זאת עניוות של שקר ח\"ו<sup data-n=\"1159\">33</sup>, שטעה יעקב ב­עצמו לחשוב שעבר על רצונו ית', אלא שחשש זה נתחדש ע\"י שנעשה \"קרוב אל ה' ביתר שאת\".\nכלומר<sup data-n=\"1160\">34</sup>: לפני שזכה ל\"קרבת אלקים\" זו, היתה עבודתו בתכלית ה­שלימות בלי חסרון כלל; ורק לאחרי ש­נתעלה להיות \"קרוב אל ה' ביתר שאת\" אזי (חשב ש)עבודתו הקודמת כחטא תחשב (אף שלפנ\"ז לא הי' שום חסרון בעבודתו)<sup data-n=\"1161\">35</sup>.",[["1154","28","ל' כ\"ק מו\"ח אדמו\"ר במכתבו לחגיגה ה­ראשונה — י\"ב תמוז תפר\"ח (אגרות קודש שלו ח\"ב ע' פ. וש\"נ)."],["1155","29","תניא שם."],["1156","30","כ\"ה הכותרת בתניא שם. ולהעיר מהכותרת למאמר כ\"ק מו\"ח אדמו\"ר הנ\"ל (שנכתבה על ידו) — \"ש\"פ פנחס, פ\"ז פטרסבורג\" [וכ\"ה ב\"מפתח\" לסה\"מ תרפ\"ז שם — שהוא ג\"כ לשון בעל הגאולה] — אף שבימים ההם שם העיר הי' לענינגראד [וכ\"ה הלשון בהרשימה שנדפסה בראש הקונטרס<sup data-n=\"e28\">*</sup> (שבו נדפס המאמר בפעם הראשונה) — \"ביום החמישי כו' ויבא לביתו ללענינגראד כו' אמר המאמר ברוך הגומל כו'\"]. — וראה סה\"ש תנש\"א ח\"ב ע' 658."],["1157","31","וישלח שם."],["1158","32","ברכות ד, א. רש\"י וישלח שם (בשינוי לשון)."],["1159","33","דנוסף לזה שיעקב מדתו מדת האמת (זח\"א קלט, סע\"א. קסא, א. תניא ספי\"ג. ובכ\"מ) — הרי ידוע שענין הענוה (משא\"כ שפל) אינו שטועה לחשוב שהוא בעל חסרון, אלא שלמרות שיודע מעלותיו ה\"ה קטן בעיני עצמו, בהכירו שכל מעלותיו ניתנו לו מלמעלה (ראה לקו\"ש חי\"ג ע' 33. וש\"נ)."],["1160","34","בהבא לקמן ראה לקו\"ש חכ\"ה ע' 16 ואילך. וראה גם לקו\"ש ח\"ה ע' 396 ואילך (ח\"כ ע' 166 ואילך)."],["1161","35","היינו שאין הכוונה שאזי מכיר החסרון שהי' בו לפנ\"ז — אלא שהחסרון נתחדש עתה — כי ע\"י עלי' זו נדרשה ממנו שלימות בערכו עתה (ולפנ\"ז היתה עבודתו בשלימות) — ראה לקו\"ש חכ\"ה (ע' 15 ואילך). וש\"נ.\nעוד דוגמא: ה\"מפסיק ממשנתו ואומר מה נאה אילן זה כו'\" (אבות פ\"ג מ\"ז) — אף שכשאינו עוסק בתורה, מחוייב לברך כשיוצא בימי ניסן ורואה אילנות שמוציאין פרח (ברכות מג, ב. טושו\"ע או\"ח סרכ\"ו. סדר ברכת הנהנין לאדה\"ז פי\"ג סי\"ד)."],["e28","*","גם רשימה זו נכתבה על ידי בעל הגאולה, אלא שכתבה בסגנון שלישי המדבר (ראה פתיחת הרמב\"ן לתורה)."]]],[1301430201,"דוגמא לדבר — מה שארז\"ל<sup data-n=\"1162\">36</sup> דמאן ד\"מחוו לי' במחוג קמי מלכא\" ה\"ז מרי­דה במלך, כי בעמדו לפני המלך צ\"ל בביטול גמור, מבלי כל זיז ותנועה כל שהיא<sup data-n=\"1163\">37</sup>; שזהו רק כשעומד לפני המלך, משא\"כ שלא במעמד המלך, הרי לא זו בלבד שמספיק כשמדת ביטולו אל ה­מלך תהי' בדרגא פחותה יותר (שמקבל ע\"ע לקיים חוקי המלך וכו'), אלא עוד זאת, שזהו רצון המלך, שהאדם לא יהי' בביטול גמור כזה, שהרי במצב ביטול כזה לא יהי' מסוגל למלאות פקודות המלך בישוב המדינה כו'.\nונמצא, שבהיותו לפני המלך — הרי עבודתו הרגילה בעת עסקו בהמדינה בישוב המדינה (גם שהיא בתכלית ה­שלימות) נחשבת \"כחטא\", כי לפני המלך אין לו אלא ביטולו אל המלך.\n[וכמבואר בספרים<sup data-n=\"1164\">38</sup>, שזוהי גם סיבת ההפרש בין ימי החול שבהם נצטווינו<sup data-n=\"1165\">39</sup> \"ששת ימים תעבוד ועשית כל מלאכתך\" (וארז\"ל<sup data-n=\"1166\">40</sup> \"זו מצות עשה\"), ואילו ביום השבת נאסרה עשיית מלאכה:\nביום השבת מאירה קדושתו ית' בעו­לם באופן גלוי<sup data-n=\"1167\">41</sup>, ע\"ד שעומדים לפני המלך, ולכן אסורים במלאכה<sup data-n=\"1168\">42</sup>; משא\"כ בימי החול, שקדושתו ית' מתעלמת בעו­לם, ה\"ז כמו בני המדינה הנמצאים מחוץ להיכל המלך — שאזי רצונו של המלך הוא שיתעסקו, יעשו מלאכה בישובו של עולם כו'].\nוזהו הפירוש בזה שיעקב \"נדמה בעי­ניו שחטא\", כי \"מחמת ריבוי החסדים\" שהגביהו את יעקב להיות \"קרוב אל ה' ביתר שאת\", הרי דרגתו, קטנותו בעיני עצמו הקודמת בעבודת השם נחשבת כחטא.\nועד\"ז יש לפרש נוסח הברכה \"הגומל לחייבים טובות\" אצל צדיקים גמורים — שעי\"ז גופא שנגמל להם חסד וטוב, ה\"ז גורם שירגישו א\"ע כ\"חייבים\", שלגבי גודל קרבתם אל ה' (ע\"י חסד זה), הרי מצבם הקודם הוא בגדר \"חייבים\" (אף שקודם \"קרבת אלקים\" זאת, היתה עבוד­תם בתכלית השלימות), כנ\"ל.\nו. אמנם עדיין אין הענין מיושב, כי ביאור הנ\"ל מספיק רק להסביר איך אפשר שצדיק גמור יחשיב א\"ע (באמת)",[["1162","36","חגיגה ה, ב."],["1163","37","וכן בשמו\"ע שאז צ\"ל כ\"עומד לפני המלך\" (שו\"ע אדה\"ז או\"ח סק\"ד ס\"ב. וראה ברכות לג, רע\"א. שבת י, א. טושו\"ע ודאדה\"ז או\"ח סו\"ס צה). — וראה לקו\"ש שם (ס\"ע 16 ואילך. וש\"נ) בטעם אמירת סלח לנו בתפלת שמו\"ע."],["1164","38","אוה\"ת לך (כרך ג) תשכ, א­ב (וש\"נ). המשך תרס\"ו ע' כב."],["1165","39","יתרו כ, ט."],["1166","40","מכילתא הובאה בדרשות ר' יהושע אבן שועיב פ' וישב ובס' מנחה בלולה יתרו שם. וראה מכילתא דרשב\"י יתרו שם. וראה לקו\"ש ח\"א ע' 189 הערה 8."],["1167","41","וי\"ל ששני ענינים בזה: מצד המטה (הרגש האדם) — דמכיון שבשבת מרגישים יותר \"קרבת אלקים\" ה\"ז פועל הרגש הביטול; וכן מצד למעלה (דרגת האור) — שבשבת מאיר אור עליון נעלה יותר, שמצד אור זה אין מקום למציאות יש."],["1168","42","ובזה גופא כמה דרגות — יו\"ט<sup data-n=\"e29\">*</sup> שמותר במלאכת אוכל נפש; שבת שאסורה בכל מלאכה, אבל מותר באכו\"ש (עניני הגוף); יום הכפורים שאין בו אכו\"ש כו'."],["e29","*","ולפני זה חוה\"מ דמותר במלאכת דבר האבד."]]],[1301430202,"כ\"חייב\", אבל בהמאמר מפרש (כנ\"ל) \"חייבים\" — ש\"מודה שהי' חייב בדבר הסכנה ח\"ו\", והתמי' במקומה עומדת: הן אמת שלגבי מצבו בהווה עבודתו ה­קודמת אינה בשלימות, אבל איך אפ\"ל \"שהי' חייב (קודם לזה) בדבר הסכנה ח\"ו\"?\n[ודוחק גדול לומר שפירוש זה ב­\"הגומל לחייבים\" הוא רק לשאינם צדי­קים, ששייך לומר שהם אשמים \"בדבר הסכנה\"].\nויש לומר הביאור בזה:\nזה שהקב\"ה מעמיד את הצדיק במצב של סכנה כו', ה\"ז רק כדי להעלות אותו למדריגה עליונה יותר. כי דוקא על ידי העבודה במצב של \"מיצר\", מגיעים ל­\"מרחב\" האמיתי (מן המיצר גו' ענני ב­מרחב).\n[וע\"ד המבואר בהמאמר בענין ירידת הנשמה למטה (שההודאה דברכת הגומל בעבודת האדם היא על היציאה מהסכנה הרוחנית שבירידה זו) — שהכוונה ב­ירידה זו היא לצורך עלי', שע\"י עבודת הנשמה בבירור וזיכוך הגוף הגשמי (ו­המשכת קדושה בדברים גשמיים) מתע­לית הנשמה למדריגה עליונה וביותר מכמו שהיתה קודם ירידתה בגוף.\nוענין זה הוא גם אצל צדיקים גמו­רים, שהענין שעובד ה' בעוה\"ז ה\"ז ירידה, כי \"גם. . צדיק גמור עובד ה' ביראה ואהבה רבה בתענוגים לא יגיע למעלות דביקותו בה'. . בטרם ירידתו לעוה\"ז החומרי לא מינה ולא מקצתה ואין ערך ודמיון ביניהם כלל\"<sup data-n=\"1169\">43</sup> — אלא שירידה זו צורך עלי', שע\"י עבודתם ב­היותם נשמות בגופים דוקא, מתעלים בעילוי אחר עילוי כו'].\nולכן גם צדיק גמור מברך \"הגומל לחייבים טובות\" — אף שלא שייך לומר שהוא \"אשם\" \"בדבר הסכנה ח\"ו\" — כי מצבו הקודם, שהוא בגדר \"חייבים\"<sup data-n=\"1170\">44</sup> לגבי \"קרבת אלקים\" שזכה לה על ידי גמילת הטוב, הוא הוא שגרם שיועמד ב­מיצר זה, כדי שיגיע לעלי' הזאת (הבאה ע\"י מיצר זה<sup data-n=\"1171\">45</sup>).\nוככל הדברים האלה נראה במוחש ב­גאולת כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1172\">46</sup> — שדוקא לאחרי שעבר את יסורי המאסר ר\"ל, הותחלה תקופה חדשה בעבודתו בהר­בצת התורה וחיזוק הדת בכלל, שעבו­דתו זו נתרחבה — יצאה למרחב — ועד להפצה בכל קצוי תבל.\nונתגלה לעין כל, שהכוונה של ה­מאסר היתה בשביל עלי' זו, ליתן ה­אפשריות להרחבת העבודה, להפיץ תורה ויהדות — כולל הפצת המעיינות של פנימיות התורה — בכל מרחבי (שבכל קצוי) תבל.\n<span data-k=\"q\">(משיחות י\"ב תמוז תשכ\"א, ש\"פ בלק תשל\"ז)</span>",[["1169","43","תניא פל\"ז (מח, סע\"א)."],["1170","44","גם י\"ל שעצם הירידה למצב של מיצר ו­סכנה הו\"ע של \"חייב\" — ע\"ד הידוע דהגם שה­צמצום הוא בשביל הגילוי, מ\"מ \"גוף ועצם הצמצום הוא היפך הרצון\" (סה\"מ קונטרסים ח\"א קצב, א ואילך). ואכ\"מ."],["1171","45","ועפ\"ז יש לפרש נוסח הברכה \"הגומל ל­חייבים\" — שע\"י הרגש המיצר מזה שנמצאים במצב ד\"חייבים\", זוכים ל\"הגומל. . טובות\" — דמן המיצר אל המרחב, כנ\"ל. וראה לקו\"ש שצויין בהערה 26."],["1172","46","להעיר, שאדה\"ז אמר לאחרי גאולתו [י\"ט כסלו תק\"ס — שנה לאחרי גאולתו, אבל בא בהמשך לד\"ה בכ\"ה בכסלו שאמר אדה\"ז בחנוכה תקנ\"ט בוויטעבסק בנסיעתו חזרה ממאסרו בפעטערבורג] דרוש \"ברוך שעשה נסים לאבותינו\" (לקו\"ד ח\"א כא, א. וראה שם מה שאמר \"בתחילת אמירתו\"), וכ\"ק מו\"ח אדמו\"ר אמר מאמר \"ברוך הגומל כו'\". ואכ\"מ."]]],[1301430203,"<h3>שיחה ב</h3>\nא. אודות יום י\"ב תמוז — היום שבו נגאל כ\"ק מו\"ח אדמו\"ר ממאסרו<sup data-n=\"1173\">1</sup> אשר נאסר בגלל \"העבודה הגדולה\" אשר עבד \"בהרבצת תורה וחיזוק הדת\"<sup data-n=\"1174\">2</sup> — כתב כ\"ק מו\"ח אדמו\"ר, במכתבו לחגיגת י\"ב תמוז הראשונה (בשנת תרפ\"ח)<sup data-n=\"1175\">3</sup>, וז\"ל \"ראוי הוא לקובעו ליום התועדות ו­התעוררות לחיזוק התורה והיהדות בכל אתר ואתר לפי ענינו\".\nנתבאר כמה פעמים, אשר כל דברי רבותינו נשיאינו מדוייקים המה, אפילו בנוגע ל\"שיחות\" ואפילו בנוגע לשיחות חולין שלהן — שהן צריכין לימוד<sup data-n=\"1176\">4</sup>, ו­כ\"ש וק\"ו שכן הוא בדברי תורתם, וביתר שאת כולל — הוראותיהם (תורה מלשון הוראה).\nובעניננו — יש לדייק בלשון כ\"ק מו\"ח אדמו\"ר הנ\"ל \"חיזוק התורה וה­יהדות\". דלכאורה, \"יהדות\" ה\"ה שם כללי, הכולל כל השייך לדת ישראל — הן לימוד התורה והן שמירת וקיום ה­מצוות (דאורייתא, דרבנן, עד למנהגי ישראל כו'), וא\"כ הי' מספיק לומר \"חיזוק היהדות\" — ומאי קמ\"ל ב\"(חיזוק) התורה\"?\nבפשטות הכוונה בזה להדגיש הענין והפעולות ד\"חיזוק התורה\", כמו שכותב כמה פעמים במכתבו הנ\"ל ע\"ד עבודתו ב\"הרבצת תורה\" (והכוונה כפשוטה — יסוד חדרים, ישיבות ושיעורי תורה ב­רבים (עבור בעלי עסק) וכו') — אבל הו\"ל (לכאורה) להקדים את הכל והכלל, \"יהדות\", ואח\"כ להוסיף ההדגשה על הפרט, \"תורה\".\nגם יש לדייק ולבאר לשונו \"חיזוק התורה\", ולא כלשונו כמה פעמים ב­מכתבו שם \"הרבצת תורה\".\nונראה לומר, שאחת הכוונות דכ\"ק מו\"ח אדמו\"ר כאן היא — לא לעורר על שני ענינים שונים — התחזקות בעבודת הרבצת התורה והתחזקות בעבודת החזקת היהדות (שמירת וקיום המצוות וכו') — אלא הכוונה לענין אחד — \"חיזוק היהדות\"; אלא שאא\"פ לחזק את היהדות באופן הנרצה כ\"א ע\"י הקדמת והתחלת חיזוק התורה.\nב. ביאור הדבר:\nהמושג \"יהדות\" במובנו הפשוט פירו­שו כללות הנהגות יהודים בתור יהודים. ולכן יש צורך להדגיש ולקבוע, ש­\"יהדות\" אינה רק הנהגת בני אדם, הדרך שנהגו בו בני ישראל במשך הדורות, מעשה ידי אדם ח\"ו — אלא כל כולה ומ­הותה הוא קיום הוראות התורה שניתנה בסיני מפי הגבורה.\nוזהו תוכן ההדגשה \"חיזוק התורה וה­יהדות\", שלפני חיזוק היהדות יש צורך לחזק את האמונה וההכרה שרק התורה היא הקובעת מהי \"יהדות\"<sup data-n=\"1177\">5</sup>, ואין הדבר",[["1173","1","ביום י\"ב תמוז נתבשר כ\"ק מו\"ח אדמו\"ר שחופשה ניתנה לו, וניתנה לו תעודת השחרור למחרתו — יום י\"ג תמוז."],["1174","2","לשון כ\"ק מו\"ח אדמו\"ר במכתבו שמובא בפנים."],["1175","3","נדפס בסה\"מ תרפ\"ח ע' קמו. תש\"ח ע' 263. אגרות קודש אדמו\"ר מהוריי\"צ (ח\"ב ע' פ)."],["1176","4","סוכה כא, ב. ע\"ז יט, ב."],["1177","5","להעיר ממאמר הרס\"ג (האמונות והדעות מ\"ג פ\"ז) \"אומתנו איננה אומה כי אם בתורותי'\"."]]],[1301430204,"מסור לבני אדם, שבשכלם יכריעו שעני­נים מסוימים אלה ביהדות הם חובה, משא\"כ ענינים אחרים — אלא כל פרט ופרט שבתורה, עד לחידוש של תלמיד ותיק, ואפילו מנהגי ישראל שנתחדשו בדורות האחרונים (ונתקבלו ברוב תפו­צות ישראל<sup data-n=\"1178\">6</sup>) — ה\"ה חלק מתורתנו ה­קדושה, שהיא תורת ה', תורה מן השמים, שניתנה למשה מסיני<sup data-n=\"1179\">7</sup> (כי אפילו מנהג ישראל — תורה הוא<sup data-n=\"1180\">8</sup>).\nומזה מובן, שמי שמקיל בחומרות ו­מנהגי ישראל שנתתקנו והונהגו בדורות האחרונים, בחשבו שהם \"מעשה בני אדם\", ואשר ע\"כ אין הוא מחויב לקבלם על עצמו — הרי אין התנגדותו בנוגע לאיזה ענינים פרטים של \"יהדות\" וחסר הוא מעשים אחדים, אלא שזהו בניגוד ממש לעיקרי היהדות, שכולה אינה מעשה בני אדם, אלא כל פרט ופרט שבה הוא דת שגילה השם על ידי עבדיו — חכמי ישראל שבכל דור ודור<sup data-n=\"1181\">9</sup>.\n[ולא עוד, אלא ש\"שיטה\" זו — לחלק בין עניני תורה שבע\"פ המיוסדים על תורה שבכתב (היינו, הענינים שלמדו חכמים ע\"פ י\"ג מדות שהתורה נדרשת בהן) או שהם הלכה למשה מסיני, ל­\"הגזירות והתקנות והמנהגות\"<sup data-n=\"1182\">10</sup> שנת­חדשו ע\"י חכמי ישראל<sup data-n=\"1183\">11</sup> שבכל דור ו­דור — ה\"ה פתח<sup data-n=\"1184\">12</sup> לכפירה ר\"ל בהעיקר שהתורה שבעל פה היא כולה מן ה­שמים<sup data-n=\"1185\">13</sup>].\nג. ויש לומר, שהצורך בהדגשה זו, \"חיזוק התורה\" לפני חיזוק היהדות, הוא בגלל המשך הענין בהוראה זו — \"(חיזוק התורה והיהדות) בכל אתר ואתר לפי ענינו\":\nאילו הי' חיזוק התורה והיהדות רק ב\"עיר מלאה חכמים\" וכיו\"ב — אין צורך בהדגשה הנ\"ל, דפשיטא אצל כאו\"א שכל מהות היהדות היא היותה תורת השם; אבל כיון שהמדובר הוא בחיזוק היהדות \"בכל אתר ואתר לפי ענינו\", יש צורך לשלול טעות, שהיהדות ניתנה ל­השתנות ח\"ו וח\"ו לפי תנאי הזמן וה­מקום. ועוד זאת, הרי יש \"אתר\" שאנשיו רחוקים מאד מיהדות ואא\"פ להשפיע עליהם שיקבלו על עצמם עול שמירת כל התורה כולה לכל פרטי', באופן ש\"ענינו\" של \"אתר\" זה דורש להסתפק (לפי שעה) בהשתדלות על מנת שיקיימו (רק) מצוות אחדות (וכיו\"ב).\nולכן, כאשר עוסקים בחיזוק היהדות \"בכל אתר ואתר לפי ענינו\", צריכים לזכור תמיד (ההקדמה) שקודם חיזוק היהדות בא \"חיזוק התורה\", שה\"יהדות\"",[["1178","6","ראה בפרטיות הל' ממרים פ\"ב. ע\"ש. — וראה הערה 9."],["1179","7","ראה מגילה יט, ב. ירושלמי שם פ\"ד ה\"א. ירושלמי פאה פ\"ב ה\"ד. שמו\"ר ספכ\"ח. שם רפמ\"ז. ויק\"ר רפכ\"ב. ועוד. וראה לקו\"ש חי\"ט ע' 252 הערה 21."],["1180","8","ראה תוד\"ה נפסל (מנחות כ, ב). רמ\"א יו\"ד סשע\"ו ס\"ד. וראה ירושלמי פסחים פ\"ד ה\"א. ועוד."],["1181","9","אלא שבזה גופא מחלקת התורה כמבואר ע\"פ חכמי התורה: הלכה חומרא מנהג שנתקבל במקום אחד ובמקום שני נתקבל ע\"פ כללי התורה מנהגי' (ראה הקדמת הרמב\"ם לספר היד). ועוד."],["1182","10","ל' הרמב\"ם הל' ממרים פ\"א ה\"ב וג'. וראה גם הקדמת הרמב\"ם שם. ועוד."],["1183","11","ראה רמב\"ם הל' ממרים שם. ובארוכה — בהקדמתו לפירוש המשניות."],["1184","12","אף שחלוקים המה (דאורייתא, ד\"ס וכו') כנ\"ל — הרי זה הוא רק מפני שכן רצה הקב\"ה וגילה בתורתו תורה אור חילוקים אלה."],["1185","13","הל' תשובה פ\"ג ה\"ח ובכס\"מ שם. וראה פיה\"מ פ' חלק היסוד הט'."]]],[1301430205,"נקבעת ונבנית אך ורק על חיזוק יסוד ה­תורה, שלא ניתנה להשתנות מצד שינויי הזמן והמקום.\nוכמשנ\"ת כמה פעמים בפירוש דיוק לשון המשנה<sup data-n=\"1186\">14</sup> \"הוי מתלמידיו של אהרן כו' אוהב את הבריות ומקרבן לתורה\" — שצריכים לקרב את הבריות לתורה, ולא להיפך, \"לקרב\" ולהוריד את התורה ח\"ו אל הבריות, על ידי וויתורים ח\"ו ו­פשרות וגרעונות בהלכות התורה — גם אפילו באם נדמה שיתכן ופשרה זו דוקא תועיל (לפי דעתו) לקרב את הזולת ל­תורה ומצוותי', עכ\"פ לקיום מצוות אחדות; כי, כנ\"ל, תורתנו הקדושה היא תורת אמת, ולא ניתנה לפשרות, וכאו\"א מישראל, מבלי הבט על מצבו ומקומו, חובתו לקבל את כל התורה כולה לשמור ולקיים כולה.\nואין זה סותר לכך שההשתדלות ב­חיזוק היהדות היא, כפי שמפורש, \"בכל אתר ואתר לפי ענינו\", ועד שלפעמים צ\"ל ההשתדלות באופן דלאט­לאט — ועד שמי שהוא בגדר תינוק שנשבה ל­בין העכו\"ם, יתחיל בקיום מצוה אחת וכיו\"ב (כנ\"ל) — כי אין פירוש הדברים שעושים פשרות בתורה ויהדות, אלא ע\"ד שמצינו בנוגע ללימוד התורה, שעם תינוק מתחילים בלימוד הא\"ב, ואח\"כ הולך מחיל אל חיל: לימוד צירוף כמה אותיות, כמה תיבות ועד שזוכה ללמוד את כל התורה כולה; ופשוט, שלימוד הא\"ב עם תינוק אינו \"פשרה\" כלל, ואין בזה כל וויתור או גרעון כלל וכלל, אלא זהו סדר הלימוד, מן ההתחלה אל ההמשך וכו' דייקא;\nוכן הוא בנוגע לקיום המצוות, \"חיזוק היהדות\" — דכאשר מתעסקים עם \"תינוק\" (ברוחניות), שאין לו שום ידיעה בעניני יהדות, צריכים לכל­לראש ל­למדו את הא\"ב של \"יהדות\"; אבל תיכף בהתחלה זו יודע \"התינוק\" שאין הא\"ב (שבזה התחיל) כל התורה כולה, אלא שבמצבו עתה (שהוא \"תינוק\" כו') הרי מתחילים בקיום מצוה אחת, ובמשך הזמן ילך מחיל אל חיל, ו\"מצוה גוררת מצוה\"<sup data-n=\"1187\">15</sup>.\nד. וזוהי ההוראה בפועל, שצריכה לשמש כיסוד לההתועדויות דחגיגת חג הגאולה די\"ב תמוז — שהעסק בחיזוק היהדות צ\"ל מיוסד על שני עיקרים אלה, ובשני הקצוות:\nהעיקר הא' הוא — \"חיזוק התורה וה­יהדות\", והיינו האמונה הטהורה שכל ענין של יהדות נקבע אך ורק על ידי התורה שהיא מן השמים (ואינו מעשה בני אדם כלל וכלל ח\"ו ור\"ל), ובמילא לא שייך שיהי' בזה פשרה, וויתור או גרעון בתורה ומצוותי', כי כשם ש\"אני ה' לא שניתי\"<sup data-n=\"1188\">16</sup>, כך אין שייך שינוי ב­\"יהדות\" שהיא דבר השם.\nוביחד עם זה חייבים להשתדל בחי­זוק היהדות \"בכל אתר ואתר לפי ענינו\", דאע\"פ שהמדובר ב\"אתר\" שהוא רחוק לעת עתה מיהדות ומה גם מקיום כל התורה כולה, וההשתדלות שם היא \"לפי ענינו\" (כנ\"ל באורך)\n— אבל ביחד עם זה באמת, ודוקא מתוך אמת לוקחים וכובשים (נעמט מען אן) את האדם —\nאסור לו לאדם לעמוד מרחוק [כאו­תם האומרים, שרק עם יהודים יראים ושלמים יש להתעסק כדי לחזק ידיהם",[["1186","14","אבות פ\"א מי\"ב."],["1187","15","אבות פ\"ד מ\"ב."],["1188","16","מלאכי ג, ו."]]],[1301430206,"בשמירת התורה ומצוותי', אבל לא עם אלה החסרים בזה ועאכו\"כ — אלה ה­רחוקים מתורת ה' ועבודתו],\nאלא חייב להשתדל בכל כחו לקרבם לתורה ומצוותי', כהוראת הבעש\"ט<sup data-n=\"1189\">17</sup> ע\"ד גודל הענין של מצות אהבת ישראל לכאו\"א מישראל, גם למי \"שלא ראה אותו מעולם\", וכמשנ\"ת במק\"א<sup data-n=\"1190\">18</sup> שה­כוונה בזה היא גם ברוחניות הענינים, ש­גם יהודי שרחוק מיהדות עד שלכאורה אין לו שום שייכות עמו ביהדות, הנה גם אותו צריך לאהוב עד כדי להשתדל לקרבו לתורה וליהדות — דברים הכי יקרים בכל העולם כולו;\nוכמבואר בספר התניא<sup data-n=\"1191\">19</sup>, ד\"מי שאינו חבירו (בתורה ומצות) ואינו מקורב אצלו\", אסור לשנאותו ח\"ו (גם אם ראה שחטא), אלא \"ע\"ז אמר הלל הזקן<sup data-n=\"1186\">14</sup> הוי מתלמידיו של אהרן אוהב שלום וכו' אוהב את הבריות ומקרבן לתורה, לומר. . צריך למשכן בחבלי עבותות אהבה וכולי האי ואולי יוכל לקרבן לתורה ועבודת ה'\".\nועל ידי ההשתדלות באהבת ישראל, לכאו\"א מישראל ממש, זוכים לברכת ה', ד\"ברכנו אבינו (כאשר) כולנו כאחד\"<sup data-n=\"1193\">20</sup> דוקא,\nעד לברכה העיקרית והפנימית — גאולה האמיתית והשלימה על ידי משיח צדקנו, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחת י\"ג תמוז תשכ\"ט) </span>",[["1189","17","\"היום יום\" טו כסלו (וראה שם ג' אדר א' בשם אדה\"ז. ועוד)."],["1190","18","לקו\"ש ח\"א ע' 201."],["1191","19","פרק לב."],["1186","14","אבות פ\"א מי\"ב."],["1193","20","ברכת שים שלום בתפלת העמידה (הובא בתניא שם לפנ\"ז)."]]],[1301430207,"<h3>בלק</h3>\nא. אודות דרכו של רש\"י בפירוש נבואות בלעם (שבפרשתנו), נתבאר ב­מ\"א<sup data-n=\"1194\">1</sup>, שאף שקבע רש\"י שלא בא בפירו­שו אלא לפרש פשוטו של מקרא ומביא רק אגדות המיישבות את המקראות<sup data-n=\"1195\">2</sup>, מ\"מ שונה בזה פירושו בנבואת בלעם, שמביא ריבוי דרשות רז\"ל — והטעם כי בכתוב כפשוטו מפורש \"וישא משלו\"<sup data-n=\"1196\">3</sup>, היינו שע\"פ דרך הפשט, אין פירוש כתו­בים אלה לפי \"פשוטם\" ממש כשאר ה­כתובים, אלא הם \"משלים\", ומשל הרי פשטות ענינו (גם) רמזים ודרשות [ועד\"ז בפירושו לשירת הים, שירת האזינו ועוד — להיותן \"שירות\" מביא שם רש\"י כמה דרשות].\nעוד מצינו, שבנבואת בלעם הרבה רש\"י להביא פירושי \"תרגומו\" שלא ע\"ד הרגיל בפירושו עה\"ת. וע\"פ הנ\"ל מובן — שבהבאת דברי התרגום, כוונתו בעי­קר (אינה לתרגום לשונות הכתובים, אלא) לפירוש הנמשל של ה\"משל\" לפי תרגומו.\nאמנם בזה גופא מצינו כמה אופנים: לפעמים מתחיל רש\"י פירושו \"כתרגומו\" ואח\"כ מביא עוד פי' מדרשת חז\"ל, ו­לפעמים להיפך. וע\"פ הנ\"ל מובן, דתלוי מה קרוב יותר לפשש\"מ בתוכן דברי ה\"משל\".\nעפכ\"ז יש לעיין בפרש\"י עה\"פ<sup data-n=\"1197\">4</sup> \"הן עם כלביא יקום גו'\", שמפרש: \"כשהן עומדין משינתם שחרית הן מתגברים כלביא וכארי לחטוף את המצות ללבוש ציצית לקרוא את שמע ולהניח תפלין. לא ישכב — בלילה על מטתו עד שהוא אוכל ומחבל כל מזיק הבא לטרפו כיצד קורא את שמע על מטתו כו'\", ולאחרי אריכות פירושו (שמקורו בדברי המד­רש<sup data-n=\"1198\">5</sup>) כתב \"ד\"א הן עם כלביא יקום וגו' — כתרגומו\".\nויש להבין: למה מקדים להביא דברי המדרש שהם רמז רחוק, לכאורה, בפי' התיבות, ולא הביא בתחלה פי' התרגום, שלפי פירושו (\"הא עמא. . לא ישרי ב­ארעה עד דיקטול קטול ונכסי עממיא יירת\") מדבר הכתוב בכניסת בני ישראל לארץ ישראל וכיבוש הארץ (וכמו ש­הביא הרמב\"ן<sup data-n=\"1199\">6</sup> מהתרגום)?\nויתירה מזו: בנבואת בלעם שלאח\"ז, ששם נאמר<sup data-n=\"1200\">7</sup> ע\"ד הלשון שבפסוק זה — \"כרע שכב כארי וכלביא מי יקימנו\", פרש\"י \"כתרגומו, יתיישבו בארצם בכח ובגבורה\" ותו לא, ומאי טעמא לא הביא כאן מתחלה פי' התרגום הקרוב יותר לפשש\"מ (גם) כאן?\nוביותר יוקשה, דבתחלת נבואה זו של בלעם \"לא איש א­ל וגו'\"<sup data-n=\"1201\">8</sup> פרש\"י \"כבר נשבע להם להביאם ולהורישם ארץ",[["1194","1","ראה לקו\"ש חי\"ח ע' 262 ובהערה 3 שם. חכ\"ח ע' 167 ואילך."],["1195","2","ראה פירושו בפ' בראשית ג, ח. שם, כד. ועוד."],["1196","3","פרשתנו כג (ז. יח). כד (ג. טו. כ. כא. כג). וראה פרש\"י חקת כא, כז."],["1197","4","כג, כד."],["1198","5","תנחומא פרשתנו יד. במדב\"ר פ\"כ, כ."],["1199","6","פרשתנו כג, כג. וראה גם ראב\"ע כאן פסוק כד."],["1200","7","כד, ט."],["1201","8","כג, יט."]]],[1301430208,"שבעה אומות ואתה סבור להמיתם ב­מדבר\", הרי שעיקר דברי בלעם (ובפרט בנבואה זו) מיוסדים על זה, לשלול הסברה \"להמיתם במדבר\" — כי ברור לו (לבלעם) שבנ\"י ימשיכו ללכת בכח ו­גבורה לכבוש ארץ שבעה עממין<sup data-n=\"1202\">9</sup>, ו­ינצחו את האומות, ובהמשך לזה מתאים יותר לכאורה פירוש התרגום הנ\"ל.\nב. וי\"ל הביאור בזה — בפשטות:\nבתוכן נבואות בלעם, שענה<sup data-n=\"1203\">10</sup> לבלק (ע\"ז שביקש ממנו \"לכה נא ארה לי את העם הזה\"<sup data-n=\"1204\">11</sup>) שאינו יכול לקלל את ישראל — יש ב' אופנים: א) שאינו יכול לקללם ולהרע להם ע\"י דבורו, כי הם חביבים בעיני הקב\"ה והוא משגיח עלי­הם ושומרם כו'. ב) יש להם מעלות ו­זכויות רבות שאינם בשאר האומות, ו­לכן (לא רק שא\"א לו להרע להם ע\"י דבורו, אלא יתירה מזו —) \"ראויים הם לברכה\"<sup data-n=\"1205\">12</sup>.\nוי\"ל, שבכללות זהו החילוק בין נבואתו הראשונה ונבואתו השני': בהק­דמה לנבואה הא' אמר<sup data-n=\"1206\">13</sup> \"מה אקב לא קבה א­ל ומה אזעם לא זעם ה'\", ואילו ההקדמה לנבואה הב'<sup data-n=\"1207\">14</sup> היא \"הנה ברך לקחתי וברך ולא אשיבנה\".\n[ואף שבב' הנבואות (וכן בנבואה הג' והד') יש מב' הענינים (אופנים) הנ\"ל, למה אינו יכול לקללם (ויתירה מזו, דר­כו של רש\"י בפי' כתובים אלה שהרבה להביא יותר מפירוש אחד, לפי שמסתבר שיש להוסיף בפירוש דברי בלעם בזכות ומעלת ישראל), מ\"מ תלוי מהו העיקר].\nובזה מבואר החילוק הכללי בין פי­רושי רש\"י בשתי נבואות אלו:\nבנבואה הא' שמתחילה<sup data-n=\"1208\">15</sup> \"כי מראש צורים אראנו\", פירש\"י \"אני מסתכל בראשיתם ובתחלת שרשיהם ואני רואה אותם מיוסדים וחזקים כצורים וגבעות הללו ע\"י אבות ואמהות. . זכו לו אבותיו כו'\", להדגיש שאינו יכול להרע להם בדבורו מצד חביבותם לפני הקב\"ה;\nובנבואה הב' שמתחילה<sup data-n=\"1209\">16</sup> \"לא הביט און ביעקב גו'\" כתב רש\"י תחלה \"כתר­גומו\", ואח\"כ מביא פי' המדרש — כי דוקא לפי התרגום (\"לית פלחי גלולין בדבית יעקב ואף לא עבדי לאות שקר בישראל\"), מדבר במעלת ישראל עצמם, משא\"כ לפי המדרש אינו מדבר במעלת ישראל עצמם (מצד מעשיהם), אלא חבי­בותם כו' לפני הקב\"ה (דגם<sup data-n=\"1210\">17</sup> \"כשהן עוברין על דבריו אינו מדקדק אחריהן",[["1202","9","ומטעם זה דוחק לפרש שזה שלא הביא רש\"י פי' התרגום כפי' הראשון הוא משום שכיבוש ארץ ז' עממין אינו נוגע לבלק — שהרי זה מורה ומדגיש כחם וגבורתם שלא יוכל בלק לנגוע בהם וכ\"ש להכותם כו', ובמילא אם ילכו דרך ארצו כו' (ראה רש\"י פרשתנו כב, ה ד\"ה עם יצא ממצרים. שם, יא ד\"ה וגרשתיו) לא יוכל למונעם. וראה מלבי\"ם כאן."],["1203","10","מיכה ו, ה (הפטרת פרשתנו)."],["1204","11","כב, וא\"ו. וראה גם שם, יז. כג, יא. יג. ועוד."],["1205","12","לשון רש\"י עה\"פ (כג, כג) כי לא נחש ביעקב."],["1206","13","כג, ח."],["1207","14","כג, כ."],["1208","15","כג, ט."],["1209","16","כג, כא. משא\"כ ג' הפסוקים שלפנ\"ז הם הקדמה לנבואתו."],["1210","17","ומ\"מ מביא רש\"י גם פירוש זה, כי נוסף על הנ\"ל בפנים, שכל מה שאפשר להוסיף בפי' הכתובים במעלת ישראל מוסיפים, ובזה מודגש גודל מעלת וחביבות ישראל לפני הקב\"ה (שאינו בפי' הא' \"כתרגומו\"), שאינו מדקדק אחריהן כו', הרי ענין ש\"לא הביט\" משמעו שישנו \"און\" אלא ש\"לא הביט\" — אינו מתיישב כ\"כ לפי' הא' (ראה משכיל לדוד כאן. אבל ראה מה שהעיר עליו בבאר בשדה)."]]],[1301430209,"להתבונן באוניות שלהם ובעמלן שהם עוברים על דתו\")<sup data-n=\"1211\">18</sup>.\nועד\"ז הוא בכתוב דידן \"הן עם כלביא יקום וגו'\": לפי \"תרגומו\" שמדבר ע\"ד כיבוש הארץ \"לא ישרי בארעה עד דיקטול קטול ונכסי עממיא יירת\", הרי מדבר בעיקר עד\"ז שהקב\"ה יעשה עמ­הם. ולכן מקדים רש\"י פי' המדרש \"כש­הן עומדין משינתם שחרית הן מתגברים כלביא וכארי לחטוף את המצות כו'\", היינו שמדבר ע\"ד גודל המעלה במעשי­הם של ישראל<sup data-n=\"1212\">19</sup>, ואשר זהו סדר תמידי אצלם<sup data-n=\"1213\">20</sup>, בכל יום. ומזה מובן, שנוסף שאין שייך שבלעם יקללם ח\"ו, הרי יתי­רה מזו \"ראויים הם לברכה\"<sup data-n=\"1205\">12</sup>.\nג. ועפ\"ז יש לבאר גם הטעם שבפי' הא' משנה רש\"י מלשון המדרש:\nבמדרש אי'<sup data-n=\"1215\">21</sup> \"לא ישכב עד יאכל טרף כשהוא אומר ה' אחד נאכלין ה­מחבלין מפניו מלחשין אחריו ברוך שם כבוד מלכותו לעולם ועד ובורחין, והוא נסמך בזכות קריאת שמע משומרי היום לשומרי הלילה, וכשבא לישן מפקיד רוחו ביד הקב\"ה ואומר בידך אפקיד רוחי, וכשננער ממליך להקב\"ה, השומ­רין בלילה מוסרים אותו לשומרי היום שנאמר כו'\";\nואילו רש\"י כותב \"לא ישכב בלילה על מטתו עד שהוא אוכל ומחבל כל מזיק הבא לטרפו כיצד קורא את שמע על מטתו<sup data-n=\"1216\">22</sup> ומפקיד רוחו ביד המקום בא מחנה וגייס להזיקם הקב\"ה שומרם ו­נלחם מלחמותם ומפילם חללים\".\nהיינו, שרש\"י מוסיף ומדגיש בהתחלת הפירוש \"עד שהוא אוכל ומחבל כל מזיק כו'\", שנוסף על שמעשה הקב\"ה הוא בזכות פעולת האדם, הוא גם באופן שפעולת הקב\"ה עצמה מתייחסת למעשה האדם.\nד. אמנם יל\"ע בשינוי עיקרי ששינה רש\"י מהמדרש בתחלת פירושו — דב­מדרש אי' \"עמדו משנתן עומדים כאריות חוטפים קריאת שמע\", ורש\"י כותב \"לחטוף את המצות ללבוש ציצית לקרוא את שמע ולהניח תפילין\". ולפי פשוטו הביא רש\"י כל המצות שעושה אדם ב­שחרית תיכף כשקם משנתו, ולא רק ק\"ש. אבל יש להבין זה גופא, למה הוזקק רש\"י להוסיף על דברי המדרש ולהביא גם \"ללבוש ציצית\" ו\"להניח תפלין\".\nגם צריך להבין הסדר שבו מנה רש\"י ג' מצות אלה — ציצית, ק\"ש ותפילין<sup data-n=\"1217\">23</sup> —",[["1211","18","ולכן כ' בפסוק כי לא נחש ביעקב (כג, כג (בסופו)) \"ואונקלוס לא תרגם כן\", שכוונתו לשלול כאן פי' אונקלוס, כי לפי תרגומו אין הכתוב מדבר במעלת ישראל — כמבואר בלקו\"ש חי\"ח שם ע' 268 ואילך."],["1212","19","ועוד י\"ל בזה, שלפני נבואה זו (הב') אמר בלק לבלעם (כג, יג) \"אפס קצהו תראה וכולו לא תראה\", שכוונתו, שאף שלא יכול להרע הכלל, \"כי מראש צורים אראנו גו'\", מ\"מ יכול להרע מקצתם כו' (ראה ספורנו שם), ולכן מסתבר שגם בלעם בנבואתו אמר דבר השייך (לא רק לעם ישראל כצבור, אלא גם) ליחידים."],["1213","20","כמו בהמשל, ש\"כלביא יקום וכארי יתנשא לא ישכב עד יאכל טרף גו'\" ה\"ז סדר הנהגה יום יומית של לביא וארי (משא\"כ להתרגום דקאי ב­כיבוש ז' עממין)."],["1205","12","לשון רש\"י עה\"פ (כג, כג) כי לא נחש ביעקב."],["1215","21","תנחומא, ועד\"ז בבמדב\"ר ויל\"ש עה\"פ (רמז תשסט)."],["1216","22","תיבות אלו \"שהוא אוכל. . מטתו\" ליתא בדפוס ראשון."],["1217","23","כ\"ה בדפוס ראשון, דפוס שני ורוב כת\"י רש\"י (שתח\"י). אבל בכמה כת\"י רש\"י (שתח\"י) ה­סדר: ציצית, תפילין וקריאת שמע. וכן הובא בבחיי כאן."]]],[1301430210,"שאינו לפי סדרן בפרשיות התורה (ש­תחלה נאמר פ' תפלין (בפ' בא), אח\"כ פ' ציצית (בפ' שלח) ולבסוף (ולאחרי פרשתנו) פ' ק\"ש (בפ' ואתחנן))<sup data-n=\"1218\">24</sup>; וכן<sup data-n=\"1219\">25</sup> לא כפי סדר עשייתן<sup data-n=\"1220\">26</sup> ע\"י האדם, דאף שהמנהג הוא שלובשים ציצית בבוקר תיכף לאחרי נט\"י<sup data-n=\"1221\">27</sup>, ולאח\"ז קורין ק\"ש, הרי ק\"ש באה לאחרי הנחת תפילין<sup data-n=\"1222\">28</sup>, וכדאיתא בגמ'<sup data-n=\"1223\">29</sup> \"כל הקורא ק\"ש בלא תפילין כאילו מעיד עדות שקר בעצמו כו'\" (וכמובא במפרשי רש\"י כאן<sup data-n=\"1224\">30</sup>)?\nויובן בהקדם עוד שינוי בלשון רש\"י ללשון המדרש: במדרש<sup data-n=\"1215\">21</sup> נאמר \"הרי הן ישנים מן התורה ומן המצות עמדו משנתן עומדים כאריות חוטפים קריאת שמע וממליכים להקב\"ה\", וברש\"י הלשון \"כשהן עומדין משינתם שחרית הן מתגב­רים כלביא וכארי לחטוף את המצות ללבוש כו'\". כלומר א) רש\"י משמיט מ\"ש במדרש \"הן ישנים מן התורה ומן ה­מצות\". ב) מוסיף על לשון המדרש הקדמה כללית — \"לחטוף את המצות\". ג) משמיט תוכן מצות ק\"ש המפורש במדרש \"וממליכים להקב\"ה\".\nויש לומר, שג' שינויים אלה תלויים זב\"ז:\nבמדרש שכתב \"הרי הן ישנים מן התורה ומן המצות\", מדגיש שהשינה היא (גם) שינה רוחנית<sup data-n=\"1226\">31</sup>, שאינם ערים לתורה ומצות של הקב\"ה, וה\"עמידה\" מ\"שינה\" זו כוללת גם ההתעוררות לתומ\"צ, שמ­קבלים עליהם עול מלכות שמים, וזהו שממשיך במדרש \"עמדו משנתן עומדים כאריות חוטפים קריאת שמע וממליכים להקב\"ה\".\nאבל ברש\"י שכ' כפשוטו, עומדים מ­שינת שחרית, היינו בזמן שאינם (חייבים ואינם) יכולים לקיים המצות, לכן תיכף כשעומדים הם מתגברים \"לחטוף את המצות\", היינו מצות בכלל, שכל המצות לא היו יכולים לקיימן בעת השינה.\nולכן כתבם בסדר זה דוקא, כי זהו לפי סדרן ביחס לכללות המצות:\nתחילה \"ללבוש ציצית\", שמצות ציצית שקולה כנגד כל המצות<sup data-n=\"1227\">32</sup>, וכמ\"ש בפרשת ציצית<sup data-n=\"1228\">33</sup> \"וראיתם אותו וזכרתם",[["1218","24","ודוחק גדול לומר שלא מנה תפילין שלפני הדיבור (פ' בא) כ\"א זה שלאחרי הדיבור (בסיום פ' שמע והי' אם שמוע)."],["1219","25","וגם לא לפי סדר קדושתן, דתפילין הוה מקודש לגבי ציצית, דתפילין הם תשמישי קדושה וציצית הם רק תשמישי מצוה — ראה בארוכה שאגת ארי' סי' כח, שמטעם זה הי' צריך להניח תפילין לפני לבישת הציצית. וראה זח\"ג פא, א ובמפרשים שם. לקוטי לוי\"צ לזהר שם. וראה פרמ\"ג בפתיחתו להל' תפילין בתחלתה. ואכ\"מ."],["1220","26","ולהעיר שגם זמן חיובן אחד הוא, משיראה את חבירו מרחוק ד\"א כו' — ראה הדיעות (ב\"י, ב\"ח, פרמ\"ג (משב\"ז) ועוד או\"ח רסנ\"ח). ולהעיר מגמ' מנחות שבהערה 40."],["1221","27","ראה טור, מג\"א ושו\"ע אדה\"ז או\"ח ר\"ס ח."],["1222","28","אלא שי\"ל שלדעת רש\"י נוהגין כן שקוראין ק\"ש לפני הנחת תפילין כהדיעות בזה — ראה שו\"ת בית יצחק או\"ח (סי\"ז) ואות חיים ושלום (לבעל מנח\"א) סכ\"ה סק\"ו — ע\"ד מנהג חסידים ואנשי מעשה לקרות ק\"ש בבוקר כשיעמדו ממטתם פן יעברו זמן ק\"ש, ושקו\"ט והאריכו בסדר ק\"ש ותפילין. ועיין בבית יצחק שם אות ב שמיישב דברי רש\"י בפרשתנו, כי לדידן דשבת לאו זמן תפילין הוי ק\"ש תדיר, ותדיר קודם. ע\"ש בארוכה. וראה שיחת ש\"פ שלח תשי\"ב."],["1223","29","ברכות יד, סע\"ב. וש\"נ."],["1224","30","ראה משכיל לדוד, שם אפרים, באר בשדה ועוד."],["1215","21","תנחומא, ועד\"ז בבמדב\"ר ויל\"ש עה\"פ (רמז תשסט)."],["1226","31","ראה שהש\"ר עה\"פ (שה\"ש ה, ב) אני ישנה ולבי ער. זח\"ג צה, א."],["1227","32","הובא גם בפרש\"י ס\"פ שלח טו, מא."],["1228","33","שם, לט. מ."]]],[1301430211,"את כל מצות ה' ועשיתם אותם\", \"למען תזכרו ועשיתם את כל מצותי\" [וכדאיתא בגמ'<sup data-n=\"1229\">34</sup> \"ולימא להו. . קיימו כל המצות כולן\" ומשני (דאז הי' קאי על) \"מצות ציצית<sup data-n=\"1230\">35</sup> דאמר מר שקולה מצות ציצית כנגד כל המצות כולן\"<sup data-n=\"1231\">36</sup>, ובספרי<sup data-n=\"1232\">37</sup> איתא ש\"כל המקיים מצות ציצית מעלים עליו כאילו קיים כל המצות\"]; ואח\"כ מביא \"לקרוא את שמע\", שגם היא מצוה כללית, שיש בה יחוד השם אהבתו כו' (ובכללות — קבלת עול מלכות שמים) שהיא יסוד<sup data-n=\"1233\">38</sup> כל המצות<sup data-n=\"1234\">39</sup>, אבל לא כמו מצות ציצית שהיא עצמה שקולה כנגד כל המצות (ומביאה לקיום כל המצות כולן) כנ\"ל<sup data-n=\"1235\">40</sup>; ואח\"כ \"ולהניח תפילין\", שהיא מצוה פרטית, אבל נאמר בה \"והי' לך לאות על ידך ולזכרון בין עיניך. . כי ביד חזקה הוציאך ה' ממצרים\"<sup data-n=\"1236\">41</sup>, ש­זכירת יצי\"מ היא יסוד לכמה מצוות התורה<sup data-n=\"1237\">42</sup>.\nה. ויש להוסיף בזה, שע\"פ הנ\"ל ה­חילוק בין פרש\"י ודברי המדרש הוא, אם קריאת שמע בבוקר היא (רק) בגדר דחטיפת קבלת עול מלכות שמים או שהיא בגדר דחטיפת כל מעשה המצוות.\nויש לומר, שזה תלוי בפלוגתא אם מצות ק\"ש מה\"ת היא רק פסוק ראשון בלבד או שכוללת יותר מזה (פרשה ראשונה, שתי פרשיות, או שלשתן)<sup data-n=\"1238\">43</sup>, והיינו אם גדר מצות ק\"ש הוא זה ש­ממליך את הקב\"ה עליו באמירת פסוק ראשון<sup data-n=\"1239\">44</sup> \"שמע ישראל ה' אלקינו ה' אחד\", שבו מקבל עליו יחודו ית' בפי­רוש<sup data-n=\"1240\">45</sup>, או שגדר מצות ק\"ש כוללת קבלת עול מצות (וכמפורש במשנה לגבי ב' פרשיות דק\"ש<sup data-n=\"1241\">46</sup>):\nלהמדרש, גדר ק\"ש הוא שממליכים את הקב\"ה והוא (בעיקר) בפסוק ראשון (או גם פרשה ראשונה<sup data-n=\"1242\">47</sup>), וכמשמע גם מהמשך דברי המדרש כנ\"ל \"ממליך להקב\"ה לא ישכב עד יאכל טרף כשהוא אומר ה' אחד נאכלין המחבלין מפניו, מלחשין אחריו ברוך שם כבוד מלכותו לעולם ועד\".",[["1229","34","נדרים כה, א. שבועות כט, סע\"א."],["1230","35","וראה תוד\"ה מצות ציצית שבועות שם: הא דשבק ע\"ז כו' משום דבלשון בנ\"א לא מקרי כל המצות אלא ציצית."],["1231","36","כ\"ה בשבועות שם. ועד\"ז הוא במנחות מג, ב. ובנדרים \"כנגד כל מצות שבתורה\". וראה פרש\"י שבועות ומנחות שם (ובנמוק\"י הל' ציצית (הובא בב\"י (וראה גם ב\"ח) או\"ח ר\"ס כה), שמטעם זה מתעטפין בציצית לפני תפילין)."],["1232","37","שלח טו, לט. הובא בספר הפרדס לרש\"י ריש הל' ציצית. בשבלי הלקט מהל' ציצית (של רש\"י). ועוד."],["1233","38","ראה לשון הרמב\"ם הל' ק\"ש פ\"א ה\"ב. וראה לקמן בפנים."],["1234","39","ולהעיר ממנחות שם: \"ראה מצוה זו וזכור מצוה אחרת התלוי' בו ואיזו זו זו קרית שמע\", ובחדא\"ג מהרש\"א שם \"דהיא (ק\"ש) נקראת כל מצות ה' שיש בק\"ש עיקר האמונה קבלת מלכות ואחדות כו' נמצא כשנזהר בק\"ש שמפורש בה כלל אמונה זוכר את כלל המצות כולן\"."],["1235","40","ולהעיר גם מ\"תניא אידך\" במנחות שם: וראיתם אותו וזכרתם את כל מצות ה', כיון שנתחייב אדם במצוה זו נתחייב בכל המצות כולן. וראה פרש\"י שם."],["1236","41","בא יג, ט ובפרש\"י. וראה גם שם, טז."],["1237","42","ראה חינוך מצוה טז. כא. ועוד."],["1238","43","ראה קרית ספר (להמבי\"ט) ריש הל' ק\"ש. פר\"ח (ונ\"כ השו\"ע) או\"ח סי' סז. שו\"ת שאג\"א סי' ב'. פרמ\"ג בהקדמתו לאו\"ח הלכות ק\"ש. ובכ\"מ. וראה שו\"ע אדה\"ז ר\"ס נח. וש\"נ. ועוד."],["1239","44","ואתחנן ו, ד."],["1240","45","ראה תניא פמ\"ז."],["1241","46","ברכות יג, א. וראה שם ע\"ב. יד, ב. ובמפרשים שם."],["1242","47","ראה תר\"י שהובאו בב\"י או\"ח סו\"ס סג. וראה לשון הרמב\"ם הל' ק\"ש פ\"א ה\"ב."]]],[1301430212,"ואילו לפרש\"י גדר מצות ק\"ש כולל שממליכים את הקב\"ה בה' אחד, קבלת עומ\"ש בפרשה ראשונה, וקבלת עול מצות, ולכן כולל ב\"לחטוף את המצות\" גם קריאת שמע.\n[ואולי י\"ל יתירה מזו, שלדעת רש\"י (בפירושו עה\"ת) מצות ק\"ש כוללת גם פרשה שלישית, כי אין קיום מצות ק\"ש בשלימותה בקבלת עול מצות בכלל אלא כאשר מקבל עליו מצות ציצית<sup data-n=\"1243\">48</sup> הכוללת (זכירת) כל המצות כולן<sup data-n=\"1244\">49</sup>. ולכן כאשר בא לקיים המצות כדבעי (שזהו תוכן הענין ד\"לחטוף את המצות\" כד­לקמן ס\"ו) (גם מצות ק\"ש), הרי אינו מסתפק בזה שקורא פרשת ציצית, אלא לובש ציצית ואח\"כ קורא את שמע (כולל פרשת ציצית), כדי שתהא זכירת כל המצות ע\"י מצות ציצית<sup data-n=\"1245\">50</sup> בפועל<sup data-n=\"1246\">51</sup>].\nו. וע\"פ מה שנתבאר לעיל (ס\"ב), ש­הקדים רש\"י פי' המדרש לתרגומו, כי ע\"פ פשש\"מ מסתבר יותר (בפרט בנבואה זו (השני') דבלעם) שמדבר במעלת ישר­אל במעשיהם, ולא רק זה שהקב\"ה עושה עמהם (שמראה גודל כחם כו' כלפי אוה\"ע), יש לבאר הטעם ששינה רש\"י בענין זה מהמדרש:\nחטיפה מורה שהדבר הנחטף חביב ביותר אצל החוטף<sup data-n=\"1247\">52</sup>, דדבר שאינו יקר וחביב לו כ\"כ לוקחו בניחותא, משא\"כ דבר החביב עליו — חוטפו.\nולפ\"ז מובן, דענין \"חוטפים ק\"ש וממ­ליכים להקב\"ה\" שבמדרש מורה שענין ה\"חטיפה\" הוא רק לגבי עצם קבלת עול מלכותו ית', אבל קיום התומ\"צ שלאח\"ז בא באופן רגיל, בניחותא.\n[ולכן לא נזכר במדרש בהמשך לזה קיום המצות, אלא \"מפליגין לדרך ארץ למשא ומתן\", כי בקיום המצות עצמן לא ניכרת מעלה מיוחדת בקיומם, והמלכת הקב\"ה בק\"ש באופן שחוטפין ק\"ש מועי­לה להם דכאשר מפליגין לדרך ארץ ו­למשא ולמתן תהי' הפלגה זו באופן כשר, משאו ומתנו באמונה<sup data-n=\"1248\">53</sup>, ו\"כל מעשיך יהיו לשם שמים\"<sup data-n=\"1249\">54</sup>, וכיו\"ב].\nואילו לפרש\"י טבע בני ישראל הוא שכשהם עומדים משנתם שחרית הן מתגברים \"לחטוף את המצות\", שכל ה­מצות יקרים וחביבים הם אצל כאו\"א מישראל, שחוטפין את המצות, ואינו מסתפק בחטיפת מצוה אחת, אלא שחוט­",[["1243","48","ראה ברכות יב, ב: \"פרשת ציצית מפני מה קבעוה כו' מפני שיש בה חמשה דברים מצות ציצית יצי\"מ עול מצות כו'\". ע\"ש."],["1244","49","ראה רמב\"ם שם ובנו\"כ שם. ובהנסמן בהערה 43."],["1245","50","להעיר מפרש\"י ברכות שם שפי' מ\"ש בגמ' \"עול מצות\" — \"ועשיתם את כל מצותי\", ואינו מובן שהרי בש\"ס מפורש \"עול מצות וראיתם אותו ו­זכרתם את כל מצות ה'\"? אלא שרש\"י מפרש הכוונה בגמ' שבשביל קבלת \"עול מצות\" אמיתית אינו מספיק \"וראיתם אותו וזכרתם גו'\" — רק זכירת המצות, אלא צ\"ל (גם) \"ועשיתם את כל מצותי\", קבלת עשייתן בפועל. וראה לשון הרמב\"ם הל' ק\"ש שם ובנ\"כ שם. וראה לעיל ע' 100 הערה *46. ועצ\"ע."],["1246","51","ולהעיר מברכות שם (יד, סע\"ב ואילך): \"הרוצה שיקבל עליו עומ\"ש שלימה כו' יניח תפילין ויקרא ק\"ש ויתפלל\", ושקו\"ט למה לא הובא ציצית — ראה ב\"ח ופרישה לטאו\"ח סו\"ס ב. שו\"ע אדה\"ז סי' סו ס\"ג וסי\"א. ועוד."],["1247","52","ראה חולין קלג, א. אלא דלמסקנא שם ישנו לימוד מיוחד \"ונתן ולא שיטול מעצמו\", ולכן לא הוי חביבותא. וגם מובן הוא כיון שהמדובר בדבר שהוא לאכילה והנאת הגוף, משא\"כ בנדו\"ד דקיום מצות שאין בה הנאת הגוף. וראה ברכות (נג, ב) \"חטוף ובריך\"."],["1248","53","שבת לא, סע\"א."],["1249","54","אבות פ\"ב מי\"ב. רמב\"ם ספ\"ג מהל' דיעות."]]],[1301430213,"פים עוד מצוה, קריאת שמע, וחוטפים עוד מצוה, הנחת תפילין, ומובן שכן הוא בהמשך כל היום כולו בקיום מצותיו של הקב\"ה.\nוזה מבטא אופן נעלה יותר במעלתן של ישראל.\nז. ע\"פ הנ\"ל תובן גם השייכות דפ' בלק (שקורין בכל שנה בסמיכות) לי\"ב תמוז, היום שבו נגאל כ\"ק מו\"ח אדמו\"ר ממאסרו אשר נאסר בגלל \"העבודה ה­גדולה\" אשר עבד \"בהרבצת תורה וחי­זוק הדת\"<sup data-n=\"1250\">55</sup>.\nהפירוש ד\"חטיפה\" הוא — פעולה ש­לא ע\"פ סדר וחשבון, ובעבודת ה' ה\"ז מורה על עבודה שלמעלה מטעם ודעת, העבודה דמסירת נפש<sup data-n=\"1251\">56</sup>.\nוזה הי' אופן העבודה הגדולה אשר עבד כ\"ק מו\"ח אדמו\"ר במדינה ההיא, ואשר בה חינך ולימד את תלמידיו ו­חסידיו, עבודה באופן של מסירת נפש בפועל, ולא רק על ענינים כלליים ו­ענינים עיקריים של תורה ומצות, אלא על כל מצוה ומצוה, קלה כחמורה, מס\"נ על בנין או החזקת מקוה, לייסד חדרים ללמוד עם תשב\"ר אל\"ף­בי\"ת וכיו\"ב, וביחד עם זה ובאותו התוקף ומסנ\"פ להפצת פנימיות התורה, רזין דאורייתא, וכן מס\"נ על הידור במצות.\n[וגם באופן עבודה זו דחטיפה, מסנ\"פ על כל צעד, בקש ותבע בשיחותיו ב­אותו הזמן<sup data-n=\"1252\">57</sup> חטיפה בתוך חטיפה, מס\"נ בתוך מס\"נ, \"יהודים חיטפו מס\"נ חיטפו, כי עובר וחולף הזמן של מסנ\"פ, עוד מעט ויבוא זמן של חופש גמור בעניני הדת ואז תחפשו אופן דמסירת נפש ולא תמצאו, עוד מעט ויבוא זמן שתדברו במעלתו של מי שזכה \"לשבת\" (בבית האסורים) בגלל היותו מלמד, בגלל החזיקו חדר, ישיבה או מקוה טהרה. תתקנאו בהם ותצטערו על עצמכם שאתם לא זכיתם לכך, יהודים — חיטפו מסנ\"פ\"].\nובכח זה עמדו בנ\"י במדינה ההיא במשך עשיריות בשנים במצב של גזירות ורדיפות על הדת, וכח זה הטביע ב­שלוחיו ובהולכים באורחותיו, אשר גם בהיותם בחסדי ה' במצב של חירות לא יסתפקו באופן של חוטפין ק\"ש להמליך עליהם את הקב\"ה, אלא שתהי' אצלם גם העבודה לחטוף את המצות — כל ה­מצות, ולא להתחשב בשום חשבונות ומניעות ועיכובים, ולא להתפעל ממלעי­גים כו', הן בעבודת ה' בעצמה, והן ב­הפצת התורה והיהדות.\nעדי קיום היעוד המפורש בפרשת בלעם<sup data-n=\"1253\">58</sup> \"וקם<sup data-n=\"1254\">59</sup> שבט מישראל. . והי' ירשה גו' זה המלך המשיח שנאמר<sup data-n=\"1255\">60</sup> ועלו מושיעים בהר ציון וגו' והיתה לה' המלוכה\".\n<span data-k=\"q\">(משיחת ש\"פ בלק תשל\"א)</span>",[["1250","55","לשון כ\"ק מו\"ח אדמו\"ר במכתבו לחגיגת י\"ב תמוז הראשונה בשנת תרפ\"ח — נדפס בסה\"מ תרפ\"ח ע' קמו. תש\"ח ע' 263. אג\"ק שלו ח\"ב ע' פ. ועוד."],["1251","56","וראה לקו\"ש חכ\"ה ע' 279 ואילך שחטיפה מורה על לקיחת דבר היפך רצונו דמנגד, והו\"ע עבודת התשובה. ע\"ש. וש\"נ."],["1252","57","י\"ט כסלו תרפ\"ז (שנת המאסר) — סה\"ש תרפ\"ז ע' 120 ואילך, הובא בס' התולדות אדמו\"ר מהוריי\"ץ ח\"ג (קה\"ת תשל\"ב ושלאח\"ז) ע' 55."],["1253","58","רמב\"ם הל' מלכים פי\"א ה\"א."],["1254","59","פרשתנו כד, יז­יח."],["1255","60","עובדי' א, כא."]]],[1301430214,"<h3>שיחה א</h3>\nא. כ\"ק מו\"ח אדמו\"ר סיפר<sup data-n=\"1256\">1</sup>, שבשנת תר\"מ<sup data-n=\"1257\">2</sup>, בש\"ק י\"ז בתמוז, הי' זקנו אדמו\"ר מהר\"ש בשמחה גדולה, והזכיר כמה פעמים<sup data-n=\"1258\">3</sup> ששבת זה נקרא \"נדחה\", כי צום שבעה עשר בתמוז נדחה ע\"י ש\"ק, וסיים \"הלואי שיהי' נדחה באמת\".\nוהנה לפי פשוטם, דברי אדמו\"ר מהר\"ש הם בגדר ברכה ותפלה (וכמו ש­סיים כ\"ק מו\"ח אדמו\"ר: ברכה של צדיק הלא מתקיימת, הלואי שכן יהי', ושיהי' נדחה באמת ויהפך לששון ולשמחה). אבל (נוסף לזה שאפילו שיחות חולין של ת\"ח צריכין לימוד<sup data-n=\"1259\">4</sup>, וכ\"ש וק\"ו תפי­לותיהם וברכותיהם, הרי) ע\"פ הידוע גודל הדיוק בדברי רבותינו נשיאינו, יש לומר, שבדיוק לשונו טמון ומרומז תוכנו של תענית נדחה, הן ע\"פ הלכה, והן ע\"פ פנימיות התורה.\nב. בהשקפה ראשונה הקשר בין ד­חיית צום (י\"ז תמוז) ע\"י יום השבת ל­דחייתו לגמרי לעתיד לבוא, פשוט הוא, דאין זה רק דחי' מזמנו הקבוע לזמן אחר, אלא שהדחי' פועלת גם המעטה בחומר התענית, כי הצום הנדחה (ליום ראשון) קיל מכשהוא בזמנו [וכמפורש בהלכה לענין ברית מילה<sup data-n=\"1260\">5</sup>, דכאשר ה­צום הוא בזמנו חייב בעל הברית להש­לים התענית, אבל כשחל בשבת ונדחה ליום הראשון אין בעל הברית משלים תעניתו<sup data-n=\"1261\">6</sup> מפני שיו\"ט שלו הוא], ומכיון שנתמעט חומר התענית הרי י\"ל שזוהי התחלה לביטולה לגמרי.\nויסוד לזה (שדחיית התענית ממעטת חומרתו, עד שנותנת מקום לדחייתה לגמרי) הוא בדברי רבי<sup data-n=\"1262\">7</sup> לענין \"תשעה באב שחל להיות בשבת. . ודחינוהו ל­אחר השבת ואמר רבי הואיל ונדחה ידחה\", היינו דס\"ל שכיון שאי אפשר ל­התענות בזמנו, בטל חיוב התענית לגמרי בשנה כזו.\nועפ\"ז יש לבאר דברי אדמו\"ר מהר\"ש<sup data-n=\"1263\">8</sup> בהקדם ביאור והסברה בדברי רבי הנ\"ל \"הואיל ונדחה ידחה\".\nג. בגמ' שם פליגי חכמים על דברי רבי, ולכאורה י\"ל שתוכן הפלוגתא הוא — אם הדחי' משבת ליום א' עושה יום א' \"זמנו\" של התענית (וזוהי דעת חכמים).\n[ועפ\"ז י\"ל שרבי ורבנן לשיטתייהו",[["1256","1","שיחת י\"ב תמוז (יום הולדת וחג הגאולה שלו) ה'ש\"ת (נדפס בספר השיחות ה'ש\"ת ע' 157)."],["1257","2","השנה שבה נולד כ\"ק מו\"ח אדמו\"ר — שהקביעות היתה (כבשנה זו (תשמ\"ח)) די\"ב תמוז חל ביום שני, ובמילא י\"ז תמוז הוא בש\"ק ונדחה."],["1258","3","בליל ש\"ק (בה\"שלום זכר\") וביום השבת."],["1259","4","סוכה כא, ב. ע\"ז יט, ב."],["1260","5","בת\"ב — טושו\"ע סי' תקנט ס\"ט. ב\"י שם. וראה מג\"א שם סקי\"א (ובמחה\"ש) דכ\"ה בנוגע לשאר הצומות י\"ז בתמוז וכו', דרק כשנדחה אין בעל הברית משלים תעניתו."],["1261","6","וראה הגהות רעק\"א בשו\"ע שם (מתשובת שבות יעקב): וכן בחולי קצת ומעוברת שיש מיחוש קצת מותרים לאכול. וראה שד\"ח פאת השדה (אסיפת דינים) מע' בין המצרים ס\"א אות יג (ח\"ט א'תשסב, א) עוד קולות בתענית שבעה עשר בתמוז כו' נדחה."],["1262","7","מגילה ה, ריש ע\"ב."],["1263","8","ולכאורה כש\"כ הוא, דהרי בנוגע לת\"ב אמר ר\"י (תענית כט, א) \"אלמלי הייתי באותו הדור לא קבעתיו אלא בעשירי מפני שרובו של היכל בו נשרף\" (וראה תוד\"ה ובקש (מגילה שם) בתירוץ הב', שזוהי הס\"ד בדברי ר\"א דביקש רבי לעקור ת\"ב), משא\"כ בדחיית שבעה עשר בתמוז לי\"ח תמוז דקיל טפי. אבל ראה שו\"ת חת\"ס או\"ח סל\"ג, וראה במקומות שנסמנו לקמן הערה 11."]]],[1301430215,"אזלי, ד\"תניא<sup data-n=\"1264\">9</sup> חל (י\"ד אדר) להיות ב­שבת כפרים מקדימין ליום הכניסה ו­עיירות גדולות קורין בע\"ש כו' רבי אומר אומר אני הואיל ונדחו עיירות ממקומן ידחו ליום הכניסה. . זמנם שבת היא והואיל דנדחו ידחו\", שרבי סבירא לי' שהתקנה דמקרא מגילה היתה שבכל שנה יקראו פרזות בי\"ד ומוקפין בט\"ו, אלא שמפני גזירה דרבה דחו תקנה זו<sup data-n=\"1265\">10</sup>, ורבנן ס\"ל שמפני גזירה דרבה היתה מלכתחילה התקנה דמקרא מגילה שכש­יחול י\"ד בשבת יקדימו את זמנה].\nוע\"ד השקו\"ט באחרונים כעין זה ב­נוגע להלכה בפועל<sup data-n=\"1266\">11</sup>, אם חיוב התענית בצום הנדחה משבת ליום א' הוא בתורת תשלומין או שכן היתה התקנה מעיקרא, שכשחל בשבת נקבע זמן התענית ליום ראשון. וכתבו כמה נפק\"מ לדינא, ול­דוגמא: א) קטן שנתגדל ביו\"ד באב, דאם זהו יום התענית (בשנה זו), אזי יש חיוב על הקטן להתענות כיון שגדל בו ביום. אבל אם התענית ביום א' הוי רק תש­לומין להתענית דט' באב (שחל בשבת), הרי כיון שביום התענית עדיין אינו בר חיובא, שוב אינו חייב בתשלומין. ב) מתי חל הדין (וחומרא) דשבוע שחל בו תשעה באב<sup data-n=\"1267\">*11</sup>, דאת\"ל דחיוב התענית דיום א' (הנדחה) הוא מעיקר התקנה, א\"כ השבוע שלפני השבת אינו שבוע שחל בו ת\"ב<sup data-n=\"1268\">12</sup>, משא\"כ אם יום א' הוי בגדר ה­שלמה, הרי השבוע שלפנ\"ז הוא השבוע שחל בו ת\"ב<sup data-n=\"1269\">*12</sup>, כיון דדין ת\"ב לא בטל ע\"י יום השבת ומחוייב בתשלומין. ג) ל­ענין אבילות בדברים שבצנעה, אם נוה­גין בת\"ב שחל בשבת: הדיעות שאין נוהגין דברים שבצנעה ס\"ל שלגמרי עקרוהו ואוקמינהו אעשירי<sup data-n=\"1270\">13</sup>, משא\"כ ה­דיעות שנוהגין דברים שבצנעה בשבת.\nאבל דוחק קצת לפרש כן פלוגתת רבי ורבנן בדחיית תענית ת\"ב, דכיון שלא קיי\"ל כרבי (כי לא הודו לו חכ­מים), נמצא שלהלכה אין זה דחי', אלא דבשנה זו תענית ת\"ב זמנו הוא ביום א' (מעיקר הדין והתקנה); אבל בשו\"ע",[["1264","9","מגילה ד, ב."],["1265","10","וראה לקו\"ש ח\"ז ע' 50 ואילך ובהערות שם, שאין סברא לומר שפלוגתתם היא בזמן התקנה — דרבנן סברי שביחד עם תקנת מקרא מגילה תקנו אנשי כנה\"ג שכשחל בשבת קורין עיירות גדולות בע\"ש, ורבי סבר שתקנת הקדימה היתה ע\"י חכמי ישראל שאחר כנה\"ג (ראה רש\"י מגילה ה, א ד\"ה ערב שבת) — אלא י\"ל דלכו\"ע היתה התקנה על ידי אנשי כנה\"ג, ופליגי באיזה אופן דחוהו. וי\"ל שעד\"ז הוא בנדו\"ד דהרי בעת שגזרו להתענות ידעו שיזדמן שיחול בש\"ק ופליגי באופן תקנת הדחי'. אבל צ\"ע בלשון הגמרא \"ודחינוהו לאחר השבת ואמר רבי הואיל ונדחה כו'\". ואכ\"מ."],["1266","11","בכל הבא לקמן ראה צפע\"נ הפלאה ב­השמטות (נד, סע\"ג ואילך). מהד\"ת כח, ג. שו\"ת דווינסק ח\"ב סל\"א­לב. שו\"ת ווארשא (נ.י.) ח\"א סמ\"ד. שו\"ת אבני נזר או\"ח סי' תכו. שו\"ת כתב סופר או\"ח סק\"א. מהרש\"ם ח\"ג סשס\"ג. ועוד."],["1267","*11","ראה ב' הדיעות בטושו\"ע או\"ח סתקנ\"א ס\"ד."],["1268","12","להעיר ממהרי\"ל הל' ת\"ב: כאילו איקלע קביעותא בא' בשבת דמי."],["1269","*12","ראה מג\"א שם סקי\"ז. וראה צפע\"נ שבהערה 11, שלהסברא שהתענית ביום א' \"הוי גדר תשלום\" — אין כאן הדין ד\"לאחריו\" (כמ\"ש בירושלמי תענית פ\"ד ה\"ו. אלא דשם, שאז גם אין הדין ד\"לפניו\". ולהעיר מסמ\"ק (סי' צו. הובא בטור שם) שגם להדיעה דיש דין דלפניו (כשחל ת\"ב בשבת), \"הוא רק חומרא יתירה\", כי יש חילוק \"בין חל להיות בתוכה בין חל להיות בשבת\")."],["1270","13","שו\"ת הרשב\"א ח\"א סתק\"כ (הובא באבני נזר שם בסופו. ועוד)."]]],[1301430216,"מפורש<sup data-n=\"1271\">14</sup> (כנ\"ל) שדוקא \"ט' באב שחל להיות בשבת ונדחה ליום ראשון, בעל ברית מתפלל מנחה בעוד היום גדול ורוחץ ואינו משלים תעניתו לפי שיום טוב שלו הוא\", משא\"כ כשהברית מילה היא בת\"ב עצמו חייב הוא להשלים<sup data-n=\"1272\">15</sup> — הרי מובן מזה, שלהלכה קיי\"ל דת\"ב שנדחה ליום א' אינו חמור כת\"ב שלא נדחה היינו שהוא בגדר דחי' ואינו מ­עיקר התקנה (דאל\"כ מדוע מקילים בו לענין בעל ברית)<sup data-n=\"1273\">16</sup>.\nוע\"כ צ\"ל שגם לדעת רבנן, התענית ביום א', כשחל ת\"ב בשבת, ה\"ז בגדר דחי', ולכן אינו חמור כתענית שביום ת\"ב עצמו — ופלוגתת רבי ורבנן היא ב­גדרה של \"דחי'\" זו עצמה, שיש לפרשה בכמה אופנים, כדלקמן.\nד. מבואר באחרונים<sup data-n=\"1274\">17</sup>, שבתענית יש ב' ענינים (ואופנים): חלות שם תענית על היום, וחלות דיני וחיובי התענית על האדם<sup data-n=\"1275\">18</sup>.\nולפי זה י\"ל, דפלוגתת רבי ורבנן אינה בחומרת התענית דיום ראשון (שנד­חית משבת), אלא בגדרו של יום השבת שהתענית שבו נדחית — אם הדחי' בשבת היא רק בקיום דיני התענית, אבל נשאר בה ענין יום תענית — וזוהי דעת רבנן; או שנדחה בשבת גם ענין יום התענית — והיא דעת רבי, דרבי ס\"ל שלגמרי נדחה חלות יום התענית ובכה\"ג אין חלות יום תענית (אלא כיון שהתענית רק נדחה, נשארו איזה דיני ת\"ב, כמו דברים שב­צנעה<sup data-n=\"1276\">*18</sup> וכיו\"ב).\nאבל דבר זה צריך ביאור, דאיך אפשר לומר שיש ענין תענית ביום ד­שבת, הרי שבת אסור בתענית, ואדרבה יש חיוב לענגו באכו\"ש וכו'<sup data-n=\"1277\">19</sup>, ולכמה דיעות<sup data-n=\"1278\">20</sup> איסור התענית בו הוא מדאו­רייתא (וכתב אדה\"ז<sup data-n=\"1279\">21</sup>, דאיסור התענית נפק\"ל מדכתיב<sup data-n=\"1280\">22</sup> \"אכלוהו היום כי שבת היום לה'\", מכלל דבשבת אסור להת­ענות).\nויש לומר בביאור הדבר (בפנימיות הענינים):",[["1271","14","סי' תקנט ס\"ט. וכ\"ה בטור שם."],["1272","15","כמ\"ש המג\"א שם בשם הב\"י. ואף שהב\"י לא כתבו בשו\"ע בפירוש, הרי מובן הוא מזה שכתב הדין רק בת\"ב שחל בשבת."],["1273","16","אלא שצ\"ע בדעת השו\"ע, שהרי בסתקנ\"א ס\"ד הביא ב' דיעות בת\"ב שחל בשבת \"אם מותר בשתי שבתות\"; ולענין דברים שבצנעה כ' (סתקנ\"ד סי\"ט) דת\"ב שחל בשבת מותר בכולן אפילו כו'<sup data-n=\"e30\">*</sup>, ומזה משמע לכאורה דס\"ל דבשנה זו עקרוהו לגמרי מט' באב וקבעוהו ליו\"ד כהרשב\"א הנ\"ל. וא\"כ שוב אין להוכיח (לכאורה) מדין הנ\"ל, דרק בת\"ב נדחה אין בעל הברית משלים, דהוי בגדר השלמה. וכבר האריכו בספרים בהשקו\"ט בזה — ראה הנסמן בהערה 11. ובכל אופן, הביאור בפנים הוא להדיעות דס\"ל דאנן קיי\"ל להלכה דהוי בגדר תשלומין."],["1274","17","ראה בצפע\"נ שבהערה 11 ובצפע\"נ הל' תענית פ\"א ה\"ט. ועוד."],["1275","18","ובצפע\"נ שם מבאר: וזה נ\"מ ג\"כ בין קבלה אז הוי היום יום תענית ובין בלא קבלה אז הוי רק גדר איסור אכילה."],["1276","*18","את\"ל שלדעת רבי דברים שבצנעה נוהגים בת\"ב שחל בשבת. ואכ\"מ."],["1277","19","ראה שו\"ע אדה\"ז ריש הל' שבת. וש\"נ."],["1278","20","שו\"ת הרשב\"א ח\"א סי' תריד — לדעת הרמב\"ם הל' שבועות פ\"א ה\"ו (הובא לקמן בפנים). וראה שו\"ת הצ\"צ או\"ח סל\"ו."],["1279","21","או\"ח סי' רמב קו\"א סק\"א. ועד\"ז בפרמ\"ג או\"ח (א\"א) סי' רפח סק\"ז."],["1280","22","בשלח טז, כה."],["e30","*","ובשו\"ת כתב סופר שם, שגם כוונת הרמ\"א שם \"ויש אוסרין\" הוא לא מדינא, אלא מכח מנהגא שנתקבל בזה. ע\"ש בארוכה."]]],[1301430217,"התענית ענינו הוא (בלשון הכתוב<sup data-n=\"1281\">23</sup>) \"יום רצון לה'\". ואף שזה נאמר (בעיקר) בתענית שהוא לתשובה וכפרה<sup data-n=\"1282\">24</sup>, משא\"כ ד' הצומות, ובפרט ת\"ב, ה\"ה בגדר אבי­לות<sup data-n=\"1283\">25</sup> על הצרות שאירעו בזמנים אלו — הרי כתב הרמב\"ם<sup data-n=\"1284\">26</sup> שגם צומות אלו הם \"כדי לעורר הלבבות לפתוח דרכי התשובה ויהי' זה זכרון למעשינו הרעים ומעשה אבותינו שהי' כמעשינו עתה עד שגרם להם ולנו אותן הצרות, שבזכרון דברים אלו נשוב להיטיב שנאמר<sup data-n=\"1285\">27</sup> ו­התודו את עונם ואת עון אבותם וגו'\", דמזה מוכח שיש בתעניות אלו שני ה­ענינים<sup data-n=\"1286\">28</sup>.\nוהיינו שהיותו \"יום רצון\" מתגלה על ידי הצום והנהגות התענית שביום זה, וכדאיתא בגמרא<sup data-n=\"1287\">29</sup> \"שיהא חלבי ודמי שנתמעט כאילו הקרבתיו לפניך על גבי המזבח ותרצני\"<sup data-n=\"1288\">30</sup>.\n[ובזה יש לבאר מש\"נ בזכרי'<sup data-n=\"1289\">31</sup> והובא ברמב\"ם<sup data-n=\"1290\">32</sup> להלכה, שלעתיד (לא רק ש­יבטלו כל הצומות, אלא עוד זאת, ש)­ייהפכו (הצומות) לימים טובים וימי ששון ושמחה.\nדלפי פשוטו צ\"ע: ביטול הצומות ל­עת\"ל מובן, דכיון שהצומות הם לזכר הצרות שאירעו לאבותינו, לכן, בהבטל זכרון הצרות (על ידי הגאולה) בטלים בדרך ממילא הצומות — אבל מדוע יהפכו ימים אלה לששון ולשמחה<sup data-n=\"1291\">33</sup>? ד­לכאורה, לשמחה מה זו עושה?\nאבל ע\"פ הנ\"ל מובן, כי עיקר ה­תענית אינו העינוי שבו, כ\"א זה שהוא \"יום רצון לה'\"<sup data-n=\"1292\">34</sup>, אלא שבזמן הגלות, כשעדיין לא בטלו חטאינו (שגרמו ל­\"גלינו מארצנו\"), הרי הדרך להרגיש ולנצל מעלת היום היא על ידי עינוי הגוף, שזה מעורר את האדם לתשובה וכו'; משא\"כ לעתיד לבא, כאשר \"את רוח הטומאה אעביר מן הארץ\"<sup data-n=\"1293\">35</sup>, אין מקום לעינוי (הגוף), אלא להוספה בעבודת ה' ועבודה זו ה\"ה מתוך שמחה וטוב לבב, ולכן יהיו ימי רצון אלה ימי שמחה, שיהפכו לימים טובים]<sup data-n=\"1294\">36</sup>.",[["1281","23","ישעי' נח, ה."],["1282","24","ראה תניא אגרת התשובה פ\"ב."],["1283","25","ראה זכרי' ז, ג ואילך. ירושלמי ברכות פ\"ב ה\"ז. ובתויו\"ט תענית פ\"ד מ\"א ד\"ה במנחה שלדעת הרמב\"ם \"ד' צומות לא הוקבעו אלא לאבל\". וראה רא\"ש תענית סל\"ב. ועוד."],["1284","26","הל' תעניות רפ\"ה."],["1285","27","בחוקותי כו, מ."],["1286","28","וראה שו\"ת חתם סופר או\"ח סי' רח (ד\"ה מ\"מ וקראת), שלהרמב\"ם \"נקבעו על התשובה\" (ולא כמו \"שהיינו חושבים שהתעניתים הללו אינם על דרך התשובה אלא ע\"ד האבל\")."],["1287","29","ברכות יז, א."],["1288","30","וראה אגה\"ת שם."],["1289","31","ח, יט."],["1290","32","סוף הל' תעניות. וראה טור או\"ח סו\"ס תקפ."],["1291","33","ראה אוה\"ת מסעי ס\"ע א'שפד ואילך."],["1292","34","ועפ\"ז מובן ג\"כ בפשטות הא דאי' בגמ' (ר\"ה יח, ריש ע\"ב) בפי' הכתוב (זכרי' שם) \"צום הרביעי וצום החמישי גו' יהי' גו' לששון ולשמחה קרי להו צום וקרי להו ששון ושמחה בזמן שיש שלום יהיו לששון ולשמחה אין שלום צום כו'\", דאיך קורא לאותו יום עצמו בשני שמות הפכיים, ואיך נהפך יום זה מההיפך אל ההיפך? אלא כי עצם תוכן היום הוא יום רצון, אלא שפעולתו וגילויו הוא בהתאם להזמן ומעשה האדם שבזמנים אלו (כבפנים), דבזמן שיש שלום ששון ושמחה אין שלום כו'. ע\"ש בגמ'. וראה צדה לדרך (לר\"מ בר\"א בן זרח) מאמר חמישי כלל ראשון פ\"א."],["1293","35","זכרי' יג, ב."],["1294","36","וי\"ל שזה מוכח מזה גופא שלעתיד יהפכו ויהיו לששון ולשמחה, שזהו אמיתית תוכן ענין הצומות, שהרי לעת\"ל, כל המצות תהיינה על מילואן ושלימותן (ראה רמב\"ם הל' מלכים רפי\"א), \"כמצות רצונך\". ועפ\"ז יומתק גם זה שד' הצומות ה\"מפורשים בקבלה\", הביאם הרמב\"ם (הל' תעניות פ\"ה ה\"ד) מהכתוב בזכרי' \"צום הרביעי גו'\" — שאינם מפורשים בו בתור יום צום כשלעצמם, אלא רק ש\"צום הרביעי וגו' יהי'. . לששון גו'\", היינו שהפסוק בא לומר (לא עצם הצום, כ\"א זה ש)הצומות יהפכו לששון ולשמחה כו'."]]],[1301430218,"ועפ\"ז מובן, דכשחל ת\"ב או א' משאר ד' הצומות ביום השבת, דאין עצב בה<sup data-n=\"1295\">37</sup>, הרי זה שאי אפשר להתענות בו אינו מבטל הענין שיום זה הוא \"יום רצון\", ואדרבה, שהרי שבת מצ\"ע הוא ג\"כ יום ועת רצון, חמדת ימים אותו קראת<sup data-n=\"1296\">38</sup>.\nכלומר: הנשבע שיתענה בשבתות וב­ימים טובים ה\"ז שבועת שוא<sup data-n=\"1297\">39</sup>, כי בימים אלו אסור להתענות והוא נשבע לבטל את המצוה — כי המדובר הוא בפעולת הגברא שיתענה; אבל ימים שמלכתחילה נקבעו ע\"פ תורה לימי תענית, צום הרביעי וצום החמישי וכו', כאשר הם חלים בשבת — הרי אף שהגברא אי אפשר שיתענה ביום זה, מ\"מ החפצא ד­היום (תענית), שהוא יום רצון לה'<sup data-n=\"1298\">40</sup>, במקומו הוא.\nוזהו דס\"ל לרבנן, שגם כשחל יום ה­צום בשבת, ישנם ב' הענינים, יום תענית בתור יום רצון, שהוא ביום השבת, ו­מעשה האדם שביום הצום שנדחה ליום א'.\nה. ויש לבאר זה בעומק יותר, ע\"פ המבואר בכ\"מ<sup data-n=\"1299\">41</sup> בנוגע לתענית דיום ה­כפורים (מ\"ע מה\"ת — וי\"ל שהוא אבוהון דכולהו תעניות) שענינו — \"לחיותם ב­רעב\"<sup data-n=\"1300\">42</sup>, והיינו שמה\"רעב\" דיוהכ\"פ גופא נמשכת חיות להנשמה (ועד \"שהחיים שלהם הוא מבחי' הרעב גופא מה שהם רעבים וצמאים אליו ית'\"), וזה מחי' גם את הגוף כפשוטו.\nוהיינו דהחיות הנמשכת להאדם ביום התענית ע\"י הרעב, היא חיות נעלית יותר מהחיות שעל ידי אכילה ושתי', כי כל מהותה הוא חיות דקדושה (שהרי אין בו אכילה ושתי' וכו', והאדם עסוק רק בעניני קדושה — ובזה הוא חיותו ביום זה)<sup data-n=\"1301\">43</sup>; וי\"ל דמיום הכפורים נמשך הענין ד\"לחיותם ברעב\" (חיות להנשמה מהרעב גופא) גם לשאר הצומות (שמדברי קבלה).\nוהנה גם בשבת האכילה והשתי' אינה דומה לאכילה ושתי' דימות החול, שע\"ד הרגיל והרוב — מתענג האדם מאכו\"ש גשמיים והתענוג שלו הוא תענוג דחול, משא\"כ אכילת שבת, שמצוה לענגו, הרי האכילה והתענוג הם קדושה ומצוה<sup data-n=\"1302\">44</sup>.",[["1295","37","ראה תוס' סד\"ה מ\"ד (מו\"ק כג, ב)."],["1296","38","נוסח ברכת העמידה דש\"ק."],["1297","39","רמב\"ם שבהערה 20."],["1298","40","באגה\"ת שם \"ודרך כלל סוד התענית היא סגולה נפלאה להתגלות רצון העליון ב\"ה כמו הקרבן שנאמר בו ריח ניחוח לה', וכמ\"ש בישעי' הלזה תקרא צום ויום רצון לה' מכלל דהצום הנרצה הוא יום רצון\", ומשמע (קצת) דהיום רצון נעשה ע\"י פעולת האדם — צום הנרצה. אבל י\"ל שזהו רק בתעניות של יחיד לתשובה וכפרה (המדובר ב­אגה\"ת שם), או תעניות שגוזרים על הצבור כדי לבטל גזירה וכיו\"ב, משא\"כ ד' הצומות שהימים עצמם נקבעו ע\"פ תורה, \"מפורשים בקבלה\", הם בעצם \"יום רצון לה'\"."],["1299","41","לקו\"ת שה\"ש סד\"ה הנך יפה (יד, ב). ועוד."],["1300","42","תהלים לג, יט."],["1301","43","ולהעיר שגם בפשטות, חיות הגוף בכלל היא מדצ\"ח, משא\"כ ביום התענית שהחיות דיום זה בא מחיות שכבר נתעלה לדרגת מדבר (ובבנ\"י — שאמיתית חיותו היא מנפשו האלקית — הרי היא חיות קדושה של הנשמה). ועיין לקו\"ת יוהכ\"פ ע, ב."],["1302","44","ראה גם תו\"א ר\"פ ח\"ש. סידור עם דא\"ח סדר סעודת שבת (רג, א ואילך). תו\"ח לך (צו, א­ג). שם ויקהל (תרלא, א ואילך). דרך מצותיך צ, א­ב. סה\"מ תרס\"ג ע' ס ואילך. המשך תרס\"ו (ע' קנד. שם ע' רמב). ובכ\"מ."]]],[1301430219,"ומזה מובן, ששלימות קיום מצות עונג שבת היא, כאשר כל תענוגו הוא מזה שהוא מקיים מצות הקב\"ה על ידי אכילה זו, והיינו, שאין העונג שלו עונג הגוף כ\"א רק עונג הנשמה.\n[אלא שגם מי שלא הגיע למדה זו, שלא ירגיש כלל עונג גשמי מאכילת שבת, ואדרבא הוא מתגשם ע\"י העונג שבהמאכל (\"וכמעשה<sup data-n=\"1303\">45</sup> הידוע אשר פעם הראה הבעש\"ט נ\"ע לתלמידיו שור מלו­בש בבגדי ש\"ק ויושב אצל השולחן. . אחד שאכל בשר שור לקיים מצות שבת ומפני תוקף רצונו לקיים את המצוה באכילת בשר בשבת נעשה עצמו כן\") — מ\"מ חייב לענג את השבת בבשר שמן ויין ישן<sup data-n=\"1304\">46</sup>].\nונמצא, שבשבת ניתן הכח להגיע ל­תוכן העבודה ד\"לחיותם ברעב\" (שחיותו תהי' חיות רוחנית של הנשמה, כנ\"ל), אף שבפועל הוא אוכל ושותה כו' — כי שלימות המצוה דעונג דשבת היא כאשר אין העונג מתענוג המאכלים כ\"א הוא עונג רוחני דהנשמה (ע\"י קיום מצות עונג שבת), וא\"כ ה\"ז דוגמת \"לחיותם ברעב\", שהרי לגבי הגוף ונפש הבהמית, אכילה זו הוא ענין של \"רעבון\" ועינוי<sup data-n=\"1305\">47</sup>, כי אינן אכילה ושתי' גשמיים השייכים לגוף ונה\"ב — אלא עונג הנשמה.\nועפ\"ז יתוסף ביאור בזה שביום ה­שבת שחל בו תענית ונדחה — נשאר ענין יום רצון (דהתענית), שהוא לא רק מחמת היום, שגם יום שבת זה הוא יום רצון לה', אלא גם מצד פעולת האדם, כי שלימות העבודה דאכו\"ש דיום השבת היא בדוגמת הענין ד\"לחיותם ברעב\".\nו. וזהו ביאור פלוגתת רבי ורבנן ע\"פ פנימיות הענינים — אי אמרינן הואיל ונדחה ידחה או לאו:\nלדעת רבי, הואיל ועיקרו של ה­תענית — יום רצון לה' — יכול להתקיים גם ביום השבת זה (ע\"י אכו\"ש בשבת באופן שכל העונג שבזה הוא עונג של מצוה), לכן, הואיל ונדחה החלק שאינו עיקרי כ\"כ בערך רצון לה' של התענית — עינוי הגוף — ידחה לגמרי, ובקביעות כזו אין צורך בזה כלל.\nויש לומר, שרבי לשיטתי' — שאמר<sup data-n=\"1306\">48</sup> שלא נהנה מעולם הזה כל ימיו אפילו באצבע קטנה, ועאכו\"כ שעונג שבת שלו הי' עונג רוחני של הנשמה, בלי תערובת של הנאת הגוף, ובמילא, העבודה רוח­נית של הצום מתקיימת גם ביום השבת.\nויש להוסיף, שס\"ל לרבי, דכאשר יום תענית חל ביום השבת, אזי נוסף על שיום השבת \"אהני\"<sup data-n=\"1307\">49</sup> ליום התענית, כיון שגם יום השבת הוא יום רצון לה', הרי גם \"אהני\" ב\"לחיותם ברעב\" דהתענית, ע\"י אכילה ושתי' דשבת, שגם מי שלא הגיע למדה זו שלא ירגיש כלל עונג",[["1303","45","סה\"מ תרח\"ץ ע' רז. וש\"נ."],["1304","46","שו\"ע אדה\"ז סרמ\"ב ס\"ב."],["1305","47","ראה בהנסמן בהערה 44 שהאכילה דשבת היא בדוגמת המן שהי' כולו לחם מן השמים שלא הי' בו פסולת כלל ולכן פרש שבתכם לא קאמר (זח\"ב פח, ב). ולהעיר ממ\"ש במן (עקב ח, ג) \"ויענך וירעיבך ויאכילך את המן\", שהמן פעל רעבון (כפי' המדרש — קה\"ר פ\"ה, יו\"ד. לקח טוב עה\"פ. וראה גם יומא עד, סע\"ב), ונת' במ\"א כי היות שלא הי' בו פסולת, והי' בבחי' פשיטות כו', לא הי' ביכולת האדם \"לתופסו\" ולכן גרם לרעבון — ראה בארוכה לקו\"ש ח\"ד ע' 1100 ואילך (וראה לקו\"ש ח\"ט ע' 16 ואילך). וש\"נ."],["1306","48","כתובות קד, א. וראה תניא פ\"ח."],["1307","49","ראה זבחים צא, א."]]],[1301430220,"גופני ממאכלי השבת — הנה בשבת זו (שחל בו תענית ונדחה) ניתן הכח שתהי' אצלו החיות והעונג דאכו\"ש בבחי' \"לחיותם ברעב\"<sup data-n=\"1308\">50</sup>.\nאבל חכמים לא הודו לו, כי כל עוד שלא בטלו עדיין הצומות הללו, צריכים לענין העינוי כפשוטו (ומה גם שהתורה על הרוב תדבר<sup data-n=\"1309\">51</sup>, ואי אפשר לדרוש (מהרוב) מכאו\"א שיגיע לדרגא זו, שלא ירגיש העונג הגשמי מאכו\"ש דשבת שהיא אכילת מצוה) — לכן ס\"ל, שאף שישנו ביום השבת זו העילוי ד\"יום רצון לה'\" (שמצד התענית), וכנ\"ל בארוכה, מ\"מ, יש צורך למעשה של תענית כ­פשוטה, ביום א', עדי יקויים היעוד ד­יהפכו ימים אלו לששון ולשמחה ול­מועדים טובים [ומ\"מ התענית דיום א' קלה יותר, כי אין בו עצם יום תענית].\nז. וע\"פ כל הנ\"ל יש לבאר דברי אדמו\"ר מהר\"ש דלעיל (ס\"א) — שהזכיר כמה פעמים שש\"ק זה נקרא \"נדחה\" כי התענית דשבעה עשר בתמוז נדחה ב­ש\"ק, וסיים \"הלואי שיהי' נדחה באמת\".\nובהקדם, דבדברי כ\"ק מו\"ח אדמו\"ר שם, לאחר שסיפר ע\"ד דברי אדמו\"ר מהר\"ש הנ\"ל, סיים (כנ\"ל) \"אַ ברכה פון אַ צדיק ווערט מקויים, הלואי עס זאָל טאַקע אַזוי זיין, און זאָל נדחה ווערן באמת ויהפך לששון ולשמחה\".\nולכאורה מהי ההוספה בדברי כ\"ק מו\"ח אדמו\"ר \"הלואי עס זאָל טאַקע אַזוי זיין און זאָל נדחה ווערן באמת\" על דברי אדמו\"ר מהר\"ש — הרי הן הן ה­דברים?\nגם — כ\"ק מו\"ח אדמו\"ר הוסיף על דברי אדמו\"ר מהר\"ש \"ויהפך לששון ולשמחה\", וגם שינה מלשונו, שאדמו\"ר מהר\"ש אמר \"הלואי ער זאָל נדחה ווערן באמת\", ואילו כ\"ק מו\"ח אדמו\"ר אמר \"הלואי עס זאָל טאַקע אַזוי זיין און זאָל נדחה ווערן באמת כו'\".\nגם צ\"ב דברי כ\"ק מו\"ח אדמו\"ר \"אַ ברכה פון אַ צדיק ווערט מקויים\" — דלכאורה, הרי זוהי נבואה מפורשת<sup data-n=\"1289\">31</sup> ופסק דין ברור בהלכה<sup data-n=\"1290\">32</sup>, שהצומות עתידין ליבטל ולהיות ימי ששון ושמחה, בלשון הרמב\"ם<sup data-n=\"1290\">32</sup> \"כל הצומות האלו עתידים ליבטל לימות המשיח ולא עוד אלא שהם עתידים להיות ימים טובים וימי ששון ושמחה שנאמר כה אמר ה' כו'\" (ופשיטא שאין לומר שהכוונה בה­שיחה שיבטל לפני הזמן דימות המשיח) — ומהו שמוסיף \"אַ ברכה פון אַ צדיק ווערט מקויים\"?\nוע\"פ משנת\"ל בגדר תענית שחל ב­שבת — יש לומר שדברי אדמו\"ר מהר\"ש ודברי כ\"ק מו\"ח אדמו\"ר מדברים בשני",[["1308","50","וי\"ל ש\"אהני\" דהתענית היא גם לצדיקים, כי אע\"פ שכל שבת היא בדוגמת \"לחיותם ברעב\" מ\"מ אינו דומה ממש לענין ד\"לחיותם ברעב\", ששם החיות אינה אלא חיות הנשמה, ואין בזה עירוב דאכילה ושתי' גשמיים כלל, משא\"כ באכילת שבת, אף שהוא עונג מאכו\"ש של מצוה, ולא עונג גשמי, מ\"מ גם בעת קיום המצוה מודגשת הגשמיות שבה שהוא התענוג שבבשר שמן ויין ישן, ולכן ה\"ז נותן מקום שהאדם יתגשם מצד העונג שבהמאכל, כנ\"ל (ראה תו\"ח לך שם: עכ\"ז הוא מגשם לגוף מצד התענוג הגשמי כו'. וראה תו\"א יתרו עד, א; לקו\"ת במדבר ז, סע\"א ואילך — שגם המאכל עצמו (לא מצד העונג שבו) מגשם קצת). משא\"כ כשחל תענית בשבת י\"ל שניתן כח שאכילתו תהי' מעין תענית.\nועפ\"ז יש לבאר מה שאמרו חז\"ל (תענית כט, ב. וש\"נ) ונפסק להלכה (שו\"ע או\"ח סתקנ\"ב ס\"י) דת\"ב שחל בשבת \"אוכל בשר ושותה יין בסעודה המפסקת ומעלה על שולחנו ואפילו כסעודת שלמה בעת מלכותו\", שלא מצינו לשון כזה בסתם שבת — כי בשבת ת\"ב יש בזה עילוי ומעלה (ולא רק היתר), כי אין בה חשש שיגשם כו' (משא\"כ בשאר שבתות)."],["1309","51","מו\"נ ח\"ג פל\"ד."],["1289","31","ח, יט."],["1290","32","סוף הל' תעניות. וראה טור או\"ח סו\"ס תקפ."],["1290","32","סוף הל' תעניות. וראה טור או\"ח סו\"ס תקפ."]]],[1301430221,"פרטים שונים בהענין, ודברי כ\"ק מו\"ח אדמו\"ר הם המשך (וסיום) לדברי אדמו\"ר מהר\"ש.\nביאור הדבר:\nאדמו\"ר מהר\"ש הזכיר כמ\"פ שש\"ק זה נקרא \"נדחה\" י\"ל כוונתו לדבר במעלת ש\"ק זה, שישנו קיום גדר התענית בעבו­דת האדם, וזהו שש\"ק זה נק' נדחה, דלהיותו כולו \"יום רצון לה'\", הרי \"ה­תענית די\"ז תמוז נדחה בש\"ק\", והיינו, שיש בכח בנ\"י לפעול ולגלות עילוי זה על ידי המצות ופעולות דש\"ק — אכילה ושתי' ועונג שבו; וע\"ז סיים \"הלואי ער זאָל נדחה ווערן באמת\", שיתקיים ב­עבודת כאו\"א שידחה באמת, שקיום ה­\"יום רצון לה'\" דיום השבת זה יהי' באמת, שיהי' נרגש אצל כאו\"א באמת בהתענוג דאכו\"ש דשבת שכולו הוא בבחי' \"לחיותם ברעב\".\nוע\"ז ממשיך כ\"ק מו\"ח אדמו\"ר \"אַ ברכה פון אַ צדיק ווערט מקויים\", והיינו הברכה על קיום גדר התענית בעבודת האדם ביום השבת תתקיים בפועל, \"הלואי עס זאָל טאַקע אַזוי זיין\" בעבו­דתו,\nואילו ההמשך \"און זאָל נדחה ווערן באמת\" — בזה מדובר בדחיית התענית עצמו בפשטות (לעת\"ל), שבאמת יהי' נד­חה, ומוסיף \"ויהפך לששון ולשמחה\" —\nוהן המה מעין וע\"ד שני השלבים (וה­תקופות) שיהיו בימות המשיח, ראשית מה ש\"כל הצומות האלו עתידים ליבטל\", היינו בלשון הרב \"זאָל נדחה ווערן באמת\", ושלב הב' \"ולא עוד אלא שהם עתידים להיות ימים טובים וימי ששון ושמחה\"<sup data-n=\"1313\">52</sup> — והוא סיום לשון כ\"ק מו\"ח אדמו\"ר \"ויהפך לששון ולשמחה\".\nויהי רצון, שבשנה זו יתקיים (בלשון הרב) שיהי' כן באמת, \"זאָל נדחה ווערן באמת ויהפך לששון ולשמחה\", ובמילא — בי\"ז בתמוז וכ\"ש בת\"ב כבר תתקיים הנבואה \"כה אמר ה' צבאות צום הרביעי וצום החמישי גו' יהי'. . לששון ול­שמחה ולמועדים טובים והאמת והשלום אהבו\".\n<span data-k=\"q\">(משיחות ש\"פ בלק (י\"ז בתמוז נדחה) תשל\"א, ש\"פ תצוה תשמ\"ז)</span>",[["1313","52","ראה בארוכה לקו\"ש חט\"ו ע' 413 ואילך בביאור דברי הרמב\"ם שם."]]],[1301430222,"<h3>שיחה א</h3>\nא. איתא בגמרא<sup data-n=\"1314\">1</sup>: \"הרואה פינחס ב­חלום פלא נעשה לו, הרואה פיל בחלום פלאות<sup data-n=\"1315\">2</sup> נעשו לו, פילים פלאי פלאות נעשו לו\". ובפרש\"י שם \"פלא נעשה לו, כמו שנעשה לפינחס כדאמרינן ב­סנהדרין\"<sup data-n=\"1316\">3</sup>.\nמפשטות הגמרא משמע, שהחילוק בין \"הרואה פינחס\" ל\"הרואה פיל\" הוא, ש­\"הרואה פיל\" עושים לו \"פלאות\" — רבות, ואילו \"הרואה פינחס\" עושים לו רק פלא אחד (\"פלא\" לשון יחיד).\nותמוה: בסנהדרין שם<sup data-n=\"1316\">3</sup> מפורש \"ששה נסים נעשו לו לפינחס\" (ובספרי<sup data-n=\"1318\">4</sup>, תיב\"ע<sup data-n=\"1318\">4</sup> ועוד איתא שי\"ב נסים נעשו לו, ובפרש\"י עה\"ת<sup data-n=\"1318\">4</sup> \"והרבה נסים נעשו לו\"), ומדוע \"הרואה פינחס בחלום (רק) פלא (אחד) נעשה לו\" — הרי אין זה \"כמו שנעשה לפינחס\"?\nויש להוסיף ולהעיר, שלולא פרש\"י הי' אפשר לבאר טעם החילוק, שהוא ע\"ד מה שנאמר בגמ' בהמשך לזה<sup data-n=\"1321\">5</sup>, \"ה­רואה הונא בחלום נס נעשה לו, חנינא חנניא יוחנן נסי נסים נעשו לו\", ובפרש\"י שם \"נס נעשה לו, נו\"ן כנגד נו\"ן כו'\", \"חנינא, נוני\"ן הרבה, נסים הרבה\". ומעין זה הי' אפשר לומר בעניננו, שה\"פ\"א\" דפינחס הוא כנגד \"פלא\"<sup data-n=\"1322\">6</sup>, והיות שב­\"פיל\" יש (נוסף על הפ\"א) גם אות למ\"ד ד\"פלא\"<sup data-n=\"1322\">6</sup> ה\"ז מוסיף בהענין — ויש \"פלאות\" [וכמו ש\"פילים\" לשון רבים — מוסיף על \"פלאות\" — \"פלאי פלאות\", היינו נוסף על הריבוי בכמות, גם ריבוי באיכות].\nאבל רש\"י שולל התחלת פירוש זה, באמרו שהטעם ש\"הרואה פינחס בחלום פלא נעשה לו\" הוא (לא מפני שאות פ\"א שבתיבת \"פינחס\" מורה על \"פלא\", אלא) לפי שזהו \"כמו שנעשה לפינחס\".\n[ויש לומר, שטעמו של רש\"י לחלק בין \"הרואה הונא כו'\" ל\"הרואה פינחס כו'\" הוא ע\"פ המשך דברי הגמ' שם ש­\"הרואה הונא כו'\" פירושו שראה שם זה \"בכתבא\" (שראה תיבת הונא או חנינא — כתובה. רש\"י), ולכן מסתבר שהרמז קשור עם האותיות שראה בחלומו<sup data-n=\"1324\">7</sup>; משא\"כ \"הרואה פינחס כו' פיל כו'\" אין פירושו שראה תיבה זו כתובה, אלא ראה דמותו של פינחס<sup data-n=\"1325\">8</sup> או פיל (כדמוכח",[["1314","1","ברכות נו, סע\"ב."],["1315","2","בברכות נז, ב \"פיל. . פלא נעשה לו\". אבל בנוסח הכ\"י בדק\"ס שם — \"פלאות\" (כלפנ\"ז בגמ' שם)."],["1316","3","פב, ב."],["1316","3","פב, ב."],["1318","4","ס\"פ בלק. — ובראב\"ע שם \"שנעשו עשרה נסים לפינחס\". וצ\"ע מקורו."],["1318","4","ס\"פ בלק. — ובראב\"ע שם \"שנעשו עשרה נסים לפינחס\". וצ\"ע מקורו."],["1318","4","ס\"פ בלק. — ובראב\"ע שם \"שנעשו עשרה נסים לפינחס\". וצ\"ע מקורו."],["1321","5","שם נז, רע\"א."],["1322","6","ולהעיר, דאות נו\"ן (שבפינחס) מתחלפת בלמ\"ד (שהן ממוצא א' — דטלנ\"ת שבלשון. ראה נחמי' ג, ל ומצו\"ד שם. רש\"י קדושים יט, טז. ועוד)."],["1322","6","ולהעיר, דאות נו\"ן (שבפינחס) מתחלפת בלמ\"ד (שהן ממוצא א' — דטלנ\"ת שבלשון. ראה נחמי' ג, ל ומצו\"ד שם. רש\"י קדושים יט, טז. ועוד)."],["1324","7","ועפ\"ז מובן הטעם שרש\"י שם (ד\"ה נס) מוסיף \"וכגון שראה השם כתוב\" (ולא סמך על המפורש בש\"ס תיכף לאח\"ז. וראה סמיכת חכמים על פרש\"י) — כי זהו היסוד לקשר אות נו\"ן שב­(אמצע) תיבת \"הונא\" לענין הנס."],["1325","8","ראה גם דק\"ס לברכות שם (בהגהות), אלא שמקשה ע\"ז דא\"כ הול\"ל \"ודוקא פינחס בן אלעזר\" כדאמר (בגמ' שם לפנ\"ז) גבי ישמעאל (\"ודוקא ישמעאל בן אברהם\")."]]],[1301430223,"מגמ' שם<sup data-n=\"1326\">9</sup> שיש חילוק אם ראה פיל \"דמסרג\" (שיש לו אוכף על גביו. רש\"י) או \"דלא מסרג\"), וכיון שראה פינחס ב­חלומו, מסתבר שזה קשור עם הקורות<sup data-n=\"1327\">10</sup> את פינחס עצמו].\nוהדרא קושיא לדוכתא — שהרבה נסים נעשו לו.\nב. ויובן זה בהקדם עוד דיוק, שלכ­אורה, ע\"פ פרש\"י שזה ש\"פלא נעשה לו\" הוא \"כמו שנעשה לפינחס\" — מדוע אומרים \"פלא נעשה לו\" (פלא דייקא), והרי בסנהדרין שם הלשון \"ששה נסים נעשו לו\", והול\"ל \"נס נעשה לו\"?\nוגם את\"ל שפתרון החלום שייך גם לשם \"פינחס\" — הרי בשם \"פינחס\" יש שתי (כל) האותיות \"נס\" (שלכאורה הרי זו שייכות יותר גלוי', מהשייכות דאות פ\"א לתיבת \"פלא\").\nוהנה לפעמים מבואר<sup data-n=\"1328\">11</sup> החילוק בין שתי הלשונות \"נס\" או \"פלא\", ש\"נס\" הוא דבר גבוה כבכתוב שלפני פרשתנו<sup data-n=\"1329\">12</sup> — היינו מאורע שיוצא וגבוה מדרכי הטבע, ואילו \"פלא\" הוא כל דבר המעורר פלי­אה אצל האדם<sup data-n=\"1330\">13</sup>, גם אם אין בו שידוד מערכות הטבע, כלומר גם כשהנס מ­לובש בטבע.\nועפ\"ז הי' אפשר לבאר, לכאורה, דיוק הלשון \"פלא נעשה לו\" — כי רוב הנסים שנפרטו בש\"ס שם אינם דברים היוצאים מדרכי הטבע, \"הי' לו לזמרי לפרוש ולא פירש. . הי' לו לדבר ולא דבר וכו'\".\nאבל דוחק לתרץ כן, כי שני הנסים האחרונים שנמנו בגמ' שם — \"שבא מלאך והגבי' את המשקוף. . שבא מלאך והשחית בעם\" — אינם מלובשים בטבע כלל [ולמדרשים הנ\"ל שי\"ב נסים נעשו לו — הרי רוב הנסים שנפרטו שם הם דברים שלמעלה מן הטבע באופן גלוי].\nג. ולכן נ\"ל להיפך, שכאן הכוונה ב\"פלא נעשה לו\" היא, ל\"פלא\" שלמעלה מ\"נס\", ע\"ד לשון הכתוב<sup data-n=\"1331\">14</sup> \"כימי צאתך מארץ מצרים אראנו נפלאות\", שהכוונה בזה<sup data-n=\"1332\">15</sup>, שבגאולה העתידה לבא יהיו נסים גדולים, שאפילו בערך להנסים שאירעו לאבותינו ביציאת מצרים (שלא היו מלובשים בטבע), יהיו בגדר \"נפלאות\".\nוזוהי גם כוונת רש\"י במ\"ש \"כמו ש­",[["1326","9","וכן מוכח מהא דרק ב\"רואה הונא כו'\" אמרו \"והני מילי בכתבא\" (ראה רש\"י שם), ומשמע שהדברים שנמנו לפנ\"ז אינם \"בכתבא\" אלא הדבר עצמו. ועכצ\"ל כן בכו\"כ דברים שם. וראה סמיכת חכמים לברכות שם ד\"ה יצפה."],["1327","10","משא\"כ בנוגע ל\"פיל\", כיון שכללות השם (שהוא חיותו של הפיל — ראה תניא ח\"ב פ\"א) קרובה לתיבת \"פלא\" (דלא כשם פינחס, שהשייכות (הגלוי') היא רק באות אחת), מובן, שיש שייכות ביניהם<sup data-n=\"e31\">*</sup>. וראה הגהות מלא הרועים לברכות שם (ד\"ה הרואה קנה).\nועוד י\"ל, שפיל בפשטות הוא בעל חי \"מופלא\" — ראה רש\"י ברכות (נז, ב ד\"ה חוץ) \"שמשונין במראיהן\". ועוד, שפיל הוא מהבע\"ח הגדולים בגשמיות (וראה ברכות שם (נה, סע\"ב) \"ולא פילא דעייל בקופא דמחטא\"). ולהעיר מגליוני הש\"ס (להר\"י ענגל) שם בנוגע ל\"גמל\". ביאוה\"ז (ל­אדמו\"ר האמצעי) וישב כד, ג."],["1328","11","ראה לקו\"ש חט\"ו ע' 367 ואילך."],["1329","12","חוקת כא, ח."],["1330","13","ולהעיר מרמב\"ם סוף הל' טומאת צרעת \"אות ופלא הי' בישראל\"."],["1331","14","מיכה ז, טו. וראה תשא לד, י. ועוד."],["1332","15","ראה אוה\"ת למיכה עה\"פ (ע' תפו­ז). וראה לקו\"ש שם הערה 16. וש\"נ."],["e31","*","ולהעיר מגמ' שם (נו, ב) לפנ\"ז ד\"רואה חתול בחלום, באתרא דקרו לי' שונרא נעשית לו שירה נאה, שינרא נעשה לו שינוי רע\"."]]],[1301430224,"נעשה לפינחס כדאמרינן בסנהדרין\", ש­מגמ' סנהדרין שם מוכח, שעיקר החידוש אצל פינחס, אינו כמות הנסים שנעשו לו, אלא זה ש\"פלא שנעשה לו\", היינו לא רק ניסים רבים בכמות, אלא איכות בל­תי טבעית — הנהגה באופן של \"מופלא\". שהרי ששת הנסים שנמנו בסנהדרין שם, היו כולם באותו ענין, היינו שבכל פרט ופרט שבמעשה שלו עשה הקב\"ה נס, ובזה נראה בעליל שכל הנהגת הקב\"ה עם פינחס היתה באופן בלתי רגיל לגמרי, מלכתחילה הנהגה של \"פלא\", וריבוי הנסים אינו עיקר החידוש כלל כ\"א שכל ההנהגה עם פינחס היתה ב­דרך \"פלא\".\nליתר ביאור:\nענין של \"נס\" הוא שידוד מערכות הטבע, שמזה גופא מובן, שיש נתינת מקום להנהגת הטבע, אלא שפועל בה שידוד וביטול, ולכן, בכל פעם שיש נס צ\"ל פעולה חדשה עוד הפעם של ביטול הטבע; משא\"כ פלא — ד\"כל הפלאה לשון הבדלה ופרישה\"<sup data-n=\"1333\">16</sup> — מורה על הנהגה שמובדלת לגמרי מהנהגת הטבע, עד שאינו בגדר הטבע, ובמילא אין כאן בכל פעם פעולה מיוחדת של שידוד הטבע, אלא נקבעה הנהגה נסית שהיא תהי' ההנהגה הרגילה בכל מאורע זה.\nוזה מ\"ש רש\"י \"פלא נעשה לו, כמו שנעשה לפינחס\" — \"פלא\" לשון יחיד דוקא: זה שנסים רבים נעשו לפינחס, היתה הנהגה (כללית) אחת, בדרך \"פלא\", מובדל לגמרי מגדר הטבע (אלא שבדרך ממילא נסתעף מזה שהיו נסים בכל פרט ופרט כו'), ולכן אין הם \"פלאות\" (או \"נסים\") לשון רבים, כי הכוונה היא למצב, הנהגה (לשון יחיד) פלאית.\n[ועפ\"ז אולי יש לומר, שה\"פלא\" שנעשה ל\"הרואה פינחס בחלום\" הוא למעלה מה\"פלאות\" (לשון רבים) אצל \"הרואה פיל\", דמזה שאומר \"פלאות\", לשון רבים, מובן, שהכוונה לריבוי פלאות בכמות, והיינו פעולות של נפלאות, משא\"כ \"פלא נעשה לו\" (\"כמו שנעשה לפינחס\") היינו לא עשיית פלא אחד, אלא מצב של \"פלא\", כנ\"ל<sup data-n=\"1334\">17</sup>].\nד. והנה ע\"פ פרש\"י הנ\"ל, ש\"הרואה פינחס בחלום פלא נעשה לו — כמו ש­נעשה לפינחס\", מובן, שענין ה\"פלא\" הוא ענינו העיקרי של פינחס; דאם נאמר שזהו רק ענין טפל וצדדי בו, לא שייך לומר, שמשום שביום ההוא נעשה פלא לפינחס — משא\"כ כל השנים שלפני זה ושלאחרי זה — לכן כל \"הרואה פינחס בחלום פלא נעשה לו\". אלא עכצ\"ל ש­ענין ה\"פלא\" הוא ענינו של פינחס.\nוהיינו, שהטעם לזה שהקב\"ה התנהג עם פינחס באופן של \"פלא\", הוא משום שהנהגתו ועבודתו של פינחס עצמו היתה (לא עבודה רגילה, אלא) באופן של \"פלא\", ומדתו של הקב\"ה מדה כנגד מדה — ולכן הנהגת הקב\"ה עמו היתה באופן כזה, \"פלא נעשה לו\".\nביאור הענין:\nענינו של \"נס\" בעבודת האדם הוא — מסירת נפש<sup data-n=\"1335\">18</sup>, דכמו שנס כפשוטו מורה על גדלותו של הקב\"ה, שאין דבר המונע מילוי רצונו ית', ואם מצב הטבע מנגד לרצונו הרי הקב\"ה משנה הטבע — עד\"ז",[["1333","16","רש\"י שופטים יז, ח. וראה רש\"י וירא יח, יד. תשא שם. ועוד."],["1334","17","ועד\"ז י\"ל בנוגע ל\"פלאי פלאות\" (בהמשך הגמ'), שהכוונה לגדר ריבוי (אלא — לא בכמות כ\"א באיכות). משא\"כ \"פלא\" ל' יחיד הוא למעלה מגדר ריבוי, כנ\"ל בפנים."],["1335","18","ראה (בסגנון אחר) לקו\"ש חי\"ז ע' 151 ואילך. ועוד."]]],[1301430225,"הוא ענין עבודה מתוך מסירת נפש, שזה מורה על תוקף רצונו של האדם לעשות רצונו ית', באופן שאין דבר שיכול למ­נוע אותו מלקיים רצונו ית', ומוסר נפשו ע\"ז.\nובזה גופא יש שני אופנים הנ\"ל — \"נס\" ו\"פלא\":\nיש אדם שעיקר עבודתו היא ע\"פ טעם ודעת, בלימוד התורה, קיום ה­מצוות, וכיו\"ב, אלא שאם נצרך באיזה פרט יוצא מהרגיל, מסירת נפש, הרי הוא מתייגע ומעורר בעצמו הנהגה חד­שה, תוקף גדול עד כדי מסירת נפש. ומובן, שאז המסירת נפש בכל פעם היא עבודה חדשה, וצ\"ל התעוררות חדשה ע\"ז;\nאבל יש אדם שהוא איש מסירת נפש, שהוא מסור ונתון לגמרי לרצונו ית' ואין לו רצון בפ\"ע כלל, ענינו הוא מסירת נפש להקב\"ה, ואזי בדרך ממילא יש לו מסירת נפש בכל ענין ופרט הקשור לעבודתו ית' — ע\"ד הנ\"ל בענין של \"פלא\", שזהו מצב של הנהגה נסית באופן שהנהגה זו היא ההנהגה הרגילה (הטבעית) שלו.\nוזוהי דרגתו של פינחס, \"בקנאו את קנאתי\"<sup data-n=\"1336\">19</sup>, שסיכן עצמו בענין שאין בזה חיוב (ואדרבה, אם הי' שואל — אין מורין כן<sup data-n=\"1337\">20</sup>), אלא שקנאין פוגעין בו<sup data-n=\"1338\">21</sup>, שזהו רשות והיתר לקנאי לפגוע בו; ובפרט לפי דברי הירושלמי<sup data-n=\"1339\">22</sup> שקנאות זו היא \"שלא ברצון חכמים\". ועוד זאת בנדו\"ד — שמשה רבינו לא עשה כלום (והרי פינחס לא הי' יודע שנתעלמה ממנו הלכה<sup data-n=\"1340\">23</sup>) — אבל פינחס לא נכנס ל­שקו\"ט בעצמו כ\"א קינא קנאת ה' צבאות.\nמסירת נפשו של פינחס היתה למעלה מחשבון ומדידה, משום שהי' איש מסירת נפש בעצם, וכיון שהי' ענין של קידוש השם<sup data-n=\"1341\">24</sup> — קינא קנאת ה' צבאות.\nומדה כנגד מדה — שפלא נעשה לו<sup data-n=\"1342\">25</sup>.\nה. עפ\"ז יבואר גם הטעם ששכרו של פינחס הי' — \"והיתה לו ולזרעו אחריו ברית כהונת עולם\"<sup data-n=\"1343\">26</sup>, שלפי פשוטו של מקרא<sup data-n=\"1344\">27</sup>, הפירוש בזה, שרק אז נתכהן פינחס, \"תחת אשר קנא לאלקיו\"<sup data-n=\"1343\">26</sup>.\nדיש לומר, שגם אופנו של שכר זה הוא בהתאם לענין הנ\"ל, שמהותו של פינחס היא — שהי' איש \"פלא\" בעצם.\nדהנה כהונה היא דבר הבא בירושה, כי אינה אלא לזרע אהרן; ואילו כאן ניתנה כהונה לפינחס \"תחת אשר קנא לאלקיו\"<sup data-n=\"1346\">28</sup>.\nאלא שזהו מדה כנגד מדה, דכשם",[["1336","19","פרשתנו כה, יא."],["1337","20","סנהדרין פב, א. רמב\"ם הל' איסו\"ב פי\"ב ה\"ה. טור אה\"ע סט\"ז. רמ\"א חו\"מ סתכ\"ה ס\"ד."],["1338","21","משנה שם פא, ב. מקומות שבהערה הקודמת. רש\"י בלק כה, ז."],["1339","22","סנהדרין שם (פ\"ט ה\"ז), וכפירוש היפה מראה שם. וראה לקו\"ש חי\"ח ע' 319 ואילך ובהערה 24. וש\"נ."],["1340","23","סנהדרין שם פב, א. רש\"י בלק שם, ו."],["1341","24","ראה סנהדרין שם (בסוף העמוד)."],["1342","25","עפ\"ז יש לבאר גם הטעם שנעשה לו נס ש\"לא הטיפו דם כדי שלא יטמא פינחס\" (תנחומא ס\"פ בלק — משא\"כ בתיב\"ע שם \"דלא יסתאב כהנא\") — אף ש(לכמה דיעות) פינחס לא הי' כהן עדיין (נסמן בהערה 27), ומהו ההכרח שלא יטמא? — אלא שזהו בהתאם להמס\"נ דפינחס, שלא הי' בזה חיוב, ולכן נעשה לו נס בענין שלא הי' מוכרח אלא להראות הגבהה, חיבה יתירה (ע\"ד המבואר ב­מפרשים לענין נס שמן דחנוכה)."],["1343","26","פרשתנו כה, יג."],["1344","27","רש\"י שם. וכהדיעה בגמ' זבחים (קא, ב)."],["1343","26","פרשתנו כה, יג."],["1346","28","ראה גם לקו\"ש ח\"ד ע' 1070 ואילך. חי\"ח ע' 320. ועוד."]]],[1301430226,"שפינחס קנא לאלקיו, אף שלא הי' מצווה ע\"ז (ועד שזהו \"שלא ברצון חכמים\", שע\"פ חכמת התורה יש מקום לשקו\"ט אודות קנאות זו), כך ניתן לו דבר — כהונה — שע\"פ חכמת התורה אינו דבר הניתן בתור שכר.\nוע\"פ הנ\"ל יש לבאר הטעם שהשכר הי' דוקא בענין של כהונה, שזהו ענין של ירושה וטבע — כי גם זה הוא כמו \"פלא\" (שלמעלה מנס), והיינו, שנוסף לזה שנעשה לו דבר שלא ע\"פ חכמת התורה (שאי אפשר להגיע לכהונה על ידי עבודה), הרי עוד זאת, ששכר זה גופא (שלמעלה מחכמה) נעשה אצלו ענין שבטבע, עד שבא בירושה \"לזרעו אחריו\" — שזהו גדר של \"פלא\", שענין הנס נעשה הטבע שלו, כנ\"ל באורך.\nו. והנה גאולת כ\"ק מו\"ח אדמו\"ר (ביום י\"ב תמוז תרפ\"ז) ממאסרו אשר נאסר במדינה ההיא היתה בשבוע דשבת פ' פינחס<sup data-n=\"1347\">29</sup>, ועוד זאת, שבשבת פ' פינחס בירך ברכת הגומל<sup data-n=\"1348\">30</sup>. ואם כל עניני ה­עולם הם בהשגחה פרטית (כתורת ה­בעש\"ט), כ\"ש וק\"ו עניני איש ישראל, ועאכו\"כ של נשיא ישראל — ומזה מובן, שגאולת כ\"ק מו\"ח אדמו\"ר שייכת לתוכן ענינו של פינחס<sup data-n=\"1349\">31</sup>.\nואכן ראינו אצל בעל הגאולה — כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1350\">32</sup>, שמסירת נפשו במדינה ההיא היתה ע\"ד מסירת נפש דפינחס באופן של \"בקנאו את קנאתי\", היינו לא מסירת נפש שמחוייבים בה ע\"פ דין תורה, וכמה חכמי ישראל סברו שאין מחוייבים במסירת נפש באופן כזה — והוא מסר נפשו ע\"ז.\nוהיינו משום שאצל כ\"ק מו\"ח אדמו\"ר היתה מסירת נפש לא פרט בעבודתו הק' אלא שכל מהותו היתה מסירת נפש, עד שכל ענין בעבודה זו הי' חדור במסירת נפש.\nוכמשנ\"ת במ\"א בארוכה<sup data-n=\"1351\">33</sup>, ע\"ד ג' התקופות הכלליות בשלשים שנות נשי­אותו של כ\"ק מו\"ח אדמו\"ר — תקופה ראשונה בעת היותו במדינה ההיא, תקו­פה השני' בהיותו בלעטלאַנד ופולין, ו­תקופה השלישית בארצות הברית — ש­עבודת הק' שלו בכל אחת מהן דרשה תוקף ומסירת נפש, ובכל אחת מהן — בצורה אחרת:\nבמדינה ההיא הי' זה קשור במסירת נפש כפשוטו בגשמיות, עבודה הקשורה בסיכון חיי הגוף, ולא רק של עצמו, אלא גם של שלוחיו וחסידיו, שע\"פ הוראותיו או גם בשליחותו ממש עסקו בהרבצת התורה וחיזוק היהדות במדינה ההיא, והעמידו חייהם בסכנת נפשות ממש;\nבתקופה השני' היתה עבודתו בין אחבנ\"י, שומרי תומ\"צ — ושם הקים כ\"ק מו\"ח אדמו\"ר מחדש ישיבות, ועסק בהפצת התורה בכלל ובהפצת המעינות ותורת חסידות חב\"ד בין כל החוגים;\nובתקופה השלישית, בהגיעו לארצות הברית, ששם הי' צריך לשנות דעם אָפּ­לייג (הנחת) המדינה שבארצות הברית",[["1347","29","וכן הברי\"מ שלו (י\"ט תמוז תר\"ם) היתה בשבוע דפ' פינחס. וראה לקו\"ש חי\"ח שם ע' 318 הערה 3."],["1348","30","ראה סה\"מ קונטרסים ח\"א קעה, א. ובכ\"מ."],["1349","31","ולהעיר שפינחס בגימט' יצחק (זהר פרשת­נו רלו, ב) — שם השני דבעל הגאולה, ופינחס מזרעי' דיוסף (רש\"י וארא ו, כה. סוטה מג, א) — שם הראשון דבעל הגאולה."],["1350","32","ראה בארוכה בכ\"ז לקו\"ש חי\"ח שם ע' 321 ואילך. ועוד."],["1351","33","לקו\"ש חי\"ח ע' 303 ואילך. ע\"ש בפרטיות."]]],[1301430227,"איז אַנדערש, ואי אפשר אידישקייט ממש ווי אין \"דער אַלטער שטעטל\" — שהתעסקות זו היתה אפשרית רק על ידי תוקף ומסירת נפש נגד כל הזרמים.\nשכל אחד משלשת אופנים אלו ב­מסירת נפש, הוא מסוג שונה זמ\"ז — וכ\"ק מו\"ח אדמו\"ר קפץ בנחשול של כאו\"א בחיות ומסירת נפש, בלי הגבלה כלל.\nוזהו איש מסירת נפש בעצם מהותו, ולכן כל דבר ודבר בזה נעשה מתוך מסירת נפש [ע\"ד הנ\"ל ס\"ג בענין \"פלא\"].\nוזוהי גם ההוראה למעשה — שע\"י ש­\"נלך בדרך. . אשר הורנו. . ונלכה ב­אורחותיו\"<sup data-n=\"1352\">34</sup> לעסוק בחיזוק הדת ו­הרבצת התורה, במסירת נפש — ובפרט שעתה הוא לא מתוך מצוקה גשמית ח\"ו אלא מתוך הרחבה, מסירה ונתינה לעבודה למעלה ממדידה והגבלה, מבלי להתחשב עם מונע ומעכב כו' — זוכים ש\"פלא נעשה לו\", שהקב\"ה מצליח את העבודה בדרך \"פלא\",\nוכ\"ז ממהר ומביא במהרה בימינו ממש קיום היעוד<sup data-n=\"1353\">35</sup> \"כימי צאתך מארץ מצרים אראנו נפלאות\".\n<span data-k=\"q\">(משיחת ש\"פ פינחס תשכ\"ו)</span>",[["1352","34","ל' אדה\"ז תניא אגה\"ק סי' זך."],["1353","35","מיכה ז, טו."]]],[1301430228,"<h3>שיחה ב</h3>\nא. עה\"פ<sup data-n=\"1354\">1</sup> \"ובני קרח לא מתו\" פרש\"י \"הם היו בעצה תחלה ובשעת המחלוקת הרהרו תשובה בלבם לפיכך נתבצר<sup data-n=\"1355\">2</sup> להם מקום גבוה בגיהנם וישבו שם\".\nוכתבו המפרשים<sup data-n=\"1356\">3</sup>, שכוונת רש\"י היא ליישב סתירה בפשטות הכתובים, דאיך אפ\"ל ש\"בני קרח לא מתו\", והרי מפורש לעיל בפ' קרח<sup data-n=\"1357\">4</sup> \"ותבלע גו' ואת כל האדם אשר לקרח\" (שבפשטות נכללים והעיקר בזה בני קרח<sup data-n=\"1358\">5</sup>)? ולכן מפרש רש\"י, שאכן נבלעו באדמה, אבל לא מתו, כי \"נתבצר להם מקום גבוה בגיהנם וישבו שם\", והטעם ש\"לא מתו\" — כי \"בשעת המחלוקת הרהרו תשובה בלבם\".\nאבל עדיין צריך ביאור אריכות לשון רש\"י — \"הם היו בעצה תחלה ובשעת המחלוקת הרהרו תשובה בלבם\" — דלכ­אורה הי' מספיק לומר בקיצור: \"לפי שעשו תשובה לפיכך נתבצר כו'\", וע\"ד לשון רש\"י לעיל בפ' קרח<sup data-n=\"1359\">6</sup> (כשמפרש טעמו של קרח שהכניס עצמו לחלוק על משה, משום ש\"ראה שלשלת גדולה יוצאה ממנו שמואל ששקול כנגד משה ואהרן כו' וכ\"ד משמרות עומדות לבני בניו כו'\", שרש\"י מסיים) \"ולא ראה יפה לפי שבניו עשו תשובה\".\nבפשטות יש לומר, שכוונתו בזה לבאר מדוע נענשו בני קרח כל עיקר (להיות בין הבלועים באדמה) — והרי עשו תשובה<sup data-n=\"1360\">7</sup>? ולכן כותב ש\"הם היו בעצה תחלה\", ועוד זאת, שתשובתם לא היתה תשובה גמורה<sup data-n=\"1361\">8</sup>, כי רק \"הרהרו תשובה בלבם\" — ולכן הגיע להם עונש זה (שנבלעו באדמה), אלא שכיון שעכ\"פ הרהרו תשובה, לכן \"לא מתו\" אלא \"נתבצר להם מקום גבוה בגיהנם וישבו שם\".\nאבל עדיין אין זה מבאר דיוק הלשונות בפירוש רש\"י:\nא) ממ\"ש \"הם היו בעצה תחלה\" (ולא \"הם היו במחלוקת\" וכיו\"ב), משמע, שלא רק שהצטרפו למחלוקת שפרצה, אלא הם היו מהיועצים שעל פי עצתם התחילה<sup data-n=\"1362\">9</sup> מחלוקת קרח.\nואינו מובן:\n(1) ההכרח ע\"פ פשט שבתחילה היו בני קרח בין החולקים על משה — ול­העיר אשר תרגום יונתן ותרגום ירו­",[["1354","1","פרשתנו כו, יא."],["1355","2","מגילה יד, א. סנהדרין קי, סע\"א. תנחומא קרח יא. במדב\"ר שם (פי\"ח, כ). — וראה הערה 18."],["1356","3","שפ\"ח. משכיל לדוד. וראה גם חדא\"ג מהרש\"א סנהדרין שם. — ובגו\"א (ועוד) שרש\"י מתרץ מדוע נאמר \"לא מתו\" ולא נאמר ובקיצור \"חיו\" (ע\"ד שלח יד, לח)."],["1357","4","טז, לב."],["1358","5","ברמב\"ן שם, ש\"כל האדם\" היינו עבדיו ושפחותיו (ולא בניו). ובספורנו שם פי' שהם \"ה­נמשכים אחריו במחלוקתו\". — אבל מסתימת רש\"י שם מובן, שלדעתו \"כל האדם אשר לקרח\" פירושו כפשוטו, שכל השייכים אליו בכלל."],["1359","6","טז, ז."],["1360","7","וראה משמרת הקדש, באר יצחק ועוד כאן. — וצע\"ק, שלכאורה קושיא זו מתעוררת כבר לעיל בפ' קרח, כיון שפרש\"י שם שבני קרח עשו תשובה, והו\"ל לרש\"י לתרץ שם מדוע נבלעו."],["1361","8","ראה עד\"ז גו\"א כאן."],["1362","9","ע\"ד \"בעצה תחלה\" שבפרש\"י וארא (ז, כח)."]]],[1301430229,"שלמי<sup data-n=\"1363\">10</sup> פירשו שלא היו בעצת קרח — מובן, כי הלא מפורש בכתוב, כנ\"ל, שכל האדם אשר לקרח נבלעו בהאדמה, ומס­תבר שזהו בגלל השתתפותם בהמח­לוקת<sup data-n=\"1364\">11</sup>; אבל מנ\"ל לרש\"י ש\"הם היו בעצה תחלה\"?\n(2) גם אם נמצא הכרח לזה בפשוטו של מקרא<sup data-n=\"1365\">12</sup> — למאי נפק\"מ כאן להדגיש גודל חטאם, ש(לא רק שנשתתפו במח­לוקת קרח ועדתו, אלא) היו \"בעצה תח­לה\" [והרי גם בלי זה ראויים לעונש כיון שלא עשו תשובה גמורה]?\nב) \"בשעת המחלוקת הרהרו תשובה בלבם\" — מהו הדיוק שהרהרו תשובה בעת המחלוקת עצמה, ולא לאחרי' כ­תוצאה מדברי משה? ולכאורה מסתבר יותר שתשובתם היתה לאחר שאמר משה<sup data-n=\"1366\">13</sup> \"בזאת תדעון כי ה' שלחני גו' אם כמות כל האדם גו'\"<sup data-n=\"1367\">14</sup>, ולכן לא הועילה אז תשובתם לבטל עונשם לגמרי, ולכן נבלעו.\nג) \"הרהרו תשובה בלבם\" — דלכ­אורה אין בלשון זו הדגשה שתשובתם לא היתה תשובה גמורה<sup data-n=\"1368\">15</sup>, אלא שהיתה רק הרהור בלב, ולא וידוי בפה כו'<sup data-n=\"1369\">16</sup>.\nב. ויש לומר, שכוונת רש\"י היא, ל­באר הטעם שנענשו ולאחר זה ניצלו וב­אופן משונה (ונסי) שלא מצינו דוגמתו בכל התורה כולה — נבלעו ביחד עם (קרח<sup data-n=\"1370\">17</sup> ו)דתן ואבירם ומשפחותיהם, ו­לאידך, שם גופא \"נתבצר להם מקום גבוה (בגיהנם) וישבו שם\" (ובפרט שיש מקום לומר שב\"וישבו שם\"<sup data-n=\"1371\">18</sup> מתכוון רש\"י לישיבה בשלוה<sup data-n=\"1372\">19</sup>, ע\"ד פירוש",[["1363","10","פרשתנו כאן.\nבקיצור מזרחי (ועד\"ז במלאכת הקודש על פרש\"י) פי' ברש\"י שהיו מבני בניו של קרח שהיו גדולים ולא נכנסו עמהם במחלוקת כל עיקר (וזוהי משפחת הקרחי שממנה יצא שמואל כו'). וצ\"ע שהרי זה היפך פרש\"י קרח הנ\"ל, דזה שיצא ממנו שמואל כו' הוא לפי שבני קרח עשו תשובה.\n[אלא שלדעתו תלוי בב' הדעות אם בני קרח יצאו מן האדמה או ששוב לא עלו (ראה לקמן ס\"ג ובהנסמן שם), וראה שם שמפרש, שפרש\"י בתהלים (מב, א) הוא להדיעה שיצאו משם ופרש\"י פרשתנו הוא כהדיעה שלא יצאו משם, וא\"כ אפ\"ל שס\"ל שפרש\"י קרח הנ\"ל הוא להדיעה שיצאו משם<sup data-n=\"e32\">*</sup>]."],["1364","11","להעיר שגם טפם של דתן ואבירם נאבדו (רש\"י קרח טז, כז)."],["1365","12","וי\"ל ע\"פ פרש\"י קרח (שהובא לעיל בפנים) שסיבת מחלוקת קרח היתה ש\"ראה שלשלת גדולה יוצאה ממנו\", וא\"כ מסתבר שגם בניו היו בעצה זו."],["1366","13","קרח טז, כח ואילך."],["1367","14","וצ\"ע במשכיל לדוד כאן, שכ' \"שנבלעו אלא דבאותה שעה הרהרו כו'\" (וכ\"ה במדרש תהלים מה, ב) — שהרי ברש\"י מפורש \"בשעת המחלוקת כו'\"."],["1368","15","שהרי תתכן תשובה גמורה בלב. ולהעיר מקידושין (מט, ב) הרהר תשובה כו' צדיק גמור (כגירסת האור זרוע סקי\"ב. וכ\"ה בתניא פ\"א)."],["1369","16","וראה מדרש תהלים שבהערה 14."],["1370","17","את\"ל שרש\"י ס\"ל שהי' מן הבלועים. וראה שיחת ש\"פ קרח תשל\"ג. ואכ\"מ."],["1371","18","דלכאורה תיבות אלו מיותרות הן. וב­במדב\"ר (פי\"ח, כ) ליתא. ואף שכ\"ה בשאר המקומות שבהערה 2 — אין זה טעם שרש\"י יעתיקו בפירושו (כמו שלא העתיק מ\"ש בסנהדרין שם \"(וישבו שם) ואמרו שירה\", כיון שאינו שייך ל­פשש\"מ).\nוע\"פ המבואר בפנים מובן מדוע בחר רש\"י בהגירסא \"וישבו\" ולא (כבמגילה שם) \"ועמדו\". וראה הערה 28."],["1372","19","וי\"ל שזוהי גם כוונת רש\"י \"נתבצר להם מקום גבוה כו'\" — והיינו, כפירושו הפשוט, מלשון \"מבצר\", \"ערים בצורות\" (וראה רש\"י סנהדרין שם) — ל' חוזק<sup data-n=\"e33\">*</sup> (ועד\"ז כ' ברע\"ב ובאר מים חיים (לאחי המהר\"ל) כאן), והיינו, ש\"מקום גבוה\" זה גופא הי' אצלם כמו עיר מבצר וחזק, שמזה מובן עוד יותר עד כמה היתה ישיבתם שם בשלוה (והיו יכולים לחיות שם זמן רב)."],["e32","*","והוא כדעת הרא\"ם בכ\"מ, שלפעמים מפרש רש\"י במקום א' לדיעה א' ובמקום שני לפי דיעה אחרת. וכבר נת' כמ\"פ שלכאורה אין זה פשוטו של פרש\"י."],["e33","*","דלא כפרש\"י במגילה שם ד\"נתבצר\" הוא \"לשון גבוה\" (ברש\"י בע\"י \"לשון גובה\"). וראה המשך לשונו בסנה' שם \"התקין להם הקב\"ה מקום גבוה\". ואכ\"מ."]]],[1301430230,"רש\"י<sup data-n=\"1373\">20</sup> \"וישב יעקב — ביקש יעקב לישב בשלוה\"). ומהו ענינו של עונש כזה, ש­הוא דבר והיפוכו — נמצאים באדמה (ב­גיהנם), ושם גופא — במקום \"גבוה\", וב­אופן של \"נתבצר\" (וישיבה בשלוה)?\nוכדי לתרץ שאלה זו מדייק רש\"י \"ובשעת המחלוקת הרהרו תשובה בלבם לפיכך נתבצר להם כו'\" — כלומר: החסרון בתשובתם של בני קרח הי' בכך שהיתה רק הרהור בלב ולא בדיבור בגלוי, באופן שלא נודעה לאיש. ו­אדרבה, תשובתם היתה בשעת המחלוקת, היינו, שלפי ראות עינים עדיין המשיכו במחלוקת, וביחד עם זה עלה בלבם הרהור תשובה.\n[בפרש\"י לתהלים<sup data-n=\"1374\">21</sup> אמנם כתב \"וב­שעת המחלוקת פירשו\" — אבל מזה ש­בפירושו על התורה סתם \"ובשעת המח­לוקת הרהרו תשובה בלבם\" (ולא כתב ש\"פירשו\") מובן, שמפשטות הכתובים (בחומש) משמע שלא פירשו מן המחלו­קת (והטעם בפשטות, שאם פירשו לא היו נבלעים באדמה<sup data-n=\"1375\">22</sup>), ורק הרהרו תשו­בה בלבם<sup data-n=\"1376\">23</sup>].\nולכן הי' עונשם משונה כנ\"ל, כי ה\"ז מדה כנגד מדה: כמו שהנהגתם היתה ב­אופן של דבר והיפוכו, שבפועל ובגלוי לא הי' ניכר שפירשו מהמחלוקת אלא שבסתר מחשבתם והרהורם נבדלו משאר עדת קרח — כך גם עונשם הי' במדה זו, שראו כל ישראל שנענשו בדומה לקרח ועדתו שכמוהם נבלעו באדמה, אלא ששם באופן מובלע בארץ נבדלו מן השאר, \"מקום גבוה בגיהנם וישבו שם\".\nג. ויש לומר, שבזה מתרץ רש\"י ב­דרך אגב (כדרכו) תמי' כללית בפסוק זה — דכל הכתוב \"ובני קרח לא מתו\" מה בעי הכא? סיפור זה שבני קרח לא מתו כי עשו תשובה, מקומו לעיל בפ' קרח, כשהתורה מספרת גופא דעובדא.\nבפשטות יש לומר, כי כאן בפרשתנו הוצרך הכתוב להודיענו שלא מתו, כדי שלא יקשה לן זה שמונה בין משפחות בני לוי את \"משפחת הקרחי\"<sup data-n=\"1377\">24</sup>, ולכן מקדים הכתוב ש\"בני קרח לא מתו\"<sup data-n=\"1378\">25</sup>, וכיון שלא מתו בהבלעם ו\"נתבצר להם מקום גבוה. . וישבו שם\", הרי מסתבר שבמשך הזמן יצאו משם<sup data-n=\"1379\">26</sup>, ומהם יצאו (כפרש\"י לעיל בפ' קרח, כנ\"ל) שמואל הנביא וכ\"ד משמרות כו'.\n[בכמה מפרשי רש\"י<sup data-n=\"1380\">27</sup> כתבו דמ\"ש רש\"י \"נתבצר כו' וישבו שם\", כוונתו שבני קרח נשארו שם לעולם.",[["1373","20","וישב לז, ב סד\"ה אלה."],["1374","21","מב, א."],["1375","22","ולהעיר ממחז\"ל (סנהדרין קט, סע\"ב ואילך) שאון בן פלת, אף שהי' בעצה, ניצל ע\"י אשתו (אלא שרש\"י לא הביאו. וראה שיחת ש\"פ קרח תשל\"ג)."],["1376","23","ולשון רש\"י בפ' קרח \"עשו תשובה\" — י\"ל שקיצר שם בלשונו (כיון שאינו מקומו), וכוונתו כמ\"ש כאן להרהור תשובה בלב."],["1377","24","כו, נח."],["1378","25","ומה שנאמר זה כאן (במנין משפחות בני ראובן), ולא במקומו — ראה לקמן סעיף ה."],["1379","26","ולהעיר שרש\"י כותב ברור \"בגיהנום\". אבל ראה בחיי ועוד כאן, שמקום הבליעה נק' גיהנום. הרשב\"א בהכותב לע\"י מגילה שם."],["1380","27","ראה רא\"ם, ס' זכרון, קצור מזרחי, ועוד."]]],[1301430231,"אבל דבריהם צע\"ג, דמאחר שרש\"י כ' בפירוש שמבני קרח יצאו שמואל ה­נביא וכ\"ד משמרות כו' לפי שעשו תשו­בה, הרי עכצ\"ל שסוף סוף יצאו חיים מן האדמה<sup data-n=\"1381\">28</sup>. ויתירה מזו — מזה שבפרשתנו — בזמן משה נמנית \"משפחת הקרחי\", מוכח שבזמן משה כבר חיו חיי משפחה].\nאבל עדיין אין בזה ישוב לשאלה ה­אמורה — מדוע לא הקדים וכתב הכתוב שבני קרח לא מתו במקומו בפ' קרח, שנשארה \"משפחת הקרחי\"?\nיש מפרשים<sup data-n=\"1382\">29</sup> שזהו \"מפני כבודו של משה שאמר משה<sup data-n=\"1383\">30</sup> ואם בריאה יברא ה' וירדו<sup data-n=\"1384\">31</sup> הם וכל אשר להם וגו', ואם הי' נזכר כאן שבניו לא מתו הי' גנאי למשה שלא הועילה תפלתו שהרי נשארה מהם שארית בארץ\".\nאבל תי' זה צ\"ע, שהרי זה ש\"בני קרח לא מתו\" אינו בסתירה כלל לתפלת משה \"אם בריאה יברא ה' וגו' וירדו גו'\", היות שלפועל נתמלאה תפילתו וגם הם ירדו חיים שאולה, אלא שאח\"כ \"נתבצר להם מקום גבוה בגיהנם\", וא\"כ אין כאן גנאי למשה [ואדרבה, כיון שמשה רצה והשתדל שיעשו תשובה<sup data-n=\"1385\">32</sup>, הרי זה מ­שבחו של משה, שפעל עכ\"פ על בני קרח שיעשו תשובה].\nד. ויש לומר בזה, בהקדם דיוק לשון הכתוב בפ' קרח<sup data-n=\"1384\">31</sup> בעונש הבליעה — \"וירדו הם גו' חיים שאולה ותכס עליהם הארץ ויאבדו מתוך הקהל\", דלכאורה מהו הדיוק \"ויאבדו מתוך הקהל\", ולא סתם \"ויאבדו\", או \"ויאבדו מן הארץ\" וכיו\"ב<sup data-n=\"1387\">33</sup>.\nוע\"פ משנת\"ל בחטאם ותשובתם של בני קרח יש לומר, כי עונש בני קרח הי' רק שנאבדו \"מתוך הקהל\" ההוא<sup data-n=\"1388\">34</sup>, היינו הקהל שראו בעיניהם את השתתפותם בהמחלוקת ואילו את תשובתם לא ראו, שלכן מן ההכרח שיאבדו מתוך קהל זה; משא\"כ קהל אחר (שלא היו עדים בדבר) הרי אין סיבה שיאבדו מתוכו.\nוזהו הטעם שלא נאמר לעיל בפ' קרח ש\"בני קרח לא מתו\" — כי רק לאחרי שכבר לא הי' הקהל שהי' בזמן מחלוקת קרח, כפרש\"י לעיל (בפ' חוקת<sup data-n=\"1389\">35</sup>) שבעדה זו \"לא הי' בהן אחד מאותם שנגזרה גזירה עליהם שכבר כלו מתי מדבר\" — היו יכולים לצאת ממקומם כו', ורק אז נגלה לבנ\"י ש\"בני קרח לא מתו\".\nה. אבל עדיין אין הענין מיושב כל צרכו, כי פסוק זה \"ובני קרח לא מתו\" בא (בסיום מנין משפחות בני ראובן —) בהמשך להסיפור ע\"ד דתן ואבירם בני אליאב (בן פלוא בן ראובן) — \"הוא<sup data-n=\"1390\">36</sup> דתן ואבירם קריאי העדה אשר הצו על משה גו' בהצותם על ה', ותפתח הארץ את פי' ותבלע אותם וגו'\".",[["1381","28","כמ\"ש בנחלת יעקב. וראה גם אמרי שפר, צידה לדרך ועוד. וכ\"כ רש\"י בתהלים מב, א \"ועלו משם\" (ובדברי דוד כאן ועוד, \"שאיזה זמן היו בגיהנום ואח\"כ יצאו על פני הארץ\").\nועפ\"ז מ\"ש רש\"י \"וישבו שם\", אינו מלשון התיישבות (וקביעות) אלא מלשון עכבה (כפרש\"י תזריע יב, ד. וראה רש\"י שמות ב, טו. ועוד. וראה לקו\"ש ח\"ז ע' 80 ואילך ובהערות שם) — שנתעכבו שם משך זמן עד שיצאו."],["1382","29","ש\"ך עה\"ת קרח (טז, לב), ובפרשתנו כאן מבאר הטעם שנאמר באמצע מנין בנ\"י. ע\"ש."],["1383","30","קרח טז, ל."],["1384","31","שם, לג."],["1385","32","ראה רש\"י קרח טז, ח. שם, יב. שם, כה."],["1384","31","שם, לג."],["1387","33","ובכלל תיבות אלו לכאורה מיותרות. וראה ראב\"ע, רמב\"ן ועוד שם."],["1388","34","ואף ששאר האנשים נאבדו לגמרי, שינה הכתוב מפני עונש בני קרח."],["1389","35","כ, כב. וכן לפנ\"ז — כ, א."],["1390","36","פרשתנו כו, ט­י."]]],[1301430232,"ולכאורה, הי' יותר מתאים לכתוב ענין זה במקום שהכתוב מונה את משפחות בני לוי<sup data-n=\"1391\">37</sup>, וביניהן את \"משפחת הקרחי\"<sup data-n=\"1392\">38</sup>.\nבפשטות יש לומר: כיון שהכתוב מספר כאן ע\"ד בליעת דתן ואבירם, לכן מסיים הכתוב בענין הבליעה בקצרה ש­\"בני קרח לא מתו\" (משא\"כ באם הי' נכתב בפרשת משפחות בני לוי, הי' צריך הכתוב לחזור עוה\"פ על דבר ה­מחלוקת והבליעה).\nאבל זהו דוחק קצת מצד תוכן ה­ענינים — כי מאחר שבא הכתוב לרמז תשובתם של בני קרח, שמשום כך לא מתו — הרי אינו מתאים להזכיר את בני קרח בהמשך אחד עם הסיפור ע\"ד הרשעים הללו, דתן ואבירם, שנאבדו הם וכל אשר להם.\nוכדי לתרץ שאלה זו, מקדים רש\"י \"הם היו בעצה תחלה\": זה שהכתוב מצרף את הענין ש\"בני קרח לא מתו\" להסיפור ע\"ד דתן ואבירם, בא ללמדנו על ההשוואה והדמיון ביניהם בחומר המחלוקת — כשם שדתן ואבירם היו אלה \"אשר הצו על משה\", וכפרש\"י \"השיאו את ישראל לריב על משה\", היינו לא רק שהכניסו עצמם בעדת החולקים, אלא שהם \"הצו\" ו\"השיאו\" לריב בתחבולות ועצות לחלוק על משה ועל הקב\"ה [וזה הי' חומר החטא של דתן ואבירם שבגללו נאבדו הם וכל אשר להם, שלא מצינו (מפורש בחומש<sup data-n=\"1393\">39</sup>) עונש כזה במשך כל מ' שנה שהיו ישראל במדבר (וגם לא אצל הר\"ן איש מעדת קרח<sup data-n=\"1394\">40</sup>)] — כמו כן הוא בבני קרח, שגם הם \"היו בעצה תחלה\".\nוזהו גודל הפלא בהענין דבני קרח, שאע\"פ שהיו בעצה תחלה כמו דתן ואבירם, מ\"מ, כיון ש\"הרהרו תשובה בלבם\" נמלטו מהשאול, ועד שיצאו מהם שמואל הנביא וכ\"ד משמרות כו'.\nויש לומר, שענין זה — החילוק בין דתן ואבירם ובני קרח — הוא בהתאם ל­תוכן הכללי של מנין זה של בני ישראל, שהי' \"אחר המגפה\"<sup data-n=\"1395\">41</sup>, וכפרש\"י שהמנין הי' כדי \"לידע מנין הנותרות\"; ובהמשך לזה מספר הכתוב ע\"ד עדת קרח, שמבין אלה שנגזרה עליהם כלי' (שנאבדו הם וכל אשר להם מבלי שנשאר מהם שריד) היו \"נותרים\" — \"ובני קרח לא מתו\".\nו. מכל הנ\"ל יש הוראה בגודל כחה של תשובה — שביכלתה לשנות ולהפוך את האדם מן הקצה אל הקצה:\nבני קרח נמצאו בתחילה בקצה הכי תחתון, וכנ\"ל שהם היו בעצה תחלה, היינו שלא רק שנכשלו בחטא המחלוקת, אלא היו בגדר מחטיאים את הרבים, לחלוק על משה ועל הקב\"ה;\nוגם תשובתם לא היתה תשובה גלוי', ואדרבא הי' רק הרהור תשובה בלב, ובגלוי הייתה — \"בשעת המחלוקת\", ש­הרהור התשובה שלהם לא הי' חזק דיו לפעול עליהם שיפרשו בריש גלי מן המחלוקת.\nואעפ\"כ, הנה לא זו בלבד, שבזכות",[["1391","37","כו, נז ואילך."],["1392","38","וראה ראב\"ע, חזקוני, אוה\"ח ועוד כאן."],["1393","39","ורק בפרש\"י פרשתנו (כו, יג. שם, כד בסופו) נזכר ע\"ד משפחות שנאבדו. ע\"ש. — אבל ג\"ז אינו דומה כלל לעונשם של דתן ואבירם, כפשוט."],["1394","40","כי הם (עכ\"פ) בקשו כהונה, משא\"כ דתן ואבירם שכל כוונתם היתה רק \"הצו\", ריב ומחלוקת עצמם."],["1395","41","פרשתנו כו, א."]]],[1301430233,"הרהור תשובה זה נמלטו מן העונש שבא על עדת קרח, אלא עוד זאת, שגם בעת העונש גופא, בהיותם בלועים בגיהנם, היתה זאת ישיבה מתוך \"שלוה\", במקום גבוה ומבוצר,\nועד שהגיעו לקצה הכי עליון — ש\"אמרו שירה\"<sup data-n=\"1396\">42</sup>, ועוד זאת — שדברי שירתם ותהילתם נכללו בספר תהלים<sup data-n=\"1397\">43</sup>, ועד להשיר<sup data-n=\"1398\">44</sup> ש\"יסודתו בהררי קודש\".\nומזה מובן בכ\"ש וק\"ו וכו' וכו' בנוגע לגאולה העתידה לבא, שפסק הרמב\"ם<sup data-n=\"1399\">45</sup> \"שסוף ישראל לעשות תשובה. . ומיד הן נגאלין\" — שלאחרי ריבוי התומ\"צ מתוך מסירת נפש וכו' במשך אריכות זמן הגלות, די ומספיק לישראל הרהור תשובה בלב להביא תיכף ומיד ממש גאולתן של ישראל — \"ולציון יאמר איש ואיש יולד בה והוא יכוננה עליון\"<sup data-n=\"1400\">46</sup>, ב­גאולה האמיתית והשלימה על ידי משיח צדקנו.\n<span data-k=\"q\">(משיחת ש\"פ פינחס תשל\"ז)</span>",[["1396","42","סנהדרין קי, סע\"א."],["1397","43","ב\"ב טו, רע\"א."],["1398","44","תהלים מזמור פז, א. — ולהעיר שמזמור זה מתחיל \"לבני קרח מזמור שיר\" (דלא ככמה ה­מזמורים שאמרו בני קרח). וי\"ל שהוא ע\"ד מחז\"ל (פסחים קיז, א) \"לדוד מזמור מלמד ששרתה עליו שכינה ואח\"כ אמר שירה\"."],["1399","45","הל' תשובה פ\"ז ה\"ה."],["1400","46","תהלים שם, ה."]]],[1301430234,"<h3>שיחה ג</h3>\nא. בפרשתנו עה\"פ<sup data-n=\"1401\">1</sup> ביום השמיני עצרת תהי' לכם, מעתיק רש\"י מן הכתוב \"עצרת תהי' לכם\" ומפרש: \"עצורים ב­עשיית מלאכה דבר אחר עצרת עצרו מלצאת מלמד שטעון לינה\" (ואח\"כ ממשיך \"ומדרשו באגדה כו'\", כדלקמן ס\"ג).\nוכתב הרא\"ם<sup data-n=\"1402\">2</sup> שפירושו השני של רש\"י (\"עצרו מלצאת\") מקורו בספרי על פסוק זה, \"כדתניא בספרי ביום השמיני עצרת עצרו הכתוב מלצאת הרי שהביא קדשיו מבית פגי לירושלים שומע אני יאכלם בירושלים וילך וילין בבית פגי ת\"ל ביום השמיני עצרת תהי' לכם עצרו הכתוב מלצאת. . אין לי אלא יו\"ט האחרון שעצור מלצאת יו\"ט הראשון מניין ודין הוא הואיל וזה קרוי מקרא קדש וזה קרוי מקרא קדש מה זה עצור מלצאת אף זה עצור מלצאת\".\nולכאורה צ\"ע: כבר נת' כמ\"פ בארו­כה שדרכו של רש\"י, בפירושו על התו­רה, לפרש פשוטו של מקרא, ולא להביא דרשות רז\"ל בפסוקים, ופשיטא שאין לומר שרש\"י מסתמך בפירושו שהלומד יעיין בדברי רז\"ל כדי להבין דבריו, ו­מה גם במקום (כבנדו\"ד) שרש\"י אינו מציין מקורם (\"כדאיתא בספרי\" וכיו\"ב). א\"כ יש להבין מ\"ש רש\"י כאן \"מלמד שטעון לינה\", ואינו מבאר מהותה וענינה של לינה זו — זמנה ומקומה (וטעמה).\nויתירה מזו: רש\"י בפירושו לש\"ס פירש בכ\"מ<sup data-n=\"1403\">3</sup> שהלינה היא במוצאי יו\"ט (ובירושלים<sup data-n=\"1404\">4</sup>), ואם בפירושו לש\"ס צריך רש\"י לפרש זמנה (ומקומה) של לינה זו א\"כ עאכו\"כ שהי' לו לפרש דבר זה ב­פירושו על התורה שהוא לפי פשש\"מ השייך (גם) לבן חמש.\n[ובפרט שבמק\"א בפירושו לש\"ס<sup data-n=\"1405\">5</sup> כ' שזמנה של לינה (בחה\"פ<sup data-n=\"1406\">*5</sup>) הוא (לא ליל מוצאי יו\"ט, אלא) \"לילה הראשון\", היינו שזמן הלינה הוא בלילה הראשון ד­\nיו\"ט<sup data-n=\"1407\">**5</sup> (וכמפורש ברש\"י שם, שדין לינה לא בא לאסור חזרה \"לביתו ממש\" — \"דהא יו\"ט הוא, ועוד דקא בעי לאיתויי עולת ראיי'\" — אלא שאסור ללון \"חוץ לחומה בתוך התחום\")].\nוא\"כ הו\"ל לרש\"י לפרש כאן אם ה­לינה היא בליל יו\"ט או בליל מוצאי יו\"ט.\n[ולדוגמא: כשחל שמע\"צ ביום ה', האם ה\"טעון לינה\" דשמע\"צ כוונתו — הלילה בין יום ד' (כ\"א תשרי) ליום ה' כ\"ב תשרי (היינו מוצאי הושע\"ר, תחלת שמע\"צ), או הלילה בין יום ה' ליום ו' (מוצאי שמע\"צ)].",[["1401","1","כט, לה."],["1402","2","בפרש\"י כאן."],["1403","3","סוכה מז, סע\"א ואילך. חגיגה יז, סע\"א ואילך. ועד\"ז בר\"ה ה, רע\"א (\"ליל חולו של מועד\")."],["1404","4","סוכה שם."],["1405","5","פסחים צה, ב ד\"ה טעון לינה."],["1406","*5","ראה הערה הבאה."],["1407","**5","להעיר משפת אמת לזבחים צז, ב.\nאבל ראה זרע אברהם לספרי ראה (טז, ז) ועוד, שהלינה דליל יו\"ט דפסח הוא מצד הקרבת הק\"פ בי\"ד, וא\"כ הלינה בשאר יו\"ט (מצד קרבנות החג) היא בליל מוצאי יו\"ט."]]],[1301430235,"ועוד: להלן בפ' ראה<sup data-n=\"1408\">6</sup> פירט רש\"י \"שטעון לינה ליל מוצאי יו\"ט\", ולא הסתפק לומר \"מלמד שטעון לינה\", אף ששם לכאורה הוא דבר מובן מעצמו — דהרי מפרש שם הפסוק \"ופנית בבוקר\" — \"לבקרו של שני\" [היינו בוקרו של יום א' דחול המועד], ולכן, גם אם הי' ממשיך לאח\"ז רק \"מלמד שטעון לינה\" (בלי התיבות \"ליל מוצאי יו\"ט\"), הי' מובן שהכוונה ללילה זה — ומ\"מ נחית רש\"י לפרש \"ליל מוצאי יו\"ט\" — ומהו הטעם דכאן השמיטו?\nב. גם צריך להבין: ידוע דכשרש\"י מביא ב' (או יותר) פירושים בכתוב ה\"ז מפני שבכל א' מהפירושים יש קושי מה שאינו בהשני, אלא שהקושי בפי' ה­ראשון אינו גדול כ\"כ כהקושי בפי' השני, ולכן הוא ראשון. וצריך ביאור בנדו\"ד: מהו הקושי בפי' הא' שהוצרך רש\"י להביא פי' שני, ולאידך — במה קשה הפירוש השני (בפשש\"מ) יותר מ­פירוש הראשון.\nיש מפרשים<sup data-n=\"1409\">7</sup> דלפי' הא' קשה \"מאי שנא רגל זה דאיקרי עצרת טפי משאר רגלים, הא כולהו נמי עצורים בעשיית מלאכה\". ולפי' השני קשה \"דהלינה היא בלילה שלאחריו ואיך נאמר שיום החג עצמו נקרא עצרת ע\"ש שטעון לינה (בלילה של)אחריו ועוד דהא יו\"ט ראשון נמי טעון לינה ומה שנא יו\"ט האחרון דאיקרי עצרת טפי מיו\"ט ראשון\".\nאמנם צ\"ע בדבריהם, דהרי הטעם להבאת הפירוש השני הוא (כנ\"ל) משום שלפי פירוש זה מסולקות הקושיות שישנן על הפירוש הראשון, אבל לפי הביאור הנ\"ל, גם לפי' השני ישנה אותה הקושיא שעל הפירוש הראשון<sup data-n=\"1410\">8</sup>: \"מאי שנא יו\"ט האחרון. . מיו\"ט הראשון\"<sup data-n=\"1411\">9</sup>?\nוגם בגוף הקושיא הנ\"ל שעל הפירוש השני צריך ביאור: א) מה שהקשו איך יתכן שיום החג עצמו ייקרא עצרת ע\"ש שהוא טעון לינה בלילה שלאחריו — הרי ברש\"י לא נתפרש כלל זמן הלינה, אם הוא בליל יו\"ט או בלילה שלאחריו (והרי גם בפירושו לש\"ס מצינו דמפרש (או שקורא שמה) דהלינה היא בליל יו\"ט, כנ\"ל), ולמה לא נפרש דקאי על \"ליל יו\"ט\"? ב) ומה שהקשו עוד \"דהא יו\"ט ראשון נמי טעון לינה ומה שנא יו\"ט האחרון כו'\", הרי (בפשוטו של מקרא) לא נתפרש בכתוב (או בפרש\"י) דיו\"ט ראשון טעון לינה<sup data-n=\"1412\">10</sup>.\nג. להלן ממשיך רש\"י \"ומדרשו ב­אגדה לפי שכל ימות הרגל הקריבו",[["1408","6","טז, ז."],["1409","7","משכיל לדוד כאן. וראה גם רע\"ב על פרש\"י כאן."],["1410","8","ואולי אין כוונת המשכיל לדוד לפרש עדי­פות דפי' הא' על פי' השני כ\"א הקושיות שישנן על ב' הפירושים שלכן הוזקק רש\"י להמשיך בפי' (שלישי) ומדרשו באגדה כו'.\nאבל — אין זה משמעות לשונו."],["1411","9","בשפ\"ח: דלטעם ראשון רחוק הוא שהכתוב עצמו יפרש מהו העצרת שהוא עשיית מלאכה לכן פירש דבר אחר. ולפי ד\"א קשה כיון דקאי על ישראל מאי דכתיב עצרת תהי' לכם הי' לו לומר עצורים תהיו.\nאבל א) לא רחוק שהכתוב יפרש עצמו — ראה רא\"ם כאן, ובגו\"א מפרש שהוא עשה ולאו. ב) הקושיא על הפי' הב', שהי' לו לומר עצורים תהיו קשה עד\"ז על הפי' הא'."],["1412","10","דהרי מש\"נ בפ' ראה \"ופנית בבוקר\" ופרש\"י \"מלמד שטעון לינה\" — קאי (בפשש\"מ) רק ביו\"ט ראשון של פסח, וג\"ז רק בשייכות לקרבן פסח די\"ד ניסן, כפשטות המשך הכתובים שם (ראה שם טז, ב ואילך ובפרש\"י), וגם תיבת \"ובשלת\" שב­תחלת הכתוב \"ופנית גו'\" פרש\"י \"זהו צלי אש\", שזהו בק\"פ."]]],[1301430236,"כנגד ע' אומות וכשבאין ללכת אמר להם המקום בבקשה מכם עשו לי סעודה קטנה כדי שאהנה מכם פר אחד כו'<sup data-n=\"1413\">11</sup> התעכבו לי מעט עוד כו'\".\nויש להבין: מאחר שרש\"י כבר הביא ב' פי' ששניהם הם ע\"פ פשש\"מ, מה מכריחו להביא עוד פירוש, ובפרט שהוא \"מדרשו באגדה\" (כדברי רש\"י)? — והרי כלל מפורש הוא בדברי רש\"י \"אני לא באתי אלא לפשוטו של מקרא ול­אגדה המיישבת דברי המקרא דבר דבור על אופניו\"<sup data-n=\"1414\">12</sup>, והיינו דמביא אגדה רק באם \"אנו צריכין לדברי אגדה\"<sup data-n=\"1415\">13</sup>.\nגם: תוכן דרש זה כבר הביאו רש\"י לעיל בפ' אמור עה\"פ<sup data-n=\"1416\">14</sup> \"עצרת היא\". אבל שם לא הביא לפנ\"ז את ב' ה­פירושים שכתב כאן (\"עצורים בעשיית מלאכה\" או \"עצרו מלצאת\"), וגם לא כתב ע\"ז \"מדרשו באגדה\" וכיו\"ב. והיינו דנקט שם שדרש \"עצרתי אתכם אצלי כמלך שזמן את בניו כו'\" הוא הפירוש הפשוט ד\"עצרת היא\".\nוי\"ל הטעם כי מלשון הכתוב שם \"עצרת היא\" — ולא כמ\"ש כאן \"עצרת תהי' לכם\" — מובן שאין זו עצרת ה­מסובבת ונפעלת ע\"י ומצד בנ\"י; ולכן אינו מפרש שלשון זה מורה על ציווי לבנ\"י (עצורים בעשיית מלאכה או עצו­רים מלצאת), אלא מפרשו בשייכות ל­ענינו של היום עצמו, יום שבו — \"עצרתי אתכם אצלי כו'\".\nולפ\"ז גדלה התמי' בפסוק דידן, דמ­כיון שכאן כתיב \"עצרת תהי' לכם\", מהו הצורך לפרשו גם ע\"פ \"מדרשו באגדה\" הנ\"ל.\nד. ויש לומר הביאור בזה:\nהקושי בכתוב כאן (שרש\"י בא ל­תרצו) הוא השינוי כאן בהגדרת היו\"ט דשמע\"צ משאר ימים טובים, שבכל ה­רגלים נאמר בפרשתנו \"מקרא קודש\" [ביום ט\"ו לחודש הראשון (חג הפסח)<sup data-n=\"1417\">15</sup>, ביום השביעי (דחה\"פ)<sup data-n=\"1418\">16</sup>, ביום הבכו­רים<sup data-n=\"1419\">17</sup>, בחודש השביעי באחד לחודש (ר\"ה)<sup data-n=\"1420\">18</sup>, בעשור לחודש השביעי (יו\"כ)<sup data-n=\"1421\">19</sup>, בחמשה עשר יום לחודש השביעי (יום א' דחה\"ס)<sup data-n=\"1422\">20</sup>], וגבי שמע\"צ שינה הכתוב כאן ולא נאמר בו \"מקרא קודש\" אלא \"עצרת תהי' לכם\".\nומזה מוכח שהכתוב (כאן<sup data-n=\"1423\">21</sup>) בא ל­השמיענו שהחג ד\"ביום השמיני\" חלוק",[["1413","11","וע\"ד שנת' כמ\"פ, זה שהתיבות שבאמצע \"פר אחד איל אחד\" נדפסו כד\"ה חדש בפרש\"י הוא ט\"ס, כי זה בא בהמשך הפירוש ד\"מדרשו באגדה\", שסיומו \"התעכבו כו' ולשון חבה הוא זה כו'\", וכמ\"ש בספר זכרון על פרש\"י כאן (וכ\"ה בכמה כת\"י רש\"י שתח\"י).\n[ומה שכ' רש\"י רק \"איל כנגד ישראל\" ולא כ' ד(גם) \"פר כנגד ישראל\"<sup data-n=\"e34\">*</sup> (כבסוכה נה, ב הנסמן בפרש\"י) כי מובן מעצמו, דמאחר דע' פרים הם לנגד ע' אומות (כנ\"ל כט, יח בפרש\"י), פשוט דפר אחד הוא נגד ישראל]."],["1414","12","בראשית ג, ח. ובכ\"מ."],["1415","13","בראשית א, ד. וראה גם שם, א (ד\"ה הב') אין המקרא כו'. ועוד."],["1416","14","כג, לו."],["1417","15","כח, יז­יח."],["1418","16","שם, כה."],["1419","17","שם, כו."],["1420","18","כט, א."],["1421","19","שם, ז."],["1422","20","שם, יב."],["1423","21","אף שבפ' אמור שם, נאמר מקרא קודש בשמע\"צ (כבשאר היו\"ט). וראה לקמן בפנים."],["e34","*","ובכמה כת\"י רש\"י שתח\"י (ודפוסים) איתא \"אלו כנגד ישראל\"."]]],[1301430237,"מכל שאר החגים, שאינו בגדר \"מקרא קודש\" אלא יש בו דין מיוחד ד\"עצרת תהי' לכם\". ובגדרו של דין מיוחד זה מביא רש\"י ב' פירושים:\nפירוש הא' הוא, שדין \"עצרת\" הוא באיסור עשיית מלאכה, שע\"ז ממשיך ב­כתוב \"כל מלאכת עבודה לא תעשו\", ד\"עצרת תהי' לכם\" פירושו שתהיו \"עצורים בעשיית מלאכה\". והיינו שדין איסור מלאכה בשמע\"צ שונה הוא מהאי­סור במועדים אחרים, דאיסור המלאכה בשאר המועדים שייך לקדושת היום, \"מקרא קודש\"<sup data-n=\"1424\">22</sup>, ואילו בשמיני עצרת הוא מחמת ציווי מיוחד: \"עצרת תהי' לכם\", שאי עשיית מלאכה בו הוא מחמת דין וחיוב בפ\"ע \"עצורים בעשיית מלאכה\" (והיינו גדר של העדר ושלילה), ולא מצד \"מקרא קדש\". [ומה שבהפסוק דפ' אמור נאמר מקרא קודש בנוגע לשמיני עצרת, לא נאמר זה בסמיכות ל­\"כל מלאכת עבודה לא תעשו\", כ\"א<sup data-n=\"1425\">23</sup> כהקדמה<sup data-n=\"1426\">24</sup> ל\"והקרבתם אשה לה'\"<sup data-n=\"1427\">25</sup>].\nאמנם פירוש זה קשה קצת, כי כל פרשה זו דמועדים עוסקת בעיקר<sup data-n=\"1428\">26</sup> לא באיסור מלאכה דיו\"ט, כ\"א בקרבנות (מוספים), וא\"כ ק\"ק לפרש שדוקא בפר­שה זו בא הכתוב לחלק בין יום השמיני לשאר הרגלים בענין איסור מלאכה (ש­מקומו המתאים לחידוש זה הוא, לכאו­רה, לעיל בפ' אמור).\nומחמת קושי זה ממשיך רש\"י ומביא פירוש אחר — \"ד\"א עצרת עצרו מל­צאת\", דהיינו שהציווי ד\"עצרת תהי'\" שביום השמיני (אינו מתייחס לאיסור מלאכה דיום זה, אלא) משתייך לקרבנות של חג זה, והיינו מה שבנ\"י עצורים ביום זה מלצאת מלפני ה' (, ממקום הקרבת הקרבנות). ואין רש\"י צריך לפרש מקום המצאם ברגל (שבו \"עצו­רים מלצאת\"), שהרי כבר נתפרש לפנ\"ז בפ' משפטים<sup data-n=\"1429\">27</sup> ופ' תשא<sup data-n=\"1430\">28</sup> \"שלש פעמים בשנה יראה כל זכורך אל (את) פני ה­אדון ה'\", שבשלש הרגלים באים ונמ­צאים לפני ה', בביהמ\"ק ובירושלים, ובז' ימי הסוכות מפורש \"ושמחתם לפני ה\"א שבעת ימים\"<sup data-n=\"1431\">29</sup>, שכבר באו ונמצאו ב­ירושלים במשך ז' הימים — באה התורה להוסיף שיתעכבו שם עוד יום אחד.",[["1424","22","ראה גם (ע\"ד ההלכה) ב\"י לטאו\"ח סתפ\"ז סד\"ה סדר היום. שו\"ע אדה\"ז ריש הל' שבת<sup data-n=\"e35\">*</sup>. וראה קו\"א שם סק\"א דהרמב\"ם \"במנין המצות (בריש ספר היד) מנה שש מצות<sup data-n=\"e36\">**</sup> לשבות ממלאכה בששת ימים טובים מדכתיב מקרא קודש בכל חד וחד ע\"ש\". וראה פרמ\"ג פתיחה להל' יו\"ט פרק הא' סק\"ב וג'."],["1425","23","ראה רע\"ב כאן."],["1426","24","ובפסוק שלאח\"ז שם, לז נאמר כן בנוגע לכל המועדים \"אלה מועדי ה' אשר תקראו אותם מקראי קודש להקריב אשה לה' גו'\"."],["1427","25","להעיר משו\"ע אדה\"ז שם על הגליון לענין חוה\"מ \"שקרוי מקרא קודש לענין הקרבנות בלבד\"."],["1428","26","אף שנזכר בכל חג איסור מלאכה שבו."],["1429","27","כג, יז."],["1430","28","לד, כג."],["1431","29","אמור שם, מ."],["e35","*","ולהעיר מרמב\"ם ריש פ\"ז דהל' יו\"ט לענין חוה\"מ \"הואיל ונקרא מקרא קדש והרי הוא זמן חגיגה במקדש אסור בעשיית מלאכה\"."],["e36","**","ברמב\"ם שם לפנינו (וכן בסהמ\"צ) מנה המצוה דלשבות בימים טובים מהכתוב מקרא קדש — רק בחמש מצות (מ\"ע קנט (א' דפסח), קס (ז' דפסח), קסב (שבועות), קסו (א' דסוכות), קסז (ח' דסוכות)). ובר\"ה (מ\"ע קסג) למדו מהכתוב באחד. . יהי' לכם שבתון. ואולי גריס אדה\"ז ברמב\"ם שם \"וגו'\" (ראה רמב\"ם ספר המדע ירושלים תשכ\"ד), והרי מסיים בהכתוב \"מקרא קדש\". ואולי זוהי הכוונה במ\"ש אדה\"ז \"ע\"ש\". ועצ\"ע (ובפרט שב­סהמ\"צ שם הוסיף \"האי שבתון עשה הוא\"). וראה פרמ\"ג שבפנים ההערה."]]],[1301430238,"אלא שפירוש זה בפ\"ע אינו מספיק, דאי משום הא — אין הכתוב צריך לתאר את יום השמיני בשם \"עצרת תהי' לכם\", כדי ללמד שבנ\"י צריכים להתעכב ב­שמע\"צ בירושלים — כי בעצם הודעת התורה שישנו יום שמיני (בהמשך לחג הסוכות) ש(גם הוא חג האסור בעשיית מלאכה, ו)מביאים בו קרבנות (\"והקרבתם גו'\"), מובן כבר שביום זה מתעכבים ב­ירושלים, ומה נתוסף ע\"י ההדגשה שנק' יום זה בשם \"עצרת תהי' לכם\"?\nולכן ממשיך רש\"י \"מלמד שטעון לינה\", כלומר, השם \"עצרת\" מלמדנו דין חדש באופן ההעכבה, שאין השהיי' ב­ירושלים כמו בשאר ימות הרגל, אלא ש\"טעון לינה\" (שצריכים גם ללון בירו­שלים), משום שביום זה \"עצורים מל­צאת\".\nואולי י\"ל הטעם שלא פירש רש\"י זמן הלינה — כי מכיון שחיוב לינה נלמד ממ\"ש \"עצרת תהי' לכם\", שביום זה \"עצורים מלצאת\", הרי מובן שזמנה של לינה זו הוא בליל שמיני דהרגל<sup data-n=\"1432\">30</sup> (שהוא הנקרא \"שמיני עצרת\", ולא מוצאי יו\"ט). וזהו החידוש בשמע\"צ לגבי שאר רגלים, שבהם יכול (ע\"פ פשש\"מ) ללון בליל הרגל במק\"א מחוץ לירושלים וכיו\"ב, משא\"כ בליל שמע\"צ צריך ללון ב­ירושלים.\n[ועפ\"ז — לפרש\"י, חיוב הלינה דפר­שתנו וחיוב הלינה דפ' ראה הם תרי לינה: דין לינה בפרשתנו הוא בליל שמיני עצרת, ואילו דין לינה הנאמר שם (לגבי יום א' דחג הפסח) הוא ב\"ליל מוצאי יו\"ט\"].\nוענין זה שייך שפיר לפ' קרבנות המוספים שבאים ברגלים, שהם קרבנות צבור הבאים עבור כלל ישראל ב­ביהמ\"ק, ואשר לכן מתעכבים בני ישראל בירושלים בזמן זה<sup data-n=\"1433\">31</sup>.\nאבל פירוש זה, עם היות שמתאים יותר (מהפירוש הא') לכללות תוכן ה­פרשה, אבל מאידך קשה יותר להולמו בפשטות המשך כתוב זה — \"עצרת תהי' לכם כל מלאכת עבודה לא תעשו\" — דמה ענין חיוב לינה לענין איסור מלאכה? ונוסף לזה: לפירוש השני מבואר רק הטעם שגבי שמע\"צ נאמר \"עצרת תהי' לכם\", אבל לא נתיישב — מדוע לא נאמר כאן (בטעם איסור מלאכה) \"מקרא קודש\". ולכן מביאו רש\"י רק כפירוש שני.\nה. ועדיין אין הענין מחוור כל צרכו: שני הפירושים שברש\"י מבארים רק במה הוא ההבדל בין שמע\"צ לגבי שאר הרגלים (אם בזה שאיסור מלאכה שבו הוא רק בגדר \"עצורים בעשיית מלאכה\" או בזה ש\"עצרו מלצאת. . טעון לינה\"), אבל הא גופא טעמא בעי — מדוע באמת שונה יו\"ט זה משאר כל הימים טובים?\nוליישב זאת ממשיך רש\"י \"ומדרשו באגדה לפי כו' וכשבאין ללכת א\"ל",[["1432","30","להעיר מפרש\"י פסחים דלעיל ס\"א (אבל ראה לעיל הערה **5). ולהעיר שגם בספרי כאן יש מפרשים (ראה תולדות אדם לספרי) הכוונה ד­עצורים מלצאת היינו לינה דליל יו\"ט, ולא דמוצאי יו\"ט. וראה שפ\"א שבהערה הנ\"ל."],["1433","31","והיינו שלינה זו הוי כעין הכנה והכשרה של בנ\"י — שמתעכבים ומתיישבים במקומם בירושלים לפני ה', לפני ההקרבה של היום. ומובן גם ב­פשש\"מ שמכינים א\"ע למאורע או דבר חשוב (ע\"ד הנאמר במ\"ת יתרו יט, י (ובפרש\"י) וי\"א). משא\"כ ה\"לינה\" שבפ' ראה, שתוכנה שלא לעזוב המקום (או הפעולה חשובה), ולכן לנים במקומם בירושלים לאחר ההקרבה."]]],[1301430239,"המקום בבקשה כו' התעכבו לי מעט עוד ול' חבה הוא כו' קשה עלי פרידתכם עכבו עוד יום אחד\"<sup data-n=\"1434\">32</sup> — שלפי אגדה זו מוסבר היטב הטעם והסיבה להחילוק בין שמע\"צ וכל היו\"ט [הן באיסור מלאכה (כפירוש הראשון) והן בענין חיוב לינה (כפירוש השני)].\nכלומר: אין כוונת רש\"י כאן להביא פירוש שלישי בתיבת \"עצרת\" (ע\"ד פי­רושו בפ' אמור, שמפרש מ\"ש שם \"עצרת היא\" — \"עצרתי אתכם אצלי כו' עכבו עמי עוד יום אחד\"), אלא שבהבאת אגדה זו כוונתו להסביר<sup data-n=\"1435\">33</sup> שני הפירושים שלפנ\"ז (שלכן לא כתב רש\"י כאן כלשון הכתוב \"עצרתי אתכם\" וכיו\"ב).\nהסברת הענין:\nמאגדה זו מובן, שבעצם הי' היו\"ט צ\"ל רק שבעת ימים, אלא ד\"כשבאין ללכת\" (בסוף שבעת הימים, אזי) אומר להם המקום שיתעכבו עוד יום אחד \"כדי שאהנה מכם\". היינו שיו\"ט זה אינו יום שנתייחד בעצם ובפ\"ע, אלא שהוא בגדר הוספה לחג הסוכות (שנתחדשה \"כשבאין ללכת\").\nוזהו ההסבר בפירוש הראשון, דשאני איסור מלאכה דשמע\"צ מכל שאר היו\"ט — שבשאר היו\"ט הוא (כנ\"ל) בסיבת היותם \"מקרא קדש\", משא\"כ בשמע\"צ (שלא נאמר בו (כאן) \"מקרא קדש\") הוא שלילה, שאיסור המלאכה הוא שצ\"ל \"עצורים בעשיית מלאכה\"<sup data-n=\"1436\">34</sup>\n— כי מכיון ששמע\"צ אינו יו\"ט מצ\"ע, הרי מובן שאין קדושת היום הסיבה להיו\"ט ואיסור מלאכה, אלא להיפך — זה שבנ\"י מקיימים בקשת הקב\"ה (ל­התעכב אצלו על ידי) שיהיו עוצרים עצמם ממלאכה כו', הוי סיבה וגורם ש­היום יתקדש בקדושת יו\"ט;\nועד\"ז לפירוש השני (\"עצרת עצרו מלצאת מלמד שטעון לינה\") — שאגדה זו היא הסברה בחיוב לינה המיוחד בשמע\"צ:\nמכיון שכל תוכנו של יו\"ט זה הוא",[["1434","32","פרטי דיוקי הלשונות בפרש\"י והשינויים לגבי פירושו בפ' אמור, וכן הטעם שהוצרך רש\"י להביא כאן \"ובמדרש רבי תנחומא למדה תורה דרך ארץ כו'\" (ראה לעיל הערה 11 שגם זה הוא המשך לד\"ה זה שבפרש\"י) — נת' בארוכה בההתועדות."],["1435","33","ולכן משנה רש\"י וכותב \"ומדרשו באגדה\", ולא כרגיל \"ומדרש אגדה\"."],["1436","34","ואף שגם בפ' ראה (טז, ח) פי' \"עצרת לה' אלקיך\" (הנאמר בשביעי של פסח) \"עצור עצמך מן המלאכה\" — יש לפרש הכוונה שם, שבא בהמשך למ\"ש בכתובים שלפנ\"ז ע\"ד החיובים בימים ה­קודמים (הפעולות בקשר לקרבן פסח כו', וששת ימים תאכל מצות), אשר בהמשך לזה מפרש רש\"י דמ\"ש \"וביום השביעי עצרת לה\"א\", היינו \"עצור עצמך מן המלאכה\", דהכוונה היא שאין בו מצוות היום כבימים שלפנ\"ז<sup data-n=\"e37\">*</sup>, והציווי אל האדם ביום זה הוא רק — \"עצור עצמך מן המלאכה\" [אבל אין לפרש שם שאיסור מלאכה דשש\"פ לא בא כתוצאה מקדושת היום שהוא \"מקרא קודש\" — שהרי בפ' ראה לא נאמר בשום יו\"ט \"מקרא קודש\" וכל הפרשה מדברת בקרבנות ובשמירת היו\"ט].\nועפ\"ז יש לבאר חילוקי הלשונות בין ב' פירושי רש\"י אלו (בפרשתנו — \"עצורים בעשיית מלאכה\", ובפ' ראה — \"עצור עצמך מן המלאכה\"): בפ' ראה אין המדובר בגדר איסור מלאכה מצד היום, אלא רק ע\"ד החיוב על האדם ביום זה, \"עצור עצמך מן המלאכה\"; משא\"כ בפרשתנו \"עצרת תהי' לכם\" בא הכתוב לתאר גדרו של היום, שהאדם נמצא ביום כזה הפועל שמצבו יהי' \"עצורים בעשיית מלאכה\" [ובפ' אמור שנאמר \"עצרת היא\" — שאינו בשייכות להאדם כלל — מפרש רש\"י שקאי על פעולת הקב\"ה \"עצרתי אתכם אצלי\", כנ\"ל]."],["e37","*","אף שלמעשה, גם בששת הימים שלפנ\"ז אין חובה לאכול מצה (כפרש\"י שם) — הרי זה גופא נלמד מיום השביעי (כפרש\"י שם). ואכ\"מ."]]],[1301430240,"שהקב\"ה מבקש מבנ\"י \"התעכבו לי מעט עוד כו' קשה עלי פרידתכם עכבו עוד יום אחד\", שבנ\"י יהיו יחד עם הקב\"ה \"כדי שאהנה מכם\" — הרי מובן, שבמשך כל יום זה נמצאים עם הקב\"ה, ואין מקום ללון חוץ לירושלים.\n[וע\"פ המדרש אגדה מוטעם עוד יותר הקשר דחיוב לינה לפרשה זו (דקרבנות דרגל) — כי בקשת המקום באה בהמשך לקרבנות דז' ימי החג (שהם כנגד ע' אומות), שמבקש מבנ\"י \"עשו לי סעודה קטנה\" — פר אחד איל אחד דיום השמיני (שכנגד ישראל)].\nו. והנה מב' הפירושים שברש\"י כאן יש ללמוד גם בירור בחלק ההלכה שב­תורה.\nארז\"ל<sup data-n=\"1437\">35</sup> \"שמיני רגל בפני עצמו לענין פז\"ר קש\"ב (פייס בפני עצמו זמן בפני עצמו רגל בפני עצמו כו')\". והנה בפירוש \"רגל בפני עצמו\" מצינו כמה שיטות: במקום אחד בש\"ס<sup data-n=\"1438\">36</sup> פירש רש\"י \"שאין יושבין בסוכה\", ובכ\"מ בש\"ס<sup data-n=\"1439\">37</sup> פי' ש\"אין שם חג הסוכות עליו\"<sup data-n=\"1440\">38</sup>. וה­רמב\"ן<sup data-n=\"1441\">39</sup> הרבה לתמוה על רש\"י, וכ' דפי' רגל בפני עצמו היינו שמתחייב בו ב­ראי' וחגיגה ושמחה כרגל בפני עצמו, ולא מדין תשלומין דראשון, שגם אם הי' חיגר בראשון, דכה\"ג פטור בשני וכו' כיון דהוי תשלומין דראשון, משא\"כ ב­שמיני עצרת הוא מתחייב בראי' וחגיגה דהוי רגל בפני עצמו (וכן יש עוד פירו­שים בראשונים ב\"רגל בפני עצמו\"<sup data-n=\"1442\">40</sup>).\nאמנם לפי דברי רש\"י כאן (בפירוש הראשון) דעצרת פירושו \"עצורים ב­עשיית מלאכה\" מתבאר הגדר ד\"רגל בפני עצמו\" באופן פשוט, שגדר איסור מלאכה שבו ודין רגל שבו אינו באותו גדר ודין רגל דסוכות, וכנ\"ל.\nז. עד\"ז יש ללמוד דבר חדש מפי­רוש השני שברש\"י:\nאף שלפום ריהטא נראה שפירוש זה מקורו בספרי<sup data-n=\"1443\">41</sup>, הרי ע\"פ הנ\"ל מובן, דדין לינה בפי' רש\"י עה\"ת, וגדר לינה המבואר בספרי כאן (וכן בש\"ס) שונים הם לגמרי.\nדהנה בדין דטעון לינה יש ב' אופ­נים<sup data-n=\"1444\">42</sup>, אי מפני הקרבנות שמביא, דקרבן טעון לינה בירושלים; או מחמת היו\"ט, דמפני כבוד יו\"ט<sup data-n=\"1445\">43</sup> טעון לינה:\nבספרי איתא שדין לינה הוא מפני הבאת הקרבן, כמפורש בהתחלת לשון הספרי \"הרי שהביא קדשיו כו'\", שמזה מובן דזה ש\"עצרו הכתוב מלצאת\" הוא מפני הבאת קדשיו.\n[וסוף דברי הספרי \"הואיל וזה קרוי מקרא קדש וזה קרוי מקרא קדש מה זה",[["1437","35","סוכה מז, סע\"ב ואילך. וש\"נ."],["1438","36","סוכה שם (מח, רע\"א)."],["1439","37","ר\"ה ד, ב. יומא ג, רע\"א. ועד\"ז חגיגה יז, א \"שיש לו שם רגל בפני עצמו ואינו קרוי סוכות\"."],["1440","38","ובתוס' ישנים יומא שם: פירש בקונטרס שאומר חג שמיני עצרת הזה. וראה תוס' ר\"ה שם ד\"ה פז\"ר, דמ\"ש רש\"י (שם) \"שאין שם חג הסוכות עליו\" — \"רוצה לומר דבבהמ\"ז ותפלה מזכירין שמיני עצרת ולא סוכות\"."],["1441","39","סוכה שם."],["1442","40","ראה תוד\"ה פז\"ר בר\"ה, יומא וחגיגה שם. תו\"י שם. רמב\"ן שם. ועוד."],["1443","41","כברא\"ם שבתחלת השיחה. וצ\"ע בספר ה­זכרון כאן, שהביא על דברי רש\"י מסוכה (מז, א) כשם ששבעת ימי החג טעונין. . לינה כו'."],["1444","42","ראה תוד\"ה דכתיב חגיגה יז, ב בסופו (תי' הר\"ר אלחנן). ריטב\"א ר\"ה ה, א; סוכה מז, ב. וברמב\"ן סוכה שם משמע דהוי מחלוקת ר\"י ורבנן."],["1445","43","ריטב\"א סוכה שם. ובמאירי שם \"לכבוד היום\"."]]],[1301430241,"עצור כו'\" — אין הכוונה שדין לינה הוא מפני כבוד יו\"ט (מקרא קודש) שבו, אלא שהואיל ושניהם (יו\"ט הראשון ויו\"ט ה­אחרון) נקראים מקרא קודש, למדין ב­היקש מהשני על הראשון. והיינו ד\"זה קרוי מקרא קודש וזה קרוי כו'\", הוא רק לימוד להשוותן זל\"ז בדין \"עצרו מל­צאת\", ולא סיבה וטעם לדין זה].\nוכן מפורש בספרי ראה עה\"פ<sup data-n=\"1446\">44</sup> ופנית בבוקר והלכת לאהלך \"מלמד שטעונים לינה אין לי אלא אלו בלבד מנין לרבות עופות ומנחות יין ולבונה ועצים ת\"ל ופנית בבוקר כל פונות שאתה פונה מן בוקר ואילך\" (אלא דשם נתחדש שדין לינה הוא לא רק בקרבנות שאדם מביא ברגל, אלא דכל קרבן שמביא טעון לי­נה<sup data-n=\"1447\">45</sup>). — ולינה זו היא בלילה שלאחרי הבאת הקרבן<sup data-n=\"1448\">*45</sup>.\nונמצא מבואר מדברי הספרי דחיוב לינה הוא מפני קרבנותיו הפרטיים שמביא ביו\"ט (וכן בשאר ימות השנה).\nאמנם מצינו בראשונים<sup data-n=\"1444\">42</sup> שפירשו שיש דין לינה (גם) מפני היו\"ט, דכבוד יו\"ט מחייב לינה בירושלים.\nולפי טעמים אלו יוקשה מאי טעמא אשמעינן רחמנא \"עצרת, עצרו מלצאת\" דוקא גבי יום שמיני עצרת ולא בקר­בנות דשאר יו\"ט? ויתירה מזו, לאחרי שלמדין ממ\"ש \"ופנית בבוקר והלכת לאהלך\" דכל פינות שאתה פונה מן הבוקר ואילך, דכל קרבן טעון לינה, שוב למה הוצרך הכתוב לומר גבי שמע\"צ \"עצרת תהי' לכם, עצרו הכתוב מלצאת\"<sup data-n=\"1450\">46</sup>?\nאמנם לפי פרש\"י מבואר, דהרי ל­רש\"י \"ופנית בבוקר והלכת לאהלך\" ש­בפ' ראה ו\"עצרת עצרו מלצאת\" דכאן הם שני דינים שונים: דין ופנית בבוקר מדובר בדין לינה מפני הקרבן<sup data-n=\"1451\">47</sup>, ובזה \"טעון לינה ליל מוצאי יו\"ט\", משא\"כ מה שטעון לינה ביום השמיני עצרת \"עצרו מלצאת\" הוא דין בהיום דשמע\"צ, ולפי­כך — א) אינו בשאר רגלים, ב) טעון לינה לא בליל מוצאי יו\"ט, כ\"א בליל יו\"ט (דאף שאינו יכול לצאת מחוץ לתחום וכו', הרי יתכן שיצא מירושלים בתוך התחום<sup data-n=\"1452\">48</sup>). ג) אי\"ז שייך להבאת קדשיו, קרבנות היחיד של כ\"א מישראל (ראי' וחגיגה), כ\"א מחמת קרבנות מוספי היום<sup data-n=\"1453\">49</sup> שהם קרבנות ציבור — פר אחד איל אחד שכנגד כל ישראל.",[["1446","44","טז, ז."],["1447","45","וראה שם פלוגתת ר\"י ורבנן אם פסח שני טעון לינה. ולהעיר מרמב\"ן סוכה שם, דלר\"י \"אין שום קרבן טעון לינה אלא של רגלים בלבד\"."],["1448","*45","וכמ\"ש בתוד\"ה טעון פסחים שם. ועוד. וכ\"כ רש\"י בסוכה שם, סע\"א (בקרבן חגיגה). וראה מפרשי הספרי פרשתנו ופ' ראה שם."],["1444","42","ראה תוד\"ה דכתיב חגיגה יז, ב בסופו (תי' הר\"ר אלחנן). ריטב\"א ר\"ה ה, א; סוכה מז, ב. וברמב\"ן סוכה שם משמע דהוי מחלוקת ר\"י ורבנן."],["1450","46","ולהעיר מקושיית התוס' (ר\"ה שם. ועד\"ז ב­רשב\"א וריטב\"א שם. תוס' וריטב\"א סוכה שם. ועוד) מדוע \"לחג הסוכות אצטריך היקישא\" (לחג המצות) דטעון לינה (ר\"ה שם. וש\"נ), ולא ילפינן (כשמע\"צ בכורים ושאר כל הקרבנות) מדכתיב ופנית. ע\"ש."],["1451","47","וגם זה רק בשייכות לקרבן פסח, כנ\"ל הערה 10."],["1452","48","כפרש\"י פסחים שם."],["1453","49","בריטב\"א ר\"ה שם: דהכתוב הוסיף ברגלים חיוב לינה מדין הרגל (והיינו לימוד דלמדין (ר\"ה שם. וש\"נ) מה חג המצות טעון לינה אף חג הסוכות טעון לינה), אע\"פ שאינו מקריב קרבן והיינו דכתבי' לקרא בפ' חג המצות ולא כתבי' בפ' קרבנות. וצ\"ע לאיזו פרשה כוונתו במ\"ש \"בפ' קרבנות\", והרי לדבריו קרבנות טעונים לינה היינו קרבנות ראי' וחגיגה — קרבנות יחיד (ולא דפרשתנו דמדובר ב­מוספי הרגלים — קרבנות צבור), ובפ' ראה שם (וכן בפ' משפטים ותשא) נזכרים קרבנות ראי' וחגיגה — לא יראה פני ריקם כו'. וצ\"ע."]]],[1301430242,"וי\"ל שבזה מבואר גם זה שבז' הימים שלפנ\"ז לא הי' טעון לינה, כי מכיון שכל ימות הרגל הקריבו כנגד ע' אומות, הרי אף שהיו כל ז' הימים בירושלים אין הכרח שיהי' באופן כזה שיתעכבו שם כל הזמן ולא יצאו ללון.\nח. מיינה של תורה שבפירוש רש\"י:\nידוע מ\"ש רבינו הזקן<sup data-n=\"1454\">50</sup>, ש\"ז' מצות דרבנן. . יוצאות ונמשכות ממצות ה­תורה וכלולות בהן במספר תרי\"ג\".\nועפ\"ז יש לומר, דיו\"ט שני של גליות שהוא מדברי סופרים (ומדברים שנת­חדשו בגלות<sup data-n=\"1455\">51</sup>) נמשך מהחג (דאורייתא) דשמיני עצרת, שבדאורייתא גופא הוא<sup data-n=\"1456\">52</sup> זה שנתוסף על הרגל (מהג' רגלים) ה­מפורשים בתורה<sup data-n=\"1457\">53</sup>. וע\"ד שיו\"ט שני של גליות הוא חידוש של דברי סופרים<sup data-n=\"1458\">54</sup> (חכמי ישראל) — מעין זה הוא גם בחג דשמע\"צ מה\"ת, שענינו הוא שהקב\"ה אומר לבנ\"י — \"בבקשה מכם עשו לי כו' התעכבו כו'\".\nוהנה ביו\"ט שני של גליות מצינו שני קצוות: אין קדושתו חמורה כיו\"ט ראשון<sup data-n=\"1459\">55</sup>, ולאידך ארז\"ל<sup data-n=\"1460\">56</sup> ערבין עלי דברי סופרים, חביבין ד\"ס מדברי תורה, שמזה מובן גם בנוגע ליו\"ט שני של גליות, שיש בו עריבות וחביבות מיוחדת יותר מיו\"ט ראשון<sup data-n=\"1461\">57</sup>.\nומעין שני ענינים אלה מצינו גם בשמיני עצרת — בהתאם לשני הפירו­שים שברש\"י:\nפירוש הא' — עצורים בעשיית מלאכה, מורה שקדושת החג אינה כ\"כ כקדושת ג' הרגלים, שבהם \"כל מלאכה לא תעשו\" הוא תוצאה מזה שהוא מקרא קודש, כנ\"ל באורך;\nובא פירוש השני ברש\"י — שדוקא ב­חג זה יש עריבות וחיבה מיוחדת, \"עצרת עצורים מלצאת. . טעון לינה\", וכהמשך האגדה שבפרש\"י — שאז ישנה ההת­חברות וההתאחדות בין ישראל ואביהם שבשמים, באופן שאא\"פ להפריד ביניהם כלל (גם לא בלילה), עוד יותר משלשת הרגלים.\nוזהו גם הטעם שענין זה בא על ידי עבודת בני ישראל, וכנ\"ל בלשון רש\"י \"אמר להם המקום בבקשה מכם כו'\" — כי שלימות העריבות והחיבה של הקב\"ה מתגלית דוקא בזה שבנ\"י ע\"י עבודתם ויגיעתם מהפכים יום חול שייעשה יום טוב (שמתעכבים עם הקב\"ה)<sup data-n=\"1462\">58</sup>.\nומזה באה הנתינת כח, שגם לאחרי החג, כשכל אחד חוזר לביתו, ואינו לפני",[["1454","50","אגה\"ק סכ\"ט (קנ, א)."],["1455","51","ל' הרמב\"ם הל' יו\"ט פ\"א הכ\"א."],["1456","52","ע\"ד מרז\"ל כל דתיקון רבנן כעין דאורייתא תקנו (פסחים ל, ב. וש\"נ), ובמכש\"כ ממרז\"ל ליכא מידי דלא רמיזא באורייתא (ראה תענית ט, א. זח\"ג פרשתנו רכא, א)."],["1457","53","ועפ\"ז אולי י\"ל (נוסף על המבואר בלקו\"ש ח\"ט ע' 235 בהערה), דלכן הדרוש בענין יו\"ט שני של גליות בא בלקו\"ת בהדרושים דשמע\"צ — אף שיש לפנ\"ז מאמרים דחה\"פ, חה\"ש וסוכות — כי משמע\"צ דוקא נמשך הענין דיו\"ט שני (גם דחה\"פ כו'), כבפנים (ומובן ג\"כ דלכן בשמח\"ת הוא עיקר המעלה דיו\"ט שני, כמבואר בלקו\"ש שם)."],["1458","54","ראה רמב\"ם פ\"א שם ובהלכה כב."],["1459","55","ראה רמב\"ם שם הכ\"ג ואילך. ועוד."],["1460","56","ע\"ז לה, א ובפרש\"י שם. ירושלמי ברכות פ\"א ה\"ד (הובא בר\"ח ע\"ז שם). וש\"נ. שהש\"ר עה\"פ כי טובים דודיך מיין (פ\"א, ב (ב))."],["1461","57","ראה לקו\"ש שם ע' 235 ובהערות שם."],["1462","58","כמו שהוא בנוגע ליו\"ט שני של גליות, שהעילוי שבו הוא מצד עבודתם של ישראל — ראה לקו\"ש שם. חי\"ט ע' 381 ואילך ובהערות."]]],[1301430243,"ה' בירושלים ובבית המקדש, ועסוק \"בכל מלאכתך\" — בעובדין דחול שלו, ה\"ה מתעכב ועצור ועד (— שרק אני ואתם) — דבוק במקום, עד לתכלית ה­התאחדות, עצרת תהי' לכם<sup data-n=\"1463\">59</sup> — ואין ל­זרים אתך — ישראל ומלכא בלחודוהי<sup data-n=\"1464\">60</sup>.\n<span data-k=\"q\">(משיחת ש\"פ פינחס תשכ\"ז)</span>",[["1463","59","ראה שמו\"ר (פט\"ו, כג) בנוגע לכמה ענינים שנאמר בהם \"לכם\" (אלא שלא נזכר שם שמע\"צ). ובסה\"מ עת\"ר (ע' לה. מד), תש\"י (ע' 71. 82) ועוד — מפרשו על שמע\"צ. וראה במדב\"ר פכ\"א, כד. זהר שבהערה הבאה."],["1464","60","זח\"א סד, א­ב. שם רח, ב — הובא ונת' באוה\"ת שמע\"צ (כרך ה) ע' ב'תקמט ואילך. סה\"מ תרפ\"ז (ע' לו ואילך)."]]],[1301430244,"<h3>שיחה א</h3>\nא. בפירושו בריש פרשתנו, לאחרי שרש\"י מפרש הטעם שנאמר \"ראשי ה­מטות לבני ישראל\" — \"חלק כבוד ל­נשיאים ללמדם תחלה ואח\"כ לכל בני ישראל כו'\", כותב: \"ומה ראה לאומרה כאן למד<sup data-n=\"1465\">1</sup> שהפרת נדרים ביחיד מומחה ואם אין יחיד מומחה מפר בשלשה הדיוטות\".\nוצריך ביאור: מלשון רש\"י \"למד<sup data-n=\"1466\">2</sup> שהפרת נדרים ביחיד מומחה כו'\" משמע שאין כאן המקור לגוף הדין דהפרת נדרים<sup data-n=\"1467\">3</sup>, אלא רק לפרט זה שההפרה היא ע\"י \"יחיד מומחה (ואם אין יחיד מומחה מפר בשלשה הדיוטות)\" — ולכאורה, מנא לן בפשוטו של מקרא שיש אפשרות של \"הפרת נדרים\" ע\"י בנ\"א (וחכם), והרי בכל הפרשה מדובר רק ע\"ד הפרת האב נדרי בתו והבעל נדרי אשתו<sup data-n=\"1468\">4</sup>, ולא בהפרת — התרת — נדרים ע\"י חכם ו­כיו\"ב?\nוהרי גם ע\"ד הדרוש וההלכה אי' במשנה<sup data-n=\"1469\">5</sup> \"היתר נדרים פורחין באויר ו­אין להם על מה שיסמוכו\", ופרש\"י \"התרת נדרים שאמרו חכמים שהחכם מתיר את הנדר מעט רמז יש במקרא ואין על מה לסמוך אלא שכן מסור ל­חכמים בתורה שבעל פה\", ופשיטא ש­אינו מפורש בכתוב לפי פשוטו של מקרא!\nוהנה בגמ' שם<sup data-n=\"1469\">5</sup> הובאו דעות כמה תנאים ש\"יש להם על מה שיסמוכו\" מ­כמה כתובים (אבל אינם בפרשת נדרים), ולבסוף הובא מאמר ר\"י אמר שמואל \"שנאמר<sup data-n=\"1471\">6</sup> לא יחל דברו הוא אינו מוחל אבל אחרים מוחלין לו\" (ולימוד זה הובא בפוסקים וכו' כמקור על התרת נדרים<sup data-n=\"1472\">7</sup>). אבל רש\"י בפירושו על התורה בפסוק הנ\"ל מפרש \"לא יחלל דברו לא יעשה דבריו חולין\", ואינו מביא כלל (אפילו לא בתור \"רבותינו דרשו\") הלי­מוד ש\"הוא אינו מוחל אבל אחרים מוחלין לו\".\nב. לכאורה י\"ל, שלשיטת רש\"י",[["1465","1","בדפוס ראשון דפרש\"י \"ומה ראה לומר פרשת נדרים כאן ללמד שהפרת כו'\", והד\"ה בפרש\"י הוא \"וידבר משה\" ולא \"ראשי המטות\" כבפרש\"י שלפנינו."],["1466","2","בכמה כת\"י רש\"י (שתח\"י) \"לפי\" (במקום \"למד\")."],["1467","3","וכדמשמע (לחד מ\"ד) בירושלמי חגיגה פ\"א ה\"ח בתחלתה. ולהעיר מפי' (המיוחס ל)רש\"י נדרים עח, רע\"א."],["1468","4","או הארוס והאב ביחד — ל, ז ואילך ובפרש\"י."],["1469","5","חגיגה י, א."],["1469","5","חגיגה י, א."],["1471","6","פרשתנו ל, ג."],["1472","7","ראה תיב\"ע עה\"פ. שאילתות שאילתא כג (\"ומנלן דאית לי' היתרא לנדרא ולשבועתא מדאורייתא. . אמר קרא לא יחל דברו הוא אינו מוחל כו'\"). רמב\"ם הל' שבועות פ\"ו ה\"ב<sup data-n=\"e38\">*</sup>. ר\"ן נדרים עז, סע\"ב ורא\"ש (עח, רע\"א) שם [וראה ר\"ח חגיגה שם: כלומר יש לו ראי' מן התורה שיש לו רשות להתיר נדרים ואינם כעופות הפורחים באויר כאשר שנינו במשנתנו. וראה ביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג ח\"א עשה קג­קד (שמה, א). וראה מהרש\"א חגיגה שם. רא\"ם לפרש\"י שם בסופו. שיח יצחק לפרש\"י חגיגה שם]."],["e38","*","ומלשון הרמב\"ם שם \"כך למדו ממשה רבינו מפי הקבלה שזה הכתוב לא יחל דברו שלא יחלל הוא בעצמו כו'\" משמע לכאורה שהוא דלא כפרש\"י חגיגה שם. ואכ\"מ."]]],[1301430245,"התרת נדרים ע\"י חכם היא דבר פשוט ע\"פ פשוטו של מקרא, ואין צריך לימוד מיוחד על זה, כי התרת הנדר לפי פשוטו היא ע\"י שפותחים לו פתח לנדרו, שאילו ידע מתחלה שעתיד להיות כך וכך, לא הי' נודר מלכתחלה. וא\"כ אין צריך לחידוש ולימוד מיוחד שחכם יכול להתיר הנדר, כיון שהחכם רק מראה לדעת<sup data-n=\"1473\">8</sup> שהי' כאן טעות בנדר ואדעתא דהכי לא נדר<sup data-n=\"1474\">9</sup>.\nוכן מוכח דעת רש\"י בפירושו לש\"ס, שפירש מאמר ר' יוחנן<sup data-n=\"1475\">10</sup> \"אין חכם מתיר כלום אלא בחרטה\" — \"שפותח<sup data-n=\"1476\">11</sup> פתח לנודר בדברים הבאים לו ע\"י נדר זה שאילו ידע מתחילה שכן עתיד להיות לא הי' נודר נמצא שמתחילתו אינו נדר\".\nומדבריו למדנו ג' דברים בגדר התרת נדרים<sup data-n=\"1477\">12</sup>:\nא) היתר נדרים מעיקרו הוא ע\"י פתח חרטה, דאף שאיתא בש\"ס שהיתרו של נדר הוא בשני אופנים, ע\"י חרטה או ע\"י פתח<sup data-n=\"1478\">13</sup>, מ\"מ עיקרו של היתר נדרים (גם כשתלוי בחרטה) הוא ע\"י פתח לנדרו.\nב) התרת הנדר אינה פעולה הנעשית (עכשיו) ע\"י החכם, אלא מצד הפתח, שע\"י הפתח נמצא שהנדר בטל מאליו<sup data-n=\"1479\">14</sup> (ע\"ד לשון רש\"י במק\"א<sup data-n=\"1480\">15</sup> \"צריך לחכם למצוא פתח לשואל שיהא לו פתחון פה לומר לדעת כן לא נדרתי ואילו הייתי יודע שכן הוא לא הייתי נודר ונמצא נדר נעקר מאליו\").\nג) יתירה מזה: ההתרה אינה בגדר ביטול, אלא הוי גילוי מילתא<sup data-n=\"1481\">16</sup> שאינו נדר מתחילתו, ולכן מדייק רש\"י \"נמצא שמתחילתו אינו נדר\"<sup data-n=\"1482\">17</sup> (ולפ\"ז לרש\"י הא דאמרינן<sup data-n=\"1483\">18</sup> ה\"חכם עוקר את הנדר מ­עיקרו\", אין הפירוש בזה שהחכם מבטל עכשיו את הנדר (למפרע) כאילו לא הי', אלא<sup data-n=\"1484\">19</sup> שמגלה עכשיו שמעיקרא הוי נדר בטעות)<sup data-n=\"1485\">20</sup>.",[["1473","8","משא\"כ בעצמו, שאדם קרוב אצל עצמו ואפשר שיטעה. וראה לקמן הערה 14, 21."],["1474","9","משא\"כ ע\"י חרטה אין מקום להתיר נדר ע\"פ פשט."],["1475","10","גיטין פג, ב."],["1476","11","ד\"ה בחרטה."],["1477","12","ראה צפע\"נ על הרמב\"ם הל' שבועות שם ה\"א."],["1478","13","ראה השקו\"ט ושינויי הגירסאות והפירושים אם פותחים בחרטה או אין פותחין בחרטה — נדרים כא, ב. שם עז, ב. עירובין סד, ב (ורש\"י ותוס' שם), ובמפרשים שם. וראה בכל הנ\"ל (ובהבא לקמן) אנציקלופדי' תלמודית ערך התרת נדרים (ושם ס\"ה­ו). וש\"נ."],["1479","14","וראה שאילתות שם (קרוב לסופה) ובהעמק שאלה שם. ובצפע\"נ הנ\"ל משאילתות: דבאמת הנדר בטל מעצמו רק החכם צריך לומר לו זה. וי\"א דבפתח לא בעי היתר חכם כלל רק שרי לנפשי' כיון דהוי נדר בטעות — הובא ברשב\"א נדרים כב, ב ד\"ה נפק. מאירי שם. ובשער המלך לרמב\"ם הל' שבועות שם ה\"ה שכן היא דעת רש\"י (נדרים סה, א ד\"ה במדין). וראה צפע\"נ שם."],["1480","15","עירובין סד, ב ד\"ה פותחין בחרטה (וראה רש\"י שם ד\"ה אין פותחין. ולהעיר מרש\"י שם ד\"ה אלא לשון)."],["1481","16","ראה הלשון ביד רמה ב\"ב קכ, ב (אות סח)."],["1482","17","ואף שבהמשך הגמ' (גיטין שם) מקשה עד\"ז לגבי הפרת הבעל, דאשה נודרת ובעל מפר, ומתרץ \"כל הנודרת על דעת בעלה היא נודרת\", ובפרש\"י שם \"ואם לאו לא יהא נדר\" — עכצ\"ל דשאני הפרת הבעל, דהרי סו\"ס למסקנא (נזיר כא, ב ואילך) בעל מיגז גייז. וראה ר\"ן נדרים עג, סע\"ב."],["1483","18","כתובות עד, ריש ע\"ב. וראה פרש\"י שם ד\"ה עוקר."],["1484","19","ראה ר\"ן נדרים כא, ב ד\"ה אין חכם מתיר שזהו דוקא ב\"פתח\" ולא ב\"חרטה\". וראה (לענין הא דחכם עוקר את הנדר מעיקרו) ר\"ן שם עה, סע\"א. תוד\"ה מר זוטרא נזיר כב, א (ב\"פתח וחרטה\"). פי' הרא\"ש שם ע\"ב (ב\"חרטה\"). ועוד."],["1485","20","וראה כס\"מ הל' נדרים פי\"ג ה\"ב בביאור דעת הרמב\"ם (ע\"פ רש\"י כתובות שם) \"דלפי זה ענין התרת חכם אינו אלא הוראה שמורה שהוא מותר מאחר שאילו ידע שאירע לו כן לא הי' נודר הוי כאילו פירש שלא נדר ע\"ד כך וא\"כ לא חלה השבועה או הנדר והחכם מורה לו שהוא מותר. . חכם עוקר נדר מעיקרו כו' והחכם מורה שלא חל הנדר מעיקרו\". ולהעיר מתוס' רי\"ד רפ\"ג דנדרים. ועוד. וראה בהנסמן בהערה 12, 13."]]],[1301430246,"ולכן בכלל אין רש\"י צריך לפרש מ­היכן יודעים היתר נדרים, כי אין צורך ללימוד על זה, דפשוט שאם נתגלה ש­הנדר הי' בטעות, הנדר בטל מעיקרו, ומתחלה לא חל ע\"ז החיוב ד\"לא יחל דברו\"<sup data-n=\"1486\">21</sup>. והחידוש בהפרשה הוא רק ב­הפרת נדרים ע\"י האב והבעל, שאינו ע\"י פתח חרטה כו', וע\"ז בא עיקר פרשת נדרים כאן.\nג. ועפ\"ז מובן זה שלא הביא רש\"י הדרש \"הוא אינו מוחל אבל אחרים מוחלין לו\" כי ע\"פ פשש\"מ, לא רק שאין צורך בלימוד זה, אלא שדרש זה אינו מתאים לתוכן ענין התרת נדרים — כי ה­התרה אינה תלוי' באחרים שהם פועלים התרת הנדר.\nואף גוף הדרש \"לא יחל דברו. . אבל אחרים מוחלין לו\" אינו מתאים לענין ההתרה ע\"פ פשטות, שהרי רש\"י פירש \"לא יחל דברו, כמו לא יחלל דברו לא יעשה דבריו חולין\"<sup data-n=\"1487\">22</sup>, וא\"כ אין מקום (עכ\"פ ע\"פ פשט) לדרוש \"אבל אחרים עושין אותו חולין\"<sup data-n=\"1488\">23</sup> (היינו ש­יכול לחלל דברו)<sup data-n=\"1489\">24</sup> — כיון שגדר ה­התרה ע\"פ פשט הוא גילוי מילתא שמעיקרא לא הי' (\"דברו\") דיבור של נדר.\n[וגם לפי פירוש הראשונים<sup data-n=\"1490\">25</sup> בלשון הש\"ס \"אבל אחרים מוחלין לו\" — \"מחי­לה ויחל הכל ענין אחד שלשון לא יחל לא יתיר, והענין כמתיר הקשר שחוזר הענין כאילו לא הי'. . וזהו שאמרו ש­חכם עוקר הנדר מעיקרו ומחילה ג\"כ שעושה את החוב או החטא כאילו לא הי'\" — שמפרש שענין המחילה הוא כמו התרת הקשר, והיינו שהי' קשר ועכשיו מתירו (אלא שלאחרי ההתרה הרי הוא (מעתה) כאילו לא הי') — הרי כיון שיש כאן פעולה של ביטול והתרת הנדר מ­עכשיו<sup data-n=\"1491\">26</sup>, לא יתכן הלשון \"אחרים מוחלין לו\" לפירוש הנ\"ל (ברש\"י) בגדר התרה, שאין זה שנתחדש עתה הביטול, באופן שעכשיו הוא כאילו לא הי', אלא שהוא דבר שבסברא, היינו שאין זה כמו מחילת חוב, אלא גילוי מילתא שלא הי' כאן נדר מעולם].\nד. ברם, ביאור זה יש לו מקום ב­דרך ההלכה שבפירוש רש\"י, אבל לא בביאור פרש\"י עה\"ת לפי פשוטו, שהרי לא מצינו בפשוטו של מקרא חילוקי אופנים דהתרת נדרים ע\"י חכם אם ב­",[["1486","21","ולהעיר שגם ע\"ד ההלכה מצינו דיעה כזו — ראה שו\"ת המבי\"ט ח\"א סי' צח, דנדר הניתר בפתח אין צריך התרה מן התורה, כ\"א מדבריהם. ע\"ש בארוכה. אלא שלדעתו א\"צ היתר חכם כלל. ולדעת רש\"י בפנים (שהביא דין הפרת נדרים ע\"י יחיד מומחה, ובד\"ה שלאח\"ז \"חכם בלשון התרה\", כדלקמן בפנים), גם מה\"ת צריך עכ\"פ לאמירת החכם מותר לך."],["1487","22","ובב' מכת\"י רש\"י (שתח\"י) ממשיך: אלא ינהג בו קדושה. וראה רא\"ם כאן."],["1488","23","כבירושלמי שבהערה 3."],["1489","24","ופי' הר\"ן נדרים שם עז, סע\"ב (וראה גם רא\"ש שם) לכאורה אינו ע\"פ פשט. וראה צ\"צ שבהערה 26. ספרי דבי רב לספרי כאן."],["1490","25","שו\"ת הרשב\"א המיוחסות להרמב\"ן סי' רסב, הובא בב\"י (וב\"ח) יו\"ד סרכ\"ח קרוב לתחלתו."],["1491","26","ראה בארוכה חי' הצ\"צ לש\"ס רפ\"ד ד­גיטין."]]],[1301430247,"חרטה סתם או ע\"י פתח וכיו\"ב, שאין שום רמז בזה בפשש\"מ באופני היתר נדרים.\nויתירה מזו: בפרש\"י עה\"פ \"זה הדבר — מיעוט הוא לומר שהחכם בלשון התרה ובעל (ואב) בלשון הפרה כלשון הכתוב כאן<sup data-n=\"1492\">27</sup>, ואם חלפו אין מותר ואין מופר\", ומדיוק לשונו [ובפרט שרש\"י משנה בזה מלשון הספרי כאן \"זה הדבר אשר צוה ה' הבעל מפר ואין חכם מיפר, חכם מתיר ואין בעל מתיר\" (ועד\"ז הוא הלימוד בגמרא<sup data-n=\"1493\">28</sup>), ומדגיש שהחכם ב­לשון התרה ובעל בלשון הפרה], משמע, שאין חילוק בין בעל (ואב) וחכם בגדר ואופן ביטול הנדר (ופשיטא לא כמש­נת\"ל שבהיתר חכם הוא רק ע\"ד גילוי מילתא שלא הי' נדר מעיקרא, ואין זה מצד ביטולו של החכם) — אלא ששניהם, החכם והבעל, שווים באופן וסוג ביטול הנדר, והחילוק ביניהם הוא רק בלשון<sup data-n=\"1494\">29</sup>.\nולכן יש לומר, שגדרה של התרת נדרים ע\"פ פרש\"י בפשש\"מ שונה מגדרה ע\"פ הלכה, ובהקדם עוד דיוק בלשון רש\"י שכ' בתחלת דבריו \"למד שהפרת נדרים ביחיד מומחה. . מפר כו'\", שלכ­אורה הול\"ל \"שהתרת נדרים ביחיד מומחה כו'\", שהרי החכם מתיר את הנדר דלא כבעל (ואב) שמפר את הנדר — ורש\"י כותב \"שהפרת נדרים\"<sup data-n=\"1495\">30</sup>? ובפרט שמשנה בזה מלשון הספרי כאן \"שאין היתר נדרים אלא מפי מומחים\", שמפו­רש בו \"היתר\" ולא \"הפרה\".\nויש לומר, דס\"ל לרש\"י בפשוטו של מקרא, שהיתר נדרים ע\"י חכם הוא אותו הגדר של הפרת נדרים שע\"י הבעל והאב (המפורש בכתוב), שכשם שהבעל מפר נדרי אשתו והאב נדרי בתו בלי שום טעם<sup data-n=\"1496\">31</sup> ובלי שום פתח וחרטה, כן הוא בהתרת חכם, שגדרה הוא הפרה, בלי פתח וחרטה<sup data-n=\"1497\">32</sup>.\nולכן לא הביא רש\"י לימוד מיוחד ע\"ז, כי ה\"ז מעין הפרה המפורשת ב­פרשה, דכיון שנאמר בריש הפרשה \"וידבר משה אל ראשי המטות\", מובן, שגדרה הוא כעין הפרת הבעל והאב, שכשם שהאשה והבת כשהם ברשות ה­בעל או האב<sup data-n=\"1498\">33</sup>, הרי מרות שלהם עליהן להפר נדריהם — כן הוא ב\"ראשי ה­מטות\", שלהיותם ראשם של אנשי שבטם ניתן להם הכח להפר נדרי בני השבט.\nוהנה גם בכלי יקר<sup data-n=\"1499\">34</sup> קישר שני ה­ענינים, וכתב ה\"טעם להיתר נדרים ב­יחיד מומחה או בג' הדיוטות שנקראו ב\"ד, אנו למדין מן הפרת האב והבעל כי כשם שהאב והבעל לכך יש בידם להפר מטעם שכל אשה ברשות בעלה או ב­רשות אבי' ואין כח בידה לעשות גדולה או קטנה בלתי הסכמתם ודומה כאילו",[["1492","27","ובדפוס ראשון דפרש\"י \"לכך כתב בלשון זה, כלומר בלשון הכתוב כאן, ואם חלפו כו'\"."],["1493","28","נדרים שם עז, סע\"ב ואילך (ושם הוא מב' ברייתות). ב\"ב קכ, ב."],["1494","29","וראה חידושי הצ\"צ שם, שמביא ראי' גם מגמ', דשינוי הלשון דבעל וחכם אינו מורה ע\"ז שבעל מיפר מכאן ולהבא וחכם עוקר מעיקרו. ע\"ש."],["1495","30","ולכאורה דוחק לומר (בפרש\"י) שהוא לאו דוקא אלא דלישנא דקרא נקט (כמ\"ש בתוד\"ה מפירין בכורות לז, רע\"א). ובפרט דתיכף בהמשך הכתוב כתב רש\"י ד\"חכם בלשון התרה ובעל בלשון הפרה\"."],["1496","31","ראה רשב\"ם ב\"ב שם ד\"ה חכם מתיר. ועוד. וראה ט\"ז יו\"ד שם סק\"ד בפי' דברי שו\"ת המיוחסות להרמב\"ן שם. ואכ\"מ."],["1497","32","להעיר גם משו\"ת המבי\"ט שם: ואפשר דמדאורייתא אפילו בלא חרטה הוי מצי למישרי' נדר ושבועה משום דכתיב כו'. ע\"ש."],["1498","33","ראה פרש\"י ל, ד. ט. יוד."],["1499","34","ל, ג ד\"ה לא יחל."]]],[1301430248,"התנו בשעת הנדר ע\"מ שיסכימו הבעל או האב, וכשאינם מסכימים אזי למפרע בטל הנדר כי מסתמא על דעתם נדרה או כאילו נדרה על דעתם<sup data-n=\"1500\">35</sup>, כך כל איש מישראל הוא ברשות ב\"ד ומחוייב לעשות ככל אשר יורו לו הב\"ד וכל נודר ה\"ז כאילו התנה בשעת הנדר ע\"מ שיסכימו הב\"ד עמו וכשאינן מסכימין נעקר הנדר מעיקרו וכל יחיד מומחה נקרא ב\"ד וכל שלשה הדיוטות בידם להתיר נדרו\".\nאבל ע\"פ פשש\"מ דוחק לפרש כן,\nכי<sup data-n=\"1501\">*35</sup> גדר זה דרשות ב\"ד מתאים יותר לסנהדרין וזקני ישראל וכיו\"ב, והוצרך להיות הדיבור (לא אל ראשי המטות, אלא) לסנהדרין, שבעים זקנים וכיו\"ב. ומזה שהדיבור הי' לראשי המטות, ה­נשיאים — נראה יותר (בפשש\"מ) שאין זה מצד שזהו כאילו נדר ע\"מ שיסכימו ב\"ד, אלא מצד מרות הנשיא על שבטו<sup data-n=\"1502\">36</sup>, מעין<sup data-n=\"1503\">*36</sup> בעלות האב והבעל על בתו ו­אשתו.\nה. ע\"פ הנ\"ל יובן גם המשך פרש\"י \"או יכול שלא אמר משה פרשה זו אלא לנשיאים בלבד נאמר כאן זה הדבר ונאמר בשחוטי חוץ<sup data-n=\"1504\">37</sup> זה הדבר מה להלן נאמרה לאהרן ולבניו ולכל בני ישראל שנאמר<sup data-n=\"1504\">37</sup> דבר אל אהרן וגו' אף זו נאמרה לכולן\".\n— והנה מקור הגז\"ש לשחוטי חוץ הוא בגמ'<sup data-n=\"1506\">38</sup>, אבל בגמ' ממשיך \"ומה<sup data-n=\"1507\">39</sup> כאן ראשי המטות אף להלן ראשי ה­מטות בפרשת נדרים למאי הלכתא (בעינן גבי נדרים אהרן ובניו וכל ישר­אל<sup data-n=\"1508\">40</sup>) אר\"א ב\"י להכשיר שלשה הדיוטות (להכי אהני גזירה שוה כאילו נכתב ב­נדרים אהרן ובניו וכל ישראל לומר לך ששקולין כל ישראל להתיר נדרים ו­אפילו הדיוטות<sup data-n=\"1508\">40</sup>), והא ראשי המטות כתיב, אר\"ח כו' ביחיד מומחה. ראשי ה­מטות בשחוטי חוץ למאי הלכתא אמר רב ששת לומר שיש שאלה בהקדש\", והיינו שלפי הגמ' הגז\"ש דפרשת נדרים ושחוטי חוץ היא למילף מיני' שהיתר נדרים יכול להיות גם בשלשה הדיוטות, ושיש שאלה בהקדש.\nאבל רש\"י לא הביא הגז\"ש לענין ההלכתא (שהתרת נדרים בג' הדיוטות) אלא רק לענין זה שפרשה זו \"נאמרה לכולן\" (בהמשך לתחילת פירושו שלכל ישראל נאמרה).\nועפ\"ז צ\"ע למה הוצרך רש\"י להוסיף \"ואם אין יחיד מומחה מפר בשלשה הדיוטות\", דלמאי נפק\"מ הלכה זו לגוף פירושו (שלכל ישראל נאמרה)<sup data-n=\"1510\">41</sup>. וגם צ\"ע, דכיון שמפרש התיבות \"ראשי ה­מטות\" הו\"ל לרש\"י לנקוט בלשון \"מומ­חין\" ולא \"ביחיד מומחה\", וע\"ד לשון הספרי, מקורו של פרש\"י (שחלק כבוד",[["1500","35","ראה הנסמן לעיל הערה 17."],["1501","*35","וגם — לשון הפרת נדרים בפשש\"מ מורה על ביטול הנדר (מכאן ולהבא), ולא עקירתו (מעיקרא)."],["1502","36","להעיר מלקמן ע' 3­202 — בב' הגדרים שישנם בנשיאי השבטים. ע\"ש."],["1503","*36","ולא ממש. וי\"ל שלכן \"חכם בלשון התרה ובעל בלשון הפרה\". ולהעיר מכלי יקר כאן. ואכ\"מ."],["1504","37","אחרי יז, ב."],["1504","37","אחרי יז, ב."],["1506","38","נדרים שם עח, א. ב\"ב קכ, ב."],["1507","39","הלשון מנדרים שם. ועד\"ז הוא בב\"ב שם."],["1508","40","ל' הרשב\"ם ב\"ב שם. וראה גם ר\"ן נדרים שם."],["1508","40","ל' הרשב\"ם ב\"ב שם. וראה גם ר\"ן נדרים שם."],["1510","41","וראה בארוכה במפרשי רש\"י השקו\"ט בדברי רש\"י, וגם בזה שלפי הגמ' הרי הגז\"ש היא לדעת ב\"ה, והלימוד דזה הדבר שהחכם בלשון התרה כו' (שהביא בד\"ה זה הדבר) הוא לדעת ב\"ש (ובתירוצי תוס' ב\"ב שם. מפרשים לנדרים שם). ו­אכ\"מ."]]],[1301430249,"לנשיאים שהם קודמים לעדה) שמסיים \"מגיד שאין היתר נדרים אלא מפי מומחים\" (ולא \"יחיד מומחה\").\n[וגם אינו מוסיף בספרי \"ואם אין יחיד מומחה מתיר בשלשה הדיוטות\" — ואדרבה, הפכו משמע, כפשטות לשון ה­ספרי \"שאין היתר כו' אלא מפי מומ­חים\"].\nאלא שרש\"י לא בא להשמיענו כאן דיני התרת נדרים, אלא להדגיש גדרה ע\"פ פשש\"מ, שהתרת נדרים ע\"י ראשי המטות היא באותו גדר דהפרת נדרים ע\"י הבעל והאב, להיותו נשיא שבט — \"יחיד מומחה\"<sup data-n=\"1511\">*41</sup> (ולא מצד היותם \"מומ­חים\" דעלמא)<sup data-n=\"1512\">**41</sup>; ומזה מובן שהפרת הנדר ע\"י ג' הדיוטות הוא רק ענין של בדיעבד, היינו לא לפי שהתורה רבתה ג' הדיוטות להפרת נדרים מגז\"ש (דאהרן ובניו וכל ישראל) דשחוטי חוץ<sup data-n=\"1513\">42</sup>, שכחם שוה ליחיד מומחה, אבל רק בדוחק ובדיעבד<sup data-n=\"1514\">*42</sup>, \"ואם אין שם יחיד מומחה מפר בשלשה הדיוטות\".\nו. מיינה של תורה שבפרש\"י:\nבתוכן ענין הנדרים, שאדם אוסר על עצמו דבר המותר לו, נאמרו בזה כמה אופנים בחז\"ל, ובדברי הרמב\"ם מצינו בזה ג' הלכות:\nבהל' נדרים<sup data-n=\"1515\">43</sup> כתב הרמב\"ם \"מי ש­נדר נדרים כדי לכונן דעותיו ולתקן מעשיו הרי זה זריז ומשובח, כיצד כגון מי שהי' זולל ואסר עליו הבשר שנה או שתים או מי שהי' כו' כולן דרך עבודה לשם הם ובנדרים אלו וכיוצא בהן אמרו חכמים<sup data-n=\"1516\">44</sup> נדרים סייג לפרישות\";\nובהלכה שלאח\"ז<sup data-n=\"1517\">45</sup> ממשיך \"ואע\"פ שהן עבודה (לשם) לא ירבה אדם בנדרי איסור ולא ירגיל עצמו בהם אלא יפרוש מדברים שראוי לפרוש מהן בלא נדר\";\nובהל' דעות כתב הרמב\"ם<sup data-n=\"1518\">46</sup> \"ציוו חכמים שלא ימנע אדם עצמו אלא מדברים שמנעתו התורה בלבד. . כך אמרו חכמים<sup data-n=\"1519\">47</sup> לא דייך מה שאסרה תורה אלא שאתה אוסר עליך דברים אחרים\".\nהרי לפנינו ג' אופנים בעבודת ה': א) פרישות מדברים המותרים ע\"י נדר. ב) פרישות בלא נדר. ג) לא לפרוש מ­דברים המותרים.\nוידוע הביאור בזה, שהמדובר אודות דרגות שונות בעבודת ה'<sup data-n=\"1520\">48</sup>:\nמי שנמצא בדרגא נמוכה בעבודת ה' זקוק לפרוש א\"ע גם מדברים המותרים, כי מצד המשכתו אחרי מותרות (דברים המותרים) יורד האדם למטה יותר, וכיון",[["1511","*41","להעיר מלשון הירושלמי (נדרים פ\"י ה\"ח): רב הונא ראש לראשי המטות (וראה מפרשי ה­ירושלמי שם)."],["1512","**41","היינו, שגם התרת נדרים ע\"י יחיד מומחה הוא (לא רשות ב\"ד, אלא) להיותו במקום הנשיא (שמרותו על שבטו). ואכ\"מ."],["1513","42","הפירוש בהלימוד (איך למדין מהכתוב דשחוטי חוץ לג' הדיוטות) — ראה במפרשים ל­נדרים ולב\"ב שם."],["1514","*42","ראה ירושלמי שם ב' הדיעות אם ג' הדיו­טות מתירים רק במקום שאין חכם. וראה טושו\"ע יו\"ד סרכ\"ח ס\"א ובפתחי תשובה שם סק\"א."],["1515","43","פי\"ג הכ\"ג."],["1516","44","אבות פ\"ג מי\"ג."],["1517","45","הכ\"ד."],["1518","46","פ\"ג ה\"א."],["1519","47","ירושלמי נדרים פ\"ט ה\"א."],["1520","48","ראה בהבא לקמן (בסגנון תורת החסידות) — לקו\"ת פרשתנו פב, ב. שם פד, ב ואילך. אוה\"ת פרשתנו. ד\"ה וידבר משה אל ראשי המטות כו' עטר\"ת (סה\"מ עטר\"ת ע' תקלז ואילך). ועוד. וראה לקו\"ש ח\"ד ע' 1076 ואילך. חי\"ג ע' 107 ואילך. לקמן ע' 197. ועוד."]]]]});
